  <!-- MODULE 5C: INTERACTIVE 3-LEVEL MINDMAP & LIVE SVG CUTOUT SPOTLIGHT GUIDE -->
  <ReportGuideTutorial
    ref="reportGuideRef"
    v-model="showReportGuideModal"
    :theme-mode="uiTheme === 'dark' ? 'dark' : 'light'"
    :is-mobile="isCompactShell"
    :prepare-step="prepareReportGuideStep"
