<script setup>
defineOptions({ name: 'Report' })
import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import * as XLSX from 'xlsx-js-style'
import { downloadCardFilesAsZip } from '../../utils/cardZipHelper'
import {
  parseCustomerDxmhStandardFromFile,
  parseCustomerQuoteStandardFromFile
} from '../../utils/universalDocumentReader'

import CustomSelect from '../CustomSelect.vue'
import ReportGuideTutorial from './ReportGuideTutorial.vue'

// --- FIREBASE IMPORT ---
import { initializeApp, getApps, getApp } from "firebase/app";
import { getDatabase, ref as dbRef, get, set, update, remove, child, push, onValue } from "firebase/database";

const firebaseConfig = {
  apiKey: "AIzaSyB3fHD_sOqyqVygCxP2gZtvaipr-35a1s8",
  authDomain: "chusonproject.firebaseapp.com",
  databaseURL: "https://chusonproject-default-rtdb.asia-southeast1.firebasedatabase.app",
  projectId: "chusonproject",
  storageBucket: "chusonproject.firebasestorage.app",
  messagingSenderId: "929199941311",
  appId: "1:929199941311:web:ca8d86f9fd7f8dff61480a",
  measurementId: "G-48VVPGFSFK"
};
const firebaseApp = !getApps().length ? initializeApp(firebaseConfig) : getApp();
const database = getDatabase(firebaseApp);

// --- TÍCH HỢP INTERCEPTOR CHO CÁC API KHÁC (Firebase) ---
const firebaseFetch = async (urlInput, options = {}) => {
  let urlStr = typeof urlInput === 'string' ? urlInput : urlInput.toString();
  
  // Bỏ qua nếu là tải ảnh lên imgbb / cloudinary, dùng fetch gốc
  if (urlStr.includes('imgbb.com') || urlStr.includes('cloudinary.com')) {
    return window.fetch(urlInput, options);
  }

  // Nếu không phải là API Google Apps Script, vẫn fetch bình thường
  if (!urlStr.includes('script.google.com') && !urlStr.includes('YOUR_GOOGLE_APPS_SCRIPT_WEB_APP_URL') && urlInput !== API_URL) {
    return window.fetch(urlInput, options);
  }

  // Phân tích URL và payload
  let urlObj;
  try {
    urlObj = new URL(urlStr.startsWith('http') ? urlStr : 'https://fake.com' + urlStr);
  } catch(e) {
    urlObj = new URL('https://fake.com');
  }
  
  let action = urlObj.searchParams.get('action');
  let sheet = urlObj.searchParams.get('sheet');
  let id = urlObj.searchParams.get('id');
  
  let payload = {};
  if (options.body) {
    try {
      payload = JSON.parse(options.body);
      action = payload.action || action;
      sheet = payload.sheet || sheet;
      id = payload.id || id;
    } catch(e) {}
  }

  console.log("Firebase Intercept:", action, sheet, id, payload);

  const jsonResponse = (data) => ({
    json: async () => data,
    text: async () => JSON.stringify(data),
    ok: true,
    status: 200
  });

  try {
    // 1. GET DATA
    if (action === 'get') {
      const targetSheet = sheet || 'REPORT';
      const snap = await get(dbRef(database, targetSheet));
      let data = [];
      if (snap.exists()) {
        const val = snap.val();
        for (const k in val) {
          let item = { ...val[k], id: k };
          delete item.action; // field rác do lưu nhầm, không được mang theo khi gửi update
          
          // Chuẩn hoá key do file Excel bị viết hoa hoặc dùng dấu gạch ngang
          const keyMap = {
            'GHI_CHU': 'ghi_chu',
            'NOI_DUNG': 'noi_dung',
            'PHAN_LOAI': 'phan_loai',
            'TAG': 'tag',
            'THOI_GIAN': 'thoi_gian',
            'TRANG_THAI': 'trang_thai',
            'CREATED_TIME': 'created_time',
            'reminder-time': 'reminder_time',
            'reminder-content': 'reminder_content',
            'reminder-visible': 'reminder_visible',
            'MAKH': 'maKH',
            'ma_khach_hang': 'maKH',
            'maKH': 'maKH',
            'ID_QUANLYFILE': 'id_quanlyfile',
            'id_quan_ly_file': 'id_quanlyfile',
            'id_quanlyfile': 'id_quanlyfile'
          };
          
          for (const oldKey in keyMap) {
            const newKey = keyMap[oldKey];
            if (item[oldKey] !== undefined) {
              item[newKey] = item[oldKey];
            }
          }
          
          data.push(item);
        }
      }
      return jsonResponse({ status: 'success', data });
    }
    
    // 2. DELETE
    if (action === 'delete') {
       if (id) {
         await remove(dbRef(database, `REPORT/${id}`));
       }
       return jsonResponse({ status: 'success' });
    }

    // 3. UPDATES (PIN, PRIORITY, FOLDER)
    if (action === 'update_pin' && payload.id) {
       await update(dbRef(database, `REPORT/${payload.id}`), { pinned: payload.pinned });
       return jsonResponse({ status: 'success' });
    }
    
    if (action === 'update_priority' && payload.id) {
       await update(dbRef(database, `REPORT/${payload.id}`), { priority: payload.priority });
       return jsonResponse({ status: 'success' });
    }

    if (action === 'update_folder' && payload.id) {
       await update(dbRef(database, `kho_luu_tru/${payload.id}`), payload);
       return jsonResponse({ status: 'success' });
    }

    // 4. COMMENTS
    if (action === 'get_comments') {
      const snap = await get(dbRef(database, `REPORT_COMMENTS/${id}`));
      return jsonResponse({ status: 'success', data: snap.exists() ? snap.val() : [] });
    }

    if (action === 'add_comment' && payload.id) {
      // Giả sử mỗi report lưu list comment tại REPORT_COMMENTS/{reportId}/[]
      const snap = await get(dbRef(database, `REPORT_COMMENTS/${payload.id}`));
      let comments = snap.exists() ? snap.val() : [];
      if (!Array.isArray(comments)) comments = Object.values(comments);
      
      const newComment = {
        id: 'CMT_' + Date.now(),
        author: 'User',
        content: payload.content,
        created_time: new Date().toISOString()
      };
      comments.push(newComment);
      await set(dbRef(database, `REPORT_COMMENTS/${payload.id}`), comments);
      return jsonResponse({ status: 'success', data: newComment });
    }

    if (action === 'delete_comment' && payload.id && payload.comment_id) {
      const snap = await get(dbRef(database, `REPORT_COMMENTS/${payload.id}`));
      let comments = snap.exists() ? snap.val() : [];
      if (!Array.isArray(comments)) comments = Object.values(comments);
      
      comments = comments.filter(c => c.id !== payload.comment_id);
      await set(dbRef(database, `REPORT_COMMENTS/${payload.id}`), comments);
      return jsonResponse({ status: 'success' });
    }

    // 5. OTHERS (sync_progress, sync_status, log_activity)
    if (action === 'update' || action === 'sync_progress' || action === 'sync_status') {
      if (payload.id) {
         // Chỉ cập nhật bản ghi ĐÃ TỒN TẠI - tránh việc update() của Firebase tự tạo node mới (gây thêm mới khi kéo thả)
         if (action === 'update') {
           const existSnap = await get(dbRef(database, `REPORT/${payload.id}`));
           if (!existSnap.exists()) {
             console.warn('Bỏ qua update: không tìm thấy REPORT/' + payload.id);
             return jsonResponse({ status: 'error', message: `Không tìm thấy báo cáo ${payload.id}` });
           }
         }
         payload.action = null; // xoá luôn field 'action' cũ (VD: 'add') đang bị lưu trong bản ghi
         // Xoá các key cũ bị viết hoa nếu có để không đè lên dữ liệu mới khi fetch
         const uppercaseKeys = ['GHI_CHU', 'NOI_DUNG', 'PHAN_LOAI', 'TAG', 'THOI_GIAN', 'TRANG_THAI', 'CREATED_TIME', 'reminder-time', 'reminder-content', 'reminder-visible'];
         uppercaseKeys.forEach(k => {
           if (payload[k] !== undefined) {
             payload[k] = null;
           }
         });
         // Khi cập nhật field chữ thường (VD: thoi_gian) thì xoá luôn field viết hoa tương ứng trong DB,
         // nếu không lúc tải lại, giá trị cũ (THOI_GIAN) sẽ đè lên giá trị mới.
         const lowerToUpper = { ghi_chu: 'GHI_CHU', noi_dung: 'NOI_DUNG', phan_loai: 'PHAN_LOAI', tag: 'TAG', thoi_gian: 'THOI_GIAN', trang_thai: 'TRANG_THAI', created_time: 'CREATED_TIME', reminder_time: 'reminder-time', reminder_content: 'reminder-content', reminder_visible: 'reminder-visible', maKH: 'MAKH', id_quanlyfile: 'ID_QUANLYFILE' };
         Object.keys(lowerToUpper).forEach(lk => {
           if (payload[lk] !== undefined) payload[lowerToUpper[lk]] = null;
         });
         await update(dbRef(database, `REPORT/${payload.id}`), payload);
      }
      return jsonResponse({ status: 'success' });
    }
    
    if (action === 'bulk_add' && payload.items) {
      const promises = payload.items.map(item => set(dbRef(database, `REPORT/${item.id}`), item));
      await Promise.all(promises);
      return jsonResponse({ status: 'success' });
    }
    
    if (action === 'add') {
      const pad = n => String(n).padStart(2, '0');
      const d = new Date();
      const newId = `RPT_${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}_${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
      payload.id = newId;
      delete payload.action;
      if (!payload.created_time) payload.created_time = d.toISOString();
      await set(dbRef(database, `REPORT/${newId}`), payload);
      return jsonResponse({ status: 'success', data: payload });
    }
    
    if (action === 'log_activity') {
      const logRef = push(dbRef(database, 'ACTIVITY_LOGS'));
      await set(logRef, payload);
      return jsonResponse({ status: 'success' });
    }
    
    // Fallback cho các action khác chưa định nghĩa
    return jsonResponse({ status: 'success' });

  } catch(error) {
    console.error("Firebase Proxy Error:", error);
    return jsonResponse({ status: 'error', message: error.message });
  }
};



