  isAddingToStorage.value = true
  
  const generateCurrentTime = () => {
    const d = new Date()
    return `${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')} ${d.getDate().toString().padStart(2, '0')}/${(d.getMonth() + 1).toString().padStart(2, '0')}/${d.getFullYear()}`
  }

  const items = pendingStorageFiles.value.map(f => ({
    id: 'FILE_' + Date.now() + Math.floor(Math.random() * 1000) + Math.floor(Math.random() * 1000),
    parents_id: '',
    parents_name: '',
    type: 'file',
    Ten_file: f.name,
    link_file: f.url,
    created_time: generateCurrentTime()
  }))
  
  try {
    const res = await firebaseFetch(`https://script.google.com/macros/s/AKfycbx1yDOQLxYgJb5w30KmxQHF8AYUZln_5q58HCKP4zlUmtJye6aJBiSt3oyT0j_3QaigdQ/exec`, {
      method: 'POST',
      body: JSON.stringify({
        sheet: 'kho_luu_tru',
        action: 'bulk_add',
