// Parse ngày từ chuỗi thời gian backend: "HH:MM /thu /DD/MM/YYYY"
const parseDateFromReport = (thoi_gian) => {
  try {
    const parts = thoi_gian.split(' /');
    if (parts.length === 3) {
      const timePart = parts[0];
      const datePart = parts[2];
      const [hour, minute] = timePart.split(':');
      const [d, m, y] = datePart.split('/');
      return new Date(Number(y), Number(m) - 1, Number(d), Number(hour), Number(minute));
    }
  } catch (e) {
    return null;
  }
};

const getRelativeDateText = (thoi_gian) => {
  if (!thoi_gian) return '';
  const parsed = parseDateFromReport(thoi_gian);
  if (!parsed) {
    const parts = thoi_gian.split(' /');
    if (parts.length === 3) return parts[2];
    return thoi_gian;
  }
  
  const targetDate = new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
  const now = new Date();
  
  const targetTime = targetDate.getTime();
  const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  
  const diffTime = targetTime - todayTime;
  const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
  
  if (diffDays === 0) {
    return 'Hôm nay';
  } else if (diffDays === -1) {
    return 'Hôm qua';
  } else if (diffDays === 1) {
    return 'Ngày mai';
  } else {
    return `${String(parsed.getDate()).padStart(2, '0')}/${String(parsed.getMonth() + 1).padStart(2, '0')}/${parsed.getFullYear()}`;
  }
};

const LAZY_BATCH_SIZE = 25;
const visibleReportCount = ref(LAZY_BATCH_SIZE);
const lazyLoadSentinel = ref(null);
const visiblePendingModalCount = ref(LAZY_BATCH_SIZE);
const pendingModalSentinel = ref(null);

// Phân bổ hạn ngạch hiển thị đồng đều (water-filling) giữa các cột con để tổng số card hiển thị = totalBudget
// nhưng không có cột con nào có dữ liệu mà bị hiển thị 0 card.
const allocateLazyBudgets = (lengths, totalBudget) => {
  const n = lengths.length;
  const totalAvailable = lengths.reduce((sum, len) => sum + len, 0);
  if (totalBudget >= totalAvailable) return [...lengths];
  if (totalBudget <= 0) return new Array(n).fill(0);

  const alloc = new Array(n).fill(0);
  let remaining = totalBudget;
  const active = new Set();
  for (let i = 0; i < n; i++) {
    if (lengths[i] > 0) active.add(i);
  }

  while (remaining > 0 && active.size > 0) {
    const share = Math.max(1, Math.floor(remaining / active.size));
    let progressed = false;
    for (const i of Array.from(active)) {
      if (remaining <= 0) break;
      const cap = lengths[i] - alloc[i];
      if (cap <= 0) {
        active.delete(i);
        continue;
      }
      const take = Math.min(cap, share, remaining);
      if (take > 0) {
        alloc[i] += take;
        remaining -= take;
        progressed = true;
      }
      if (alloc[i] >= lengths[i]) {
        active.delete(i);
      }
    }
    if (!progressed) break;
  }
  return alloc;
};

const navigateToReportDate = (report) => {
  const dObj = parseDateFromReport(report.thoi_gian);
  if (dObj) {
    const yyyy = dObj.getFullYear();
    const mm = String(dObj.getMonth() + 1).padStart(2, '0');
    const dd = String(dObj.getDate()).padStart(2, '0');
    const dateStr = `${yyyy}-${mm}-${dd}`;
    
    filters.value.filterMode = 'day';
    filters.value.dateFrom = dateStr;
    filters.value.dateTo = dateStr;
    filters.value.period = ''; // Hiển thị tất cả các buổi
    
    // Đóng modal
    isPendingModalOpen.value = false;
    
    // Cập nhật highlight cho thẻ được chọn
    highlightedReportId.value = report.id;
    
    // Đảm bảo card mục tiêu nằm trong vùng được render của lazy loading
    nextTick(() => {
      ensureReportVisible(report.id);
    });

    // Cuộn xuống bảng
    scrollToTable();

    // Cuộn tới thẻ tương ứng
    setTimeout(() => {
      ensureReportVisible(report.id);
      nextTick(() => {
        const el = document.getElementById(`report-card-${report.id}`);
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      });
      
      // Xóa highlight sau 1.3 giây
      setTimeout(() => {
        if (highlightedReportId.value === report.id) {
          highlightedReportId.value = null;
        }
      }, 1300);
    }, 300); // Đợi Vue render DOM xong
  } else {
    // Nếu ngày không hợp lệ thì vẫn đóng modal
    isPendingModalOpen.value = false;
  }
}

// Helper định dạng hiển thị thời gian
const formatDisplayTime = (thoi_gian) => {
  if (!thoi_gian) return { time: '', thu: '', date: '', period: '' };
  
  // Xác định Sáng/Chiều dựa vào giờ đầu tiên trong chuỗi
  let periodText = '';
  const firstPart = thoi_gian.trim().split(' ')[0];
  if (firstPart && firstPart.includes(':')) {
    const h = parseInt(firstPart.split(':')[0]);
    if (!isNaN(h)) {
      periodText = h < 12 ? 'Sáng' : 'Chiều';
    }
  }

  const parts = thoi_gian.split(' /');
  if (parts.length === 3) {
    const timePart = parts[0];
    const thuPart = parts[1].trim();
    const datePart = parts[2];
    
    const [h, m] = timePart.split(':');
    const thuText = thuPart === '8' ? 'CN' : `Thứ ${thuPart}`;
    
    return {
      time: `${h} : ${m}`,
      thu: thuText,
      date: datePart.split('/').join(' / '),
      period: periodText
    };
  }
  return { time: thoi_gian, thu: '', date: '', period: periodText };
}

const normalizeReportSearch = (str) => {
  if (!str) return '';
  return String(str)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase()
    .trim();
};

const baseFilteredReports = computed(() => {
  const normQuery = normalizeReportSearch(filters.value.searchQuery);
  let result = reports.value.filter(r => {
    if (r._isGuideDemo) return true;
    if (filters.value.tag && r.tag !== filters.value.tag) return false;
    if (filters.value.phan_loai && r.phan_loai !== filters.value.phan_loai) return false;
    if (filters.value.period) {
      const displayTime = formatDisplayTime(r.thoi_gian);
      if (displayTime.period !== filters.value.period) return false;
    }
    const rMaKH = r.maKH || r.MAKH || r.ma_khach_hang || '';
    if (filters.value.maKH && rMaKH !== filters.value.maKH) return false;
    if (normQuery) {
      const cus = rMaKH
        ? customersList.value.find(c => c.ma_khach_hang === rMaKH || c.id === rMaKH)
        : null;
      const haystack = normalizeReportSearch([
        r.noi_dung,
        r.ghi_chu,
        r.reminder_content,
        rMaKH,
        cus?.ten_khach_hang,
        cus?.ten_cong_ty
      ].filter(Boolean).join(' '));
      if (!haystack.includes(normQuery)) return false;
    }
    
    if (filters.value.filterMode === 'week' && (filters.value.weekFrom || filters.value.weekTo)) {
      const reportDate = parseDateFromReport(r.thoi_gian);
      if (!reportDate) return false;
      if (filters.value.weekFrom) {
        const { from } = getWeekDateRange(filters.value.weekFrom);
        if (reportDate < from) return false;
      }
      if (filters.value.weekTo) {
        const { to } = getWeekDateRange(filters.value.weekTo);
        if (reportDate > to) return false;
      }
    } else if (filters.value.filterMode === 'day' && (filters.value.dateFrom || filters.value.dateTo)) {
      const reportDate = parseDateFromReport(r.thoi_gian);
      if (!reportDate) return false;
      if (filters.value.dateFrom) {
        const from = new Date(filters.value.dateFrom);
        from.setHours(0, 0, 0, 0);
        if (reportDate < from) return false;
      }
      if (filters.value.dateTo) {
        const to = new Date(filters.value.dateTo);
        to.setHours(23, 59, 59, 999);
        if (reportDate > to) return false;
      }
    } else if (filters.value.filterMode === 'month' && (filters.value.monthFrom || filters.value.monthTo)) {
      const reportDate = parseDateFromReport(r.thoi_gian);
      if (!reportDate) return false;
      if (filters.value.monthFrom) {
        const [y, m] = filters.value.monthFrom.split('-');
        const from = new Date(Number(y), Number(m) - 1, 1, 0, 0, 0, 0);
        if (reportDate < from) return false;
      }
      if (filters.value.monthTo) {
        const [y, m] = filters.value.monthTo.split('-');
        const to = new Date(Number(y), Number(m), 0, 23, 59, 59, 999);
        if (reportDate > to) return false;
      }
    } else if (filters.value.filterMode === 'year' && (filters.value.yearFrom || filters.value.yearTo)) {
      const reportDate = parseDateFromReport(r.thoi_gian);
      if (!reportDate) return false;
      if (filters.value.yearFrom) {
        const from = new Date(Number(filters.value.yearFrom), 0, 1, 0, 0, 0, 0);
        if (reportDate < from) return false;
      }
      if (filters.value.yearTo) {
        const to = new Date(Number(filters.value.yearTo), 11, 31, 23, 59, 59, 999);
        if (reportDate > to) return false;
      }
    }
    return true;
  });

  // Sắp xếp
  result.sort((a, b) => {
    const dateA = parseDateFromReport(a.thoi_gian) || 0;
    const dateB = parseDateFromReport(b.thoi_gian) || 0;
    if (filters.value.sortOrder === 'desc') {
      return dateB - dateA;
    } else {
      return dateA - dateB;
    }
  });

  return result;
})

