    link_excel_bao_gia: r.link_excel_bao_gia || '',
    link_excel_mua_hang: r.link_excel_mua_hang || '',
    ten_file_bao_gia: r.ten_file_bao_gia || '',
    ten_file_mua_hang: r.ten_file_mua_hang || '',
    id_pipeline: r.id_pipeline || '',
