const hideReminder = async (report) => {
  const original = report.reminder_visible;
  report.reminder_visible = false;
  try {
    await update(dbRef(database, `REPORT/${report.id}`), { reminder_visible: "FALSE" });
  } catch (error) {
    console.error("Lỗi ẩn nhắc nhở:", error);
    report.reminder_visible = original;
  }
};

const dueReminders = computed(() => {
  const list = [];
  const today = new Date();
  today.setHours(0,0,0,0);
  
  reports.value.forEach(r => {
    if (r.reminder_time && r.reminder_visible !== false && String(r.reminder_visible).toUpperCase() !== 'FALSE') {
      let parts;
      if (r.reminder_time.includes('/')) {
        parts = r.reminder_time.split('/');
      } else {
        parts = r.reminder_time.split('-');
        parts.reverse(); // if YYYY-MM-DD, reverse to DD-MM-YYYY to match parts[2] = YYYY
      }
      
      if (parts && parts.length === 3) {
        const rd = new Date(parts[2], parts[1]-1, parts[0]);
        rd.setHours(0,0,0,0);
        if (rd <= today) {
          list.push(r);
        }
      }
    }
  });
  return list;
});

const filteredReports = computed(() => {
  return baseFilteredReports.value.filter(r => {
    if (filters.value.trang_thai && filters.value.trang_thai !== 'Tất cả') {
      if (filters.value.trang_thai === 'Failed') {
        if (!r.isFailed || (r.isFailed !== true && r.isFailed !== 'TRUE')) return false;
      } else {
        if (r.trang_thai !== filters.value.trang_thai) return false;
      }
    }
    return true;
  });
});

const totalCount = computed(() => baseFilteredReports.value.length)
const pendingCount = computed(() => baseFilteredReports.value.filter(r => r.trang_thai === 'Chưa xử lý').length)
const completedCount = computed(() => baseFilteredReports.value.filter(r => r.trang_thai === 'Hoàn thành').length)
const failedCount = computed(() => baseFilteredReports.value.filter(r => r.isFailed === true || r.isFailed === 'TRUE').length)

const pendingReports = computed(() => filteredReports.value.filter(r => r.trang_thai !== 'Hoàn thành'));
const completedReports = computed(() => filteredReports.value.filter(r => r.trang_thai === 'Hoàn thành'));
const allPendingReports = computed(() => reports.value.filter(r => r.trang_thai !== 'Hoàn thành'));

const pendingFilterMode = ref('all')

const filteredPendingReports = computed(() => {
  let list = [...allPendingReports.value];
  if (pendingFilterMode.value !== 'all') {
    const now = new Date();
    const currentWeek = getWeekString(now);
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    list = list.filter(r => {
      const dObj = parseDateFromReport(r.thoi_gian);
      if (!dObj) return false;
      
      if (pendingFilterMode.value === 'week') {
        return getWeekString(dObj) === currentWeek;
      } else if (pendingFilterMode.value === 'month') {
        return dObj.getMonth() === currentMonth && dObj.getFullYear() === currentYear;
      } else if (pendingFilterMode.value === 'year') {
        return dObj.getFullYear() === currentYear;
      }
      return true;
    });
  }
  
  // Sắp xếp
  list.sort((a, b) => {
    const dA = parseDateFromReport(a.thoi_gian) || new Date(0);
    const dB = parseDateFromReport(b.thoi_gian) || new Date(0);
    if (pendingFilterMode.value === 'old') {
      return dA - dB; // Quá lâu: cũ nhất lên đầu
    } else {
      return dB - dA; // Gần đây, Tất cả...: mới nhất lên đầu
    }
  });

  return list;
});

const isPendingReportToday = (report) => {
  if (!report || !report.thoi_gian) return false;
  const dObj = parseDateFromReport(report.thoi_gian);
  if (!dObj) return false;
  const dStr = `${dObj.getFullYear()}-${String(dObj.getMonth() + 1).padStart(2, '0')}-${String(dObj.getDate()).padStart(2, '0')}`;
  return dStr === getTodayStr();
};

const pendingTodayReports = computed(() => {
  const todayStr = getTodayStr();
  return filteredPendingReports.value.filter(r => {
    const dObj = parseDateFromReport(r.thoi_gian);
    if (!dObj) return false;
    const dStr = `${dObj.getFullYear()}-${String(dObj.getMonth() + 1).padStart(2, '0')}-${String(dObj.getDate()).padStart(2, '0')}`;
    return dStr === todayStr;
  });
});

const pendingOtherReports = computed(() => {
  const todayStr = getTodayStr();
  return filteredPendingReports.value.filter(r => {
    const dObj = parseDateFromReport(r.thoi_gian);
    if (!dObj) return true;
    const dStr = `${dObj.getFullYear()}-${String(dObj.getMonth() + 1).padStart(2, '0')}-${String(dObj.getDate()).padStart(2, '0')}`;
    return dStr !== todayStr;
  });
});

// Lazy loading cho Modal Việc chưa hoàn thành (25 công việc mỗi đợt)
const pendingModalBudgets = computed(() => {
  return allocateLazyBudgets(
    [pendingOtherReports.value.length, pendingTodayReports.value.length],
    visiblePendingModalCount.value
  );
});

const visiblePendingOtherReports = computed(() => {
  return pendingOtherReports.value.slice(0, pendingModalBudgets.value[0]);
});

const visiblePendingTodayReports = computed(() => {
  return pendingTodayReports.value.slice(0, pendingModalBudgets.value[1]);
});

const visiblePendingMobileReports = computed(() => {
  return filteredPendingReports.value.slice(0, visiblePendingModalCount.value);
});

const currentlyRenderedPendingCount = computed(() => {
  return Math.min(filteredPendingReports.value.length, visiblePendingModalCount.value);
});

const hasMorePendingModalReports = computed(() => {
  return currentlyRenderedPendingCount.value < filteredPendingReports.value.length;
});

const loadMorePendingModalReports = () => {
  if (visiblePendingModalCount.value < filteredPendingReports.value.length) {
    visiblePendingModalCount.value = Math.min(
      filteredPendingReports.value.length,
      visiblePendingModalCount.value + LAZY_BATCH_SIZE
    );
  }
};

const showAllPendingModalReports = () => {
  visiblePendingModalCount.value = Math.max(LAZY_BATCH_SIZE, filteredPendingReports.value.length);
};

const onDropToToday = async (e) => {
  const id = draggedReportId.value;
  if (!id) return;
  const report = reports.value.find(r => r.id === id);
  if (report) {
    if (API_URL === 'YOUR_GOOGLE_APPS_SCRIPT_WEB_APP_URL') {
       alert("Tính năng này cần cấu hình API_URL");
       return;
    }
    const originalTime = report.thoi_gian;
    
    const now = new Date();
    const timeObj = parseTimeString(report.thoi_gian);
    if (!timeObj) return;
    
    timeObj.day = String(now.getDate()).padStart(2, '0');
    timeObj.month = String(now.getMonth() + 1).padStart(2, '0');
    timeObj.year = String(now.getFullYear());
    const dayOfWeek = now.getDay();
    timeObj.thu = dayOfWeek === 0 ? '8' : String(dayOfWeek + 1);
    
    const newTimeStr = `${timeObj.hour}:${timeObj.minute} /${timeObj.thu} /${timeObj.day}/${timeObj.month}/${timeObj.year}`;
    if (newTimeStr === originalTime && (!report.isFailed || report.isFailed === '')) return;
    
    const originalIsFailed = report.isFailed;
    report.thoi_gian = newTimeStr;
    report.isFailed = '';

    droppedReportId.value = report.id;
    setTimeout(() => {
      if (droppedReportId.value === report.id) droppedReportId.value = null;
    }, 800);
    
    try {
      const response = await firebaseFetch(API_URL, {
        method: 'POST',
        body: JSON.stringify({ ...report, action: 'update' })
      });
      const result = await response.json();
      if (result.status !== 'success') {
        report.thoi_gian = originalTime;
        report.isFailed = originalIsFailed;
        alert('Lỗi cập nhật: ' + result.message);
      }
    } catch (error) {
      report.thoi_gian = originalTime;
      report.isFailed = originalIsFailed;
      alert('Lỗi kết nối: ' + error.message);
    }
  }
};

const moveToToday = async (report) => {
  if (!report) return;
  if (API_URL === 'YOUR_GOOGLE_APPS_SCRIPT_WEB_APP_URL') {
     showToast('Tính năng này cần cấu hình API_URL', 'warning');
     return;
  }
  const originalTime = report.thoi_gian;
  
  const now = new Date();
  const timeObj = parseTimeString(report.thoi_gian);
  if (!timeObj) return;
  
  timeObj.day = String(now.getDate()).padStart(2, '0');
  timeObj.month = String(now.getMonth() + 1).padStart(2, '0');
  timeObj.year = String(now.getFullYear());
  const dayOfWeek = now.getDay();
  timeObj.thu = dayOfWeek === 0 ? '8' : String(dayOfWeek + 1);
  
  const newTimeStr = `${timeObj.hour}:${timeObj.minute} /${timeObj.thu} /${timeObj.day}/${timeObj.month}/${timeObj.year}`;
  if (newTimeStr === originalTime && (!report.isFailed || report.isFailed === '') && report.trang_thai !== 'Failed') return;

  const oldFmt = formatDisplayTime(originalTime);
  const newFmt = formatDisplayTime(newTimeStr);
  const oldLabel = [oldFmt.time, oldFmt.dayOfWeek, oldFmt.date].filter(Boolean).join(' • ') || originalTime;
  const newLabel = [newFmt.time, newFmt.dayOfWeek, newFmt.date].filter(Boolean).join(' • ') || newTimeStr;

  const confirmed = await enqueueBaogiaDialog({
    mode: 'confirm',
    variant: 'info',
    title: 'Chuyển sang làm hôm nay?',
    eyebrow: 'XÁC NHẬN DỜI LỊCH CÔNG VIỆC',
    targetLabel: report.noi_dung || `Báo cáo #${report.id}`,
    targetMeta: `Lịch cũ: ${oldLabel}  →  Hôm nay: ${newLabel}`,
    message: 'Xác nhận chuyển thời gian thực hiện công việc này sang ngày hôm nay?',
    confirmText: 'Chuyển sang hôm nay',
    cancelText: 'Huỷ bỏ'
  });
  if (!confirmed) return;
  
  const originalIsFailed = report.isFailed;
  const originalStatus = report.trang_thai;
  report.thoi_gian = newTimeStr;
  report.isFailed = '';
  if (report.trang_thai === 'Failed') {
    report.trang_thai = 'Chưa xử lý';
  }

  droppedReportId.value = report.id;
  setTimeout(() => {
    if (droppedReportId.value === report.id) droppedReportId.value = null;
  }, 800);
  
  try {
    const response = await firebaseFetch(API_URL, {
      method: 'POST',
      body: JSON.stringify({ ...report, action: 'update' })
    });
    const result = await response.json();
    if (result.status !== 'success') {
      report.thoi_gian = originalTime;
      report.isFailed = originalIsFailed;
      report.trang_thai = originalStatus;
      showToast('Lỗi cập nhật: ' + result.message, 'error');
    } else {
      showToast('Đã chuyển công việc sang hôm nay', 'success');
    }
  } catch (error) {
    report.thoi_gian = originalTime;
    report.isFailed = originalIsFailed;
    report.trang_thai = originalStatus;
    showToast('Lỗi kết nối: ' + error.message, 'error');
  }
};

// View mode: 'detail' (kanban) or 'daily' (single column by day)
const desktopViewMode = ref('detail');

const kanbanColumns = computed(() => {
  const pMorning = pendingReports.value.filter(r => formatDisplayTime(r.thoi_gian).period === 'Sáng');
  const pAfternoon = pendingReports.value.filter(r => formatDisplayTime(r.thoi_gian).period !== 'Sáng');
  const cMorning = completedReports.value.filter(r => formatDisplayTime(r.thoi_gian).period === 'Sáng');
  const cAfternoon = completedReports.value.filter(r => formatDisplayTime(r.thoi_gian).period !== 'Sáng');

  const [bPM, bPA, bCM, bCA] = allocateLazyBudgets(
    [pMorning.length, pAfternoon.length, cMorning.length, cAfternoon.length],
    visibleReportCount.value
  );

  const pendingCol = {
    status: 'Chưa xử lý',
    title: filters.value.trang_thai === 'Failed' ? 'THẤT BẠI (FAILED)' : 'CHƯA XỬ LÝ',
    dotClass: filters.value.trang_thai === 'Failed' ? 'bg-rose-500 shadow-rose-500/50' : 'bg-amber-500 shadow-amber-500/50',
    reports: pendingReports.value,
    morningReports: pMorning.slice(0, bPM),
    morningTotal: pMorning.length,
    afternoonReports: pAfternoon.slice(0, bPA),
    afternoonTotal: pAfternoon.length
  };
  const doneCol = {
    status: 'Hoàn thành',
    title: 'HOÀN THÀNH',
    dotClass: 'bg-emerald-500 shadow-emerald-500/50',
    reports: completedReports.value,
    morningReports: cMorning.slice(0, bCM),
    morningTotal: cMorning.length,
    afternoonReports: cAfternoon.slice(0, bCA),
    afternoonTotal: cAfternoon.length
  };
  if (filters.value.trang_thai === 'Hoàn thành') return [doneCol];
  if (filters.value.trang_thai === 'Chưa xử lý' || filters.value.trang_thai === 'Failed') return [pendingCol];
  return [pendingCol, doneCol];
});

const dailyColumns = computed(() => {
  const grouped = {};
  
  // 1. Tạo sẵn các ngày trống trong phạm vi bộ lọc
  let startDate = null;
  let endDate = null;
  
  try {
    if (filters.value.filterMode === 'week') {
      if (filters.value.weekFrom) startDate = getWeekDateRange(filters.value.weekFrom).from;
      if (filters.value.weekTo) endDate = getWeekDateRange(filters.value.weekTo).to;
    } else if (filters.value.filterMode === 'day') {
      if (filters.value.dateFrom) startDate = new Date(filters.value.dateFrom);
      if (filters.value.dateTo) endDate = new Date(filters.value.dateTo);
    } else if (filters.value.filterMode === 'month') {
      if (filters.value.monthFrom) {
        const [y, m] = filters.value.monthFrom.split('-');
        startDate = new Date(y, parseInt(m)-1, 1);
      }
      if (filters.value.monthTo) {
        const [y, m] = filters.value.monthTo.split('-');
        endDate = new Date(y, parseInt(m), 0);
      }
    } else if (filters.value.filterMode === 'year') {
      if (filters.value.yearFrom) startDate = new Date(filters.value.yearFrom, 0, 1);
      if (filters.value.yearTo) endDate = new Date(filters.value.yearTo, 11, 31);
    }
    
    if (startDate && endDate && !isNaN(startDate.getTime()) && !isNaN(endDate.getTime())) {
      startDate.setHours(0,0,0,0);
      endDate.setHours(0,0,0,0);
      let d = new Date(startDate);
      let count = 0;
      while (d <= endDate && count < 366) {
        const yyyy = d.getFullYear();
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        const dateKey = `${yyyy}-${mm}-${dd}`;
        
        const dayOfWeek = d.getDay() + 1;
        const thuLabel = dayOfWeek === 1 ? 'CN' : `Thứ ${dayOfWeek}`;
        
        grouped[dateKey] = {
          dateKey,
          dateObj: new Date(d),
          dateLabel: `${dd} / ${mm} / ${yyyy}`,
          thuLabel,
          morning: [],
          afternoon: []
        };
        
        d.setDate(d.getDate() + 1);
        count++;
      }
    }
  } catch(e) { console.error("Lỗi tạo ngày trống", e); }
  
  // 2. Điền dữ liệu thật vào
  filteredReports.value.forEach(r => {
    const parsed = parseDateFromReport(r.thoi_gian);
    if (!parsed) return;
    const dateKey = `${parsed.getFullYear()}-${String(parsed.getMonth()+1).padStart(2,'0')}-${String(parsed.getDate()).padStart(2,'0')}`;
    if (!grouped[dateKey]) {
      const display = formatDisplayTime(r.thoi_gian);
      grouped[dateKey] = {
        dateKey,
        dateObj: new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate()),
        dateLabel: display.date,
        thuLabel: display.thu,
        morning: [],
        afternoon: []
      };
    }
    const ft = formatDisplayTime(r.thoi_gian);
    if (ft.period === 'Sáng') grouped[dateKey].morning.push(r);
    else grouped[dateKey].afternoon.push(r);
  });
  const arr = Object.values(grouped);
  arr.sort((a, b) => filters.value.sortOrder === 'desc' ? b.dateObj - a.dateObj : a.dateObj - b.dateObj);
  return arr;
});

// Lazy loading cho chế độ Xem theo ngày, Mobile và toàn trang (25 công việc mỗi đợt)
const visibleDailyColumns = computed(() => {
  const allDays = dailyColumns.value;
  const totalTasksAllDays = filteredReports.value.length;
  const result = [];
  let remainingTasks = visibleReportCount.value;
  let emptyDaysIncluded = 0;
  const maxEmptyDaysWhenPaginated = Math.max(14, visibleReportCount.value);

  for (const day of allDays) {
    const mLen = day.morning.length;
    const aLen = day.afternoon.length;
    const dayTotal = mLen + aLen;

    if (dayTotal === 0) {
      // Nếu tất cả công việc đã hiển thị hết (hoặc tổng <= budget), hiển thị các ngày trống trong phạm vi lọc
      if (totalTasksAllDays <= visibleReportCount.value || remainingTasks > 0) {
        if (emptyDaysIncluded < maxEmptyDaysWhenPaginated || totalTasksAllDays <= visibleReportCount.value) {
          result.push({
            ...day,
            morning: [],
            morningTotal: 0,
            afternoon: [],
            afternoonTotal: 0,
            totalTasks: 0
          });
          emptyDaysIncluded++;
        }
      }
      continue;
    }

    if (remainingTasks <= 0) break;

    const dayBudget = Math.min(dayTotal, remainingTasks);
    const [mBudget, aBudget] = allocateLazyBudgets([mLen, aLen], dayBudget);
    remainingTasks -= (mBudget + aBudget);

    result.push({
      ...day,
      morning: day.morning.slice(0, mBudget),
      morningTotal: mLen,
      afternoon: day.afternoon.slice(0, aBudget),
      afternoonTotal: aLen,
      totalTasks: dayTotal
    });
  }

  return result;
});

const visibleMobileReports = computed(() => {
  return filteredReports.value.slice(0, visibleReportCount.value);
});

const currentlyRenderedCount = computed(() => {
  return Math.min(filteredReports.value.length, visibleReportCount.value);
});

const hasMoreReports = computed(() => {
  return currentlyRenderedCount.value < filteredReports.value.length;
});

const loadMoreReports = () => {
  if (visibleReportCount.value < filteredReports.value.length) {
    visibleReportCount.value = Math.min(
      filteredReports.value.length,
      visibleReportCount.value + LAZY_BATCH_SIZE
    );
  }
};

const showAllReports = () => {
  visibleReportCount.value = Math.max(LAZY_BATCH_SIZE, filteredReports.value.length);
};

const ensureReportVisible = (reportId) => {
  if (!reportId) return;
  const idx = filteredReports.value.findIndex(r => String(r.id) === String(reportId));
  if (idx === -1) return;
  // Tăng visibleReportCount đủ lớn để đảm bảo card ở mọi cột con đều đã được render
  const requiredBatches = Math.ceil(( filteredReports.value.length ) / LAZY_BATCH_SIZE);
  if (idx >= Math.floor(visibleReportCount.value / 4)) {
    visibleReportCount.value = Math.max(
      visibleReportCount.value,
      Math.min(
        filteredReports.value.length,
        Math.ceil(((idx + 1) * 4) / LAZY_BATCH_SIZE) * LAZY_BATCH_SIZE
      )
    );
  }
  // Kiểm tra chắc chắn lần nữa xem card đã nằm trong kanbanColumns chưa
  const inKanban = kanbanColumns.value.some(col =>
    col.morningReports.some(r => String(r.id) === String(reportId)) ||
    col.afternoonReports.some(r => String(r.id) === String(reportId))
  );
  if (!inKanban) {
    visibleReportCount.value = Math.max(LAZY_BATCH_SIZE, filteredReports.value.length);
  }
};

const draggedReportId = ref(null);
const draggedReminderId = ref(null);
const activeReminderForNewReport = ref(null);
const droppedReportId = ref(null);
const dragOverColumn = ref(null); // track cột đang hover khi kéo

const onDragStartReport = (e, report) => {
  if (e?.target?.closest && e.target.closest('button, a, input, textarea, select, .bg-dcard-files-wrap, .bg-dcard-actions, .bg-dcard-pipelines')) {
    e.preventDefault();
    return;
  }
  draggedReminderId.value = null;
  droppedReportId.value = null;
  highlightedReportId.value = null;
  draggedReportId.value = report.id;
  if (e?.dataTransfer) {
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', report.id);
  }
};

const onDragStartReminder = (e, reminder) => {
  draggedReportId.value = null;
  draggedReminderId.value = reminder.id;
  e.dataTransfer.effectAllowed = 'copy';
  e.dataTransfer.setData('text/plain', 'reminder:' + reminder.id);
};

const onDragEndReport = () => {
  draggedReportId.value = null;
  draggedReminderId.value = null;
  dragOverColumn.value = null;
};

const onDragEnterColumn = (status, period) => {
  if (draggedReportId.value || draggedReminderId.value) dragOverColumn.value = status + '-' + period;
};

const onDragLeaveColumn = (e, colEl) => {
  // Chỉ clear khi thực sự rời khỏi column (không phải vào card con)
  if (colEl && colEl.contains && colEl.contains(e.relatedTarget)) return;
  dragOverColumn.value = null;
};

// Tạo chuỗi thoi_gian "HH:MM /thu /DD/MM/YYYY" từ ngày + buổi
const buildThoiGian = (dateObj, period) => {
  const hh = period === 'Sáng' ? '08' : '14';
  const dow = dateObj.getDay();
  const thu = dow === 0 ? 8 : dow + 1;
  const dd = String(dateObj.getDate()).padStart(2, '0');
  const mm = String(dateObj.getMonth() + 1).padStart(2, '0');
  return `${hh}:00 /${thu} /${dd}/${mm}/${dateObj.getFullYear()}`;
};

// targetDateKey (YYYY-MM-DD): ngày của cột được thả vào (Daily view). Nếu không có thì giữ ngày cũ.
const onDropReport = async (e, newStatus, newPeriod, targetDateKey = null) => {
  const pendingRemId = draggedReminderId.value;
  const pendingReportId = draggedReportId.value;
  draggedReportId.value = null;
  draggedReminderId.value = null;
  dragOverColumn.value = null;
  highlightedReportId.value = null;

  if (pendingRemId) {
    const remId = pendingRemId;
    
    const sourceReminder = dueReminders.value.find(r => r.id === remId);
    if (!sourceReminder) return;

    if (API_URL === 'YOUR_GOOGLE_APPS_SCRIPT_WEB_APP_URL') {
      alert("Tính năng này cần cấu hình API_URL");
      return;
    }

    let d = new Date();
    if (targetDateKey) {
      const [ty, tm, td] = targetDateKey.split('-').map(Number);
      d = new Date(ty, tm - 1, td);
    }
    const newThoiGian = buildThoiGian(d, newPeriod);

    const originalStatus = sourceReminder.trang_thai;
    const originalTime = sourceReminder.thoi_gian;
    const originalReminderVisible = sourceReminder.reminder_visible;
    const originalReminderContent = sourceReminder.reminder_content;
    const originalReminderTime = sourceReminder.reminder_time;

    // Kéo thả chỉ đổi trạng thái + thời gian, không ghi gì vào ghi_chu
    sourceReminder.trang_thai = newStatus !== null && newStatus !== undefined ? newStatus : 'Chưa xử lý';
    sourceReminder.thoi_gian = newThoiGian;
    
    sourceReminder.reminder_visible = 'FALSE';
    sourceReminder.reminder_content = '';
    sourceReminder.reminder_time = '';

    hideReminder(sourceReminder);
    triggerDroppedSuccess(sourceReminder.id);

    try {
      const response = await firebaseFetch(API_URL, {
        method: 'POST',
        body: JSON.stringify({ ...sourceReminder, action: 'update' })
      });
      const result = await response.json();
      if (result.status !== 'success') {
        sourceReminder.trang_thai = originalStatus;
        sourceReminder.thoi_gian = originalTime;
        sourceReminder.reminder_visible = originalReminderVisible;
        sourceReminder.reminder_content = originalReminderContent;
        sourceReminder.reminder_time = originalReminderTime;
        alert('Lỗi cập nhật: ' + result.message);
      }
    } catch (error) {
      sourceReminder.trang_thai = originalStatus;
      sourceReminder.thoi_gian = originalTime;
      sourceReminder.reminder_visible = originalReminderVisible;
      sourceReminder.reminder_content = originalReminderContent;
      sourceReminder.reminder_time = originalReminderTime;
      alert('Lỗi kết nối: ' + error.message);
    }
    return;
  }

  const id = pendingReportId;
  if (!id) return;
  const report = reports.value.find(r => r.id === id);
  if (report) {
    // Nếu newStatus null (daily view), giữ nguyên trạng thái hiện tại
    const effectiveStatus = newStatus !== null && newStatus !== undefined ? newStatus : report.trang_thai;
    // Tính thời gian mới: đổi buổi (giờ 08:00 / 14:00) và ngày (nếu thả sang cột ngày khác)
    const oldDate = parseDateFromReport(report.thoi_gian) || new Date();
    let targetDate = new Date(oldDate.getFullYear(), oldDate.getMonth(), oldDate.getDate());
    if (targetDateKey) {
      const [ty, tm, td] = targetDateKey.split('-').map(Number);
      targetDate = new Date(ty, tm - 1, td);
    }
    const currentPeriod = formatDisplayTime(report.thoi_gian).period;
    const sameDay = targetDate.getFullYear() === oldDate.getFullYear() && targetDate.getMonth() === oldDate.getMonth() && targetDate.getDate() === oldDate.getDate();
    const newThoiGian = (currentPeriod === newPeriod && sameDay) ? report.thoi_gian : buildThoiGian(targetDate, newPeriod);

    if (report.trang_thai !== effectiveStatus || newThoiGian !== report.thoi_gian) {
      if (API_URL === 'YOUR_GOOGLE_APPS_SCRIPT_WEB_APP_URL') {
         alert("Tính năng này cần cấu hình API_URL");
         return;
      }
      const originalStatus = report.trang_thai;
      const originalTime = report.thoi_gian;
      const originalIsFailed = report.isFailed;
      
      // Cập nhật trực tiếp trên thẻ hiện có (không tạo thẻ mới)
      report.trang_thai = effectiveStatus;
      report.thoi_gian = newThoiGian;
      report.isFailed = '';

      triggerDroppedSuccess(report.id);
      
      try {
        const response = await firebaseFetch(API_URL, {
          method: 'POST',
          body: JSON.stringify({ ...report, action: 'update' })
        });
        const result = await response.json();
        if (result.status !== 'success') {
          report.trang_thai = originalStatus;
          report.thoi_gian = originalTime;
          report.isFailed = originalIsFailed;
          alert('Lỗi cập nhật: ' + result.message);
        }
      } catch (error) {
        console.error('Lỗi khi cập nhật trạng thái:', error);
        report.trang_thai = originalStatus;
        report.thoi_gian = originalTime;
        report.isFailed = originalIsFailed;
      }
    } else {
      triggerDroppedSuccess(report.id);
    }
  }
};

