  timeInputs.value.minute = '00';
}

const isMorning = computed(() => {
  const h = Number(timeInputs.value.hour);
  return h >= 0 && h < 12;
})

const isAfternoon = computed(() => {
  const h = Number(timeInputs.value.hour);
  return h >= 12 && h < 24;
})

const getNowTimeInputs = () => {
  const now = new Date();
  const thu = now.getDay();
  return {
    hour: String(now.getHours()).padStart(2, '0'),
    minute: String(now.getMinutes()).padStart(2, '0'),
    thu: String(thu === 0 ? 8 : thu + 1),
    day: String(now.getDate()).padStart(2, '0'),
    month: String(now.getMonth() + 1).padStart(2, '0'),
    year: String(now.getFullYear())
  };
}

const parseTimeString = (timeStr) => {
  try {
    const parts = timeStr.split(' /');
    if (parts.length === 3) {
      const timePart = parts[0]; 
      const thuPart = parts[1].trim(); 
      const datePart = parts[2]; 
      
      const [hour, minute] = timePart.split(':');
      const [d, m, y] = datePart.split('/');
      
      return { 
        hour, minute, 
        thu: thuPart,
        day: d.padStart(2, '0'), 
        month: m.padStart(2, '0'), 
        year: y 
      };
    }
  } catch (e) {
    console.error("Lỗi parse ngày:", e);
  }
  return getNowTimeInputs();
}

const formatTimeString = () => {
  const { hour, minute, thu, day, month, year } = timeInputs.value;
  let validDay = Number(day);
  const maxDay = new Date(Number(year), Number(month), 0).getDate();
  if (validDay > maxDay) validDay = maxDay;

  const validDayStr = String(validDay).padStart(2, '0');
  
  return `${hour}:${minute} /${thu} /${validDayStr}/${month}/${year}`;
}

// Chia tags ra mảng để render giao diện đẹp hơn
const splitTags = (tagString) => {
  if (!tagString) return [];
  return tagString.split(',').map(t => t.trim()).filter(t => t);
}

let unsubscribeReports = null;

// Fetch dữ liệu từ Google App Script
const fetchReports = async () => {
  if (API_URL === 'YOUR_GOOGLE_APPS_SCRIPT_WEB_APP_URL') {
     console.warn("Vui lòng cập nhật API_URL của Google Apps Script.");
     // Dữ liệu mẫu tạm thời để xem giao diện
     reports.value = [
       { id: '1', phan_loai: 'CÔNG VIỆC', thoi_gian: '14:30 /3 /22/4/2026', noi_dung: 'Hoàn thiện báo cáo', ghi_chu: 'Gửi sếp lúc 5h', tag: 'ƯU TIÊN', trang_thai: 'Chưa xử lý' },
       { id: '2', phan_loai: 'ĐỜI SỐNG', thoi_gian: '09:15 /2 /21/4/2026', noi_dung: 'Mua cà phê', ghi_chu: '', tag: 'BÌNH THƯỜNG', trang_thai: 'Hoàn thành' }
     ];
     return;
  }

  if (unsubscribeReports) {
    return; // Đã subscribe thì không cần chạy lại
  }

  loading.value = true
  try {
    const targetSheet = 'REPORT';
    const reportsRef = dbRef(database, targetSheet);
    
    unsubscribeReports = onValue(reportsRef, (snap) => {
      let data = [];
      if (snap.exists()) {
        const val = snap.val();
        for (const k in val) {
          let item = { ...val[k], id: k };
          delete item.action;
          
          const keyMap = {
            'GHI_CHU': 'ghi_chu',
            'NOI_DUNG': 'noi_dung',
            'PHAN_LOAI': 'phan_loai',
            'TAG': 'tag',
            'THOI_GIAN': 'thoi_gian',
            'TRANG_THAI': 'trang_thai',
            'CREATED_TIME': 'created_time',
            'reminder-time': 'reminder_time',
            'reminder-content': 'reminder_content',
            'reminder-visible': 'reminder_visible',
            'MAKH': 'maKH',
            'ma_khach_hang': 'maKH',
            'maKH': 'maKH',
            'ID_QUANLYFILE': 'id_quanlyfile',
            'id_quan_ly_file': 'id_quanlyfile',
            'id_quanlyfile': 'id_quanlyfile'
          };
          
          for (const oldKey in keyMap) {
            const newKey = keyMap[oldKey];
            if (item[oldKey] !== undefined) {
              item[newKey] = item[oldKey];
            }
          }
          
          data.push(item);
        }
      }
      
      const sortedData = data.sort((a, b) => String(b.id).localeCompare(String(a.id)));
      reports.value = sortedData;
      loading.value = false;
      
      if (route.query.id && !autoOpenedId) {
        autoOpenedId = true
        const r = reports.value.find(x => String(x.id) === String(route.query.id))
        if (r) {
          const rd = parseDateFromReport(r.thoi_gian)
          if (rd) {
            filters.value.filterMode = 'day'
            const dStr = `${rd.getFullYear()}-${String(rd.getMonth() + 1).padStart(2, '0')}-${String(rd.getDate()).padStart(2, '0')}`
            filters.value.dateFrom = dStr
            filters.value.dateTo = dStr
          }
          
          highlightedReportId.value = r.id;
          nextTick(() => {
            ensureReportVisible(r.id);
          });
          
          setTimeout(() => {
            ensureReportVisible(r.id);
            nextTick(() => {
              const el = document.getElementById('report-card-' + r.id)
              if (el) {
                el.scrollIntoView({ behavior: 'smooth', block: 'center' })
                setTimeout(() => {
                  if (highlightedReportId.value === r.id) {
                    highlightedReportId.value = null;
                  }
                }, 3000);
              }
            });
          }, 300);
        }
      }
    }, (error) => {
      console.error("Lỗi khi tải dữ liệu realtime: ", error);
      loading.value = false;
    });
  } catch (error) {
    console.error('Lỗi fetch data:', error)
    loading.value = false
  }
}

// Mở Modal
const deriveContextTimeInputs = () => {
  const base = getNowTimeInputs();
  if (
    filters.value.filterMode === 'day' &&
    filters.value.dateFrom &&
    (!filters.value.dateTo || filters.value.dateTo === filters.value.dateFrom)
  ) {
    const parts = String(filters.value.dateFrom).split('-').map(Number);
    if (parts.length === 3 && parts[0] && parts[1] && parts[2]) {
      const dObj = new Date(parts[0], parts[1] - 1, parts[2]);
      if (!isNaN(dObj.getTime())) {
        const jsDay = dObj.getDay();
        base.day = String(dObj.getDate()).padStart(2, '0');
        base.month = String(dObj.getMonth() + 1).padStart(2, '0');
        base.year = String(dObj.getFullYear());
        base.thu = String(jsDay === 0 ? 8 : jsDay + 1);
      }
    }
  }
  if (filters.value.period === 'Sáng' && Number(base.hour) >= 12) {
    base.hour = '08';
    base.minute = '00';
  } else if (filters.value.period === 'Chiều' && Number(base.hour) < 12) {
    base.hour = '14';
    base.minute = '00';
  }
  return base;
};

const openAddModal = () => {
  isEditing.value = false;
