    noi_dung: '',
    ghi_chu: '',
    tag: filters.value.tag || 'BÌNH THƯỜNG',
    trang_thai: preStatus,
    isFailed: preStatus === 'Failed' ? true : '',
    img_save: '',
    ten_file_img: '',
    link_excel_bao_gia: '',
    link_excel_mua_hang: '',
    ten_file_bao_gia: '',
