  const imgs = formData.value.img_save ? formData.value.img_save.split('\n').filter(Boolean).length : 0;
  const bgs = formData.value.link_excel_bao_gia ? formData.value.link_excel_bao_gia.split('\n').filter(Boolean).length : 0;
