const handlePasteImage = async (e) => {
  const items = e.clipboardData?.items;
  if (!items) return;
  const files = [];
  for (let i = 0; i < items.length; i++) {
    if (items[i].type.indexOf('image') !== -1) {
      files.push(items[i].getAsFile());
    }
  }
  if (files.length === 0) return;
  
  e.preventDefault();
  
  isUploadingFiles.value = 'img';
  try {
    for (const file of files) {
      if (!file) continue;
      const fd = new FormData();
      fd.append('key', 'b202a4bdc79bf1dc72f6f6ded6b74501');
      fd.append('image', file);
      const res = await firebaseFetch('https://api.imgbb.com/1/upload', { method: 'POST', body: fd }).then(r => r.json());
      
      if (res.success) {
        const nowP = new Date();
        const padP = (n) => String(n).padStart(2, '0');
        const pastedName = file.name && file.name !== 'image.png'
          ? file.name
          : `Screenshot_${padP(nowP.getHours())}${padP(nowP.getMinutes())}${padP(nowP.getSeconds())}.png`;
        formData.value.img_save = formData.value.img_save ? formData.value.img_save + '\n' + res.data.url : res.data.url;
        formData.value.ten_file_img = formData.value.ten_file_img ? formData.value.ten_file_img + '\n' + pastedName : pastedName;
        showToast('Đã tải ảnh dán lên thành công', 'success');
      } else {
        alert('Lỗi tải ảnh: ' + (res.error?.message || 'Không rõ'));
      }
    }
  } catch (err) {
    console.error(err);
    alert('Lỗi khi tải ảnh dán!');
  } finally {
    isUploadingFiles.value = false;
  }
}

const handleImgUpload = async (e) => {
  const files = e.target.files
  if (!files || files.length === 0) return
  
  isUploadingFiles.value = 'img'
  const newlyUploaded = []
  try {
    for (const file of files) {
      const fd = new FormData()
      fd.append('key', 'b202a4bdc79bf1dc72f6f6ded6b74501')
      fd.append('image', file)
      const res = await firebaseFetch('https://api.imgbb.com/1/upload', { method: 'POST', body: fd }).then(r => r.json())
      
      if (res.success) {
        formData.value.img_save = formData.value.img_save ? formData.value.img_save + '\n' + res.data.url : res.data.url
        formData.value.ten_file_img = formData.value.ten_file_img ? formData.value.ten_file_img + '\n' + file.name : file.name
        pendingStorageFiles.value.push({ name: file.name, url: res.data.url })
        newlyUploaded.push({ name: file.name, kind: 'img' })
        showToast('Đã tải ảnh đính kèm lên', 'success')
      } else {
        alert('Lỗi tải ảnh: ' + (res.error?.message || 'Không rõ'))
      }
    }
    if (newlyUploaded.length > 0) {
      openUploadFileNamePrompt(newlyUploaded)
    }
  } catch (err) {
    console.error(err)
    alert('Lỗi mạng khi tải ảnh lên')
  } finally {
    isUploadingFiles.value = false
    e.target.value = ''
    pendingStorageFiles.value = []
  }
}

const handleExcelUpload = async (e, field) => {
  const files = e.target.files
  if (!files || files.length === 0) return
  
  const kind = field === 'link_excel_bao_gia' ? 'bg' : 'mh'
  const labelKind = kind === 'bg' ? 'Báo giá' : 'DXMH/Khác'
  isUploadingFiles.value = kind
  const newlyUploaded = []
  const uploadedDocFilesForCustomerScan = []
  try {
    for (const file of files) {
      const fd = new FormData()
      fd.append('upload_preset', 'upload_file')
      fd.append('file', file)
      const res = await firebaseFetch('https://api.cloudinary.com/v1_1/db6fzs3rh/auto/upload', { method: 'POST', body: fd }).then(r => r.json())
      
      if (res.secure_url) {
        formData.value[field] = formData.value[field] ? formData.value[field] + '\n' + res.secure_url : res.secure_url
        const nameField = field.replace('link_excel_', 'ten_file_')
        formData.value[nameField] = formData.value[nameField] ? formData.value[nameField] + '\n' + file.name : file.name
        uploadedFileObjectsMap.set(res.secure_url, file)
        pendingStorageFiles.value.push({ name: file.name, url: res.secure_url })
        newlyUploaded.push({ name: file.name, kind })
        uploadedDocFilesForCustomerScan.push({ file, kind, name: file.name, url: res.secure_url })
      } else {
        alert('Lỗi tải file: ' + (res.error?.message || 'Không rõ'))
      }
    }
    let scannedCusSummary = null
    if (uploadedDocFilesForCustomerScan.length > 0) {
      scannedCusSummary = await scanAndSyncCustomerFromUploadedFiles(uploadedDocFilesForCustomerScan)
    }
    if (newlyUploaded.length > 0) {
      if (!scannedCusSummary) {
        showToast(`Đã tải tệp ${labelKind} đính kèm lên`, 'success')
      }
      openUploadFileNamePrompt(newlyUploaded, scannedCusSummary)
    }
  } catch (err) {
    console.error(err)
    alert('Lỗi mạng khi tải file lên Cloudinary')
  } finally {
    isUploadingFiles.value = false
    e.target.value = ''
    pendingStorageFiles.value = []
  }
}

const removeLink = (field, index) => {
  const links = formData.value[field].split('\n').filter(Boolean)
  links.splice(index, 1)
  formData.value[field] = links.join('\n')

  let nameField = null
  if (field.startsWith('link_excel_')) {
    nameField = field.replace('link_excel_', 'ten_file_')
  } else if (field === 'img_save') {
    nameField = 'ten_file_img'
  }

  if (nameField && formData.value[nameField]) {
    const names = formData.value[nameField].split('\n')
    while (names.length < links.length + 1) {
      names.push('')
    }
    names.splice(index, 1)
    formData.value[nameField] = names.join('\n')
  }
}

// Lưu (Thêm/Sửa)
const highlightedReportId = ref(null)

const createPipelineFromReport = () => {
  const pipelineData = {
    content: formData.value.noi_dung || '',
    note: formData.value.ghi_chu || ''
  }
  sessionStorage.setItem('pendingPipelineCreate', JSON.stringify(pipelineData))
  window.open('/pipeline-firebase', '_blank')
}

const saveReport = async (options = {}) => {
  const isContinue = !!options.continue;
  const isOpenEmpty = !!options.openEmpty;
  
  if ((isContinue || isOpenEmpty) && !formData.value.noi_dung) {
    return;
  }

  if (API_URL === 'YOUR_GOOGLE_APPS_SCRIPT_WEB_APP_URL') {
     alert("Vui lòng cập nhật API_URL của Google Apps Script để lưu thực tế.");
     if (!isContinue) closeModal();
     return;
  }

  formData.value.thoi_gian = formatTimeString();
  if (formData.value.trang_thai === 'Failed') {
    formData.value.isFailed = true;
  } else {
    formData.value.isFailed = '';
  }

  saving.value = true
  if (isUploadingFiles.value) {
    alert('Vui lòng đợi file đang được tải lên xong trước khi lưu.')
    saving.value = false
    return
  }
  
  // Tạo độ trễ giả 500ms để hiển thị trạng thái "Đang lưu..." (UX)
  await new Promise(r => setTimeout(r, 500));

  const action = isEditing.value ? 'update' : 'add'
  const payload = {
    action: action,
    ...formData.value,
    maKH: formData.value.maKH || '',
    id_quanlyfile: formData.value.id_quanlyfile || ''
  }
  
  // Đảm bảo cờ reminder_visible được set thành 'TRUE' nếu có lịch nhắc nhở
  if (payload.reminder_time && payload.reminder_visible !== 'FALSE' && payload.reminder_visible !== false) {
    payload.reminder_visible = 'TRUE';
  }

  // Cập nhật UI ngay lập tức
  const tempId = action === 'add' ? `temp_${Date.now()}` : formData.value.id;
  
  let newCreatedTime = formData.value.created_time;
  if (action === 'add') {
    const now = new Date();
    const pad = n => String(n).padStart(2, "0");
    newCreatedTime = `${pad(now.getHours())}:${pad(now.getMinutes())} ${pad(now.getDate())}/${pad(now.getMonth()+1)}/${now.getFullYear()}`;
  }

  const newReport = {
    ...formData.value,
    id: tempId,
    created_time: newCreatedTime
  };

  if (action === 'add') {
    reports.value.unshift(newReport);
  } else {
    const index = reports.value.findIndex(r => r.id === tempId);
    if (index !== -1) {
      reports.value[index] = newReport;
    }
  }

  // Clear Auto-Draft on successful save
  if (action === 'add') {
    clearSavedAddDraft();
  }
  if (formData.value.maKH) {
    recordRecentCustomerCode(formData.value.maKH);
  }

  // Tắt loading và xử lý đóng modal/reset
  if (!isContinue && !isOpenEmpty) {
    isModalOpen.value = false;
  } else if (isOpenEmpty) {
    isModalOpen.value = false;
    showEmptyDays();
  } else {
    suppressDraftPersist = true;
    formData.value.noi_dung = '';
    formData.value.ghi_chu = '';
    formData.value.img_save = '';
    formData.value.ten_file_img = '';
    formData.value.link_excel_bao_gia = '';
    formData.value.ten_file_bao_gia = '';
    formData.value.link_excel_mua_hang = '';
    formData.value.ten_file_mua_hang = '';
    formData.value.reminder_time = '';
    formData.value.reminder_content = '';
    isNotePanelOpen.value = false;
    isReminderPanelOpen.value = false;
    setTimeout(() => { suppressDraftPersist = false; }, 40);
    nextTick(() => {
      reportContentTextareaRef.value?.focus?.();
    });
  }
  saving.value = false;
  showToast(action === 'add' ? 'Đã thêm báo cáo công việc mới' : 'Đã lưu cập nhật báo cáo', 'success');

  // Highlight dòng vừa tác động
  highlightedReportId.value = tempId;
  setTimeout(() => {
    if (highlightedReportId.value === tempId) {
      highlightedReportId.value = null;
    }
  }, 3000);

  // Xử lý gửi dữ liệu ngầm (Firebase Realtime Database)
  // Không lưu field 'action' vào DB (nếu lưu, lần kéo thả sau sẽ bị hiểu nhầm là thêm mới)
  const { action: _ignoredAction, ...dbPayload } = payload;
  try {
    if (action === 'add') {
      const d = new Date()
      const pad = n => String(n).padStart(2, '0')
      const realId = `RPT_${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}_${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`
      
      const idx = reports.value.findIndex(r => r.id === tempId);
      if (idx !== -1) {
        reports.value[idx].id = realId;
      }
      if (highlightedReportId.value === tempId) {
        highlightedReportId.value = realId;
      }
      
      dbPayload.id = realId;
      await set(dbRef(database, `REPORT/${realId}`), dbPayload);
      
      if (activeReminderForNewReport.value) {
        hideReminder(activeReminderForNewReport.value);
        activeReminderForNewReport.value = null;
      }
    } else {
      await update(dbRef(database, `REPORT/${dbPayload.id}`), { ...dbPayload, action: null });
    }
  } catch (error) {
    console.error('Lỗi khi lưu Firebase:', error)
  }
}

// Chọn hàng loạt
const selectedReports = ref([])

const toggleSelectAll = (event) => {
  if (event.target.checked) {
    selectedReports.value = filteredReports.value.map(r => r.id);
  } else {
    selectedReports.value = [];
  }
}

const isAllSelected = computed(() => {
  return filteredReports.value.length > 0 && selectedReports.value.length === filteredReports.value.length;
})

const bulkMarkCompleted = async () => {
  if (selectedReports.value.length === 0) return;
  const count = selectedReports.value.length;
  const ok = await enqueueBaogiaDialog({
    mode: 'confirm',
    variant: 'success',
    title: 'Đánh dấu hoàn thành hàng loạt',
    eyebrow: 'XÁC NHẬN CẬP NHẬT',
    targetLabel: `${count} báo cáo công việc đang chọn`,
    message: `Xác nhận đánh dấu Hoàn thành cho ${count} công việc đã chọn?`,
    confirmText: 'Hoàn thành tất cả',
    cancelText: 'Huỷ bỏ'
  });
  if (!ok) return;
  
  saving.value = true;
  try {
    const promises = selectedReports.value.map(async id => {
      const report = reports.value.find(r => r.id === id);
      if (report && report.trang_thai !== 'Hoàn thành') {
        report.trang_thai = 'Hoàn thành';
        await firebaseFetch(API_URL, {
          method: 'POST',
          body: JSON.stringify({ ...report, action: 'update' })
        });
      }
    });
    await Promise.all(promises);
    selectedReports.value = [];
    showToast(`Đã hoàn thành ${count} công việc`, 'success');
  } catch (error) {
    console.error('Lỗi bulk update', error);
    alert('Có lỗi xảy ra khi cập nhật hàng loạt.');
  }
  saving.value = false;
}

const bulkDelete = async () => {
  if (selectedReports.value.length === 0) return;
  const count = selectedReports.value.length;
  const ok = await enqueueBaogiaDialog({
    mode: 'confirm',
    variant: 'danger',
    title: 'Xoá hàng loạt báo cáo?',
    eyebrow: 'HÀNH ĐỘNG KHÔNG THỂ HOÀN TÁC',
    targetLabel: `${count} báo cáo công việc đang chọn`,
    message: `Bạn có chắc chắn muốn xoá vĩnh viễn ${count} công việc đã chọn?`,
    subnote: 'Dữ liệu sau khi xoá sẽ không thể khôi phục.',
    confirmText: 'Xoá vĩnh viễn',
    cancelText: 'Huỷ bỏ'
  });
  if (!ok) return;
  
  saving.value = true;
  try {
    const promises = selectedReports.value.map(id => firebaseFetch(`${API_URL}?action=delete&id=${id}`));
    await Promise.all(promises);
    reports.value = reports.value.filter(r => !selectedReports.value.includes(r.id));
    selectedReports.value = [];
    showToast(`Đã xoá ${count} báo cáo công việc`, 'success');
  } catch (error) {
    console.error('Lỗi bulk delete', error);
    alert('Có lỗi xảy ra khi xóa hàng loạt.');
  }
  saving.value = false;
}

// Đánh dấu hoàn thành nhanh từ List
const isDoneModalOpen = ref(false)
const doneTarget = ref(null)

const markAsCompleted = async (report) => {
  if (report && report._isGuideDemo) {
    showToast('Thẻ mẫu minh hoạ trong chế độ hướng dẫn', 'info', 2000);
    return;
  }
  const originalStatus = report.trang_thai;
  report.trang_thai = 'Hoàn thành';
  
  try {
    await update(dbRef(database, `REPORT/${report.id}`), { trang_thai: 'Hoàn thành' });
    showToast('Đã đánh dấu Hoàn thành', 'success');
  } catch (error) {
    report.trang_thai = originalStatus;
    alert('Lỗi cập nhật: ' + error.message);
  }
}

const markAsFailed = async (report) => {
  if (report && report._isGuideDemo) {
    showToast('Thẻ mẫu minh hoạ trong chế độ hướng dẫn', 'info', 2000);
    return;
  }
  const originalStatus = report.trang_thai;
  const originalIsFailed = report.isFailed;
  
  report.trang_thai = 'Failed';
  report.isFailed = true;
  
  try {
    await update(dbRef(database, `REPORT/${report.id}`), { trang_thai: 'Failed', isFailed: true });
    showToast('Đã đánh dấu công việc Failed', 'warning');
  } catch (error) {
    report.trang_thai = originalStatus;
    report.isFailed = originalIsFailed;
    alert('Lỗi cập nhật: ' + error.message);
  }
}

// Xoá (Unified FIFO Queued baogiaDialog)
const isDeleteModalOpen = ref(false)
const deleteTarget = ref(null)
const isDeleting = ref(false)
const deletingIds = ref([])

const confirmDelete = async (id) => {
  if (id === '__guide_demo_report__') {
    showToast('Thẻ mẫu minh hoạ trong chế độ hướng dẫn', 'info', 2000);
    return;
  }
  if (API_URL === 'YOUR_GOOGLE_APPS_SCRIPT_WEB_APP_URL') {
    alert("Tính năng xoá cần cấu hình API_URL");
    return;
  }
  const target = reports.value.find(r => r.id === id);
  const dtInfo = target ? formatDisplayTime(target.thoi_gian) : null;
  const metaParts = [];
  if (dtInfo?.time) metaParts.push(dtInfo.time);
  if (dtInfo?.thu) metaParts.push(dtInfo.thu);
  if (dtInfo?.date) metaParts.push(dtInfo.date);
  if (target?.phan_loai) metaParts.push(target.phan_loai);

  const ok = await enqueueBaogiaDialog({
    mode: 'confirm',
    variant: 'danger',
    title: 'Xoá báo cáo công việc?',
    eyebrow: 'HÀNH ĐỘNG KHÔNG THỂ HOÀN TÁC',
    targetLabel: target?.noi_dung || `Báo cáo #${id}`,
    targetMeta: metaParts.join(' · '),
    message: 'Bạn có chắc chắn muốn xoá báo cáo công việc này khỏi hệ thống?',
    subnote: 'Dữ liệu sau khi xoá sẽ không thể khôi phục lại.',
    confirmText: 'Xoá báo cáo',
    cancelText: 'Huỷ bỏ'
  });
  if (!ok) return;
  deleteTarget.value = id;
  await executeDelete();
  showToast('Đã xoá báo cáo công việc', 'success');
}

const executeDelete = async () => {
  if (!deleteTarget.value) return;
  const id = deleteTarget.value;
  
  isDeleting.value = true;
  deletingIds.value = [id];
  isDeleteModalOpen.value = false;
  
  try {
    await remove(dbRef(database, `REPORT/${id}`));
    await new Promise(r => setTimeout(r, 400));
    reports.value = reports.value.filter(r => r.id !== id);
  } catch (error) {
    console.error('Lỗi delete:', error);
    alert('Lỗi khi xoá: ' + error.message);
  }
  
  deletingIds.value = [];
  isDeleting.value = false;
  deleteTarget.value = null;
}

// Helpers giao diện
const getCategoryClass = (cat) => {
  switch (cat?.toUpperCase()) {
    case 'CÔNG VIỆC': return 'cat-work'
    case 'ĐỜI SỐNG': return 'cat-life'
    default: return 'cat-default'
  }
}

const getStatusDotClass = (status) => {
  switch (status) {
    case 'Hoàn thành': return 'bg-emerald-500 shadow-emerald-500/50'
    case 'Chưa xử lý': return 'bg-amber-500 shadow-amber-500/50'
    default: return 'bg-slate-300'
  }
}


const downloadExcelFile = async (url, fileName) => {
  try {
    const response = await firebaseFetch(url);
    if (!response.ok) throw new Error('Network response was not ok');
    const blob = await response.blob();
    const blobUrl = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = blobUrl;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    window.URL.revokeObjectURL(blobUrl);
    a.remove();
  } catch (error) {
    console.error('Lỗi khi tải file', error);
    window.open(url, '_blank');
  }
}

const getExcelFileName = (dataObj, field, index, prefix) => {
  const nameField = field.replace('link_excel_', 'ten_file_');
  if (dataObj && dataObj[nameField]) {
    const names = String(dataObj[nameField]).split('\n');
    if (names[index] && names[index].trim() !== '') return names[index];
  }
  return `${prefix} ${index + 1}`;
}

const getImgFileName = (dataObj, index) => {
  if (dataObj && dataObj.ten_file_img) {
    const names = String(dataObj.ten_file_img).split('\n');
    if (names[index] && names[index].trim() !== '') return names[index];
  }
  return `Ảnh ${index + 1}`;
}

