  }
  if (type === 'word') {
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="18" height="18"><path fill="#2196F3" d="M41,10H25v28h16c0.553,0,1-0.447,1-1V11C42,10.447,41.553,10,41,10z"/><path fill="#FFF" d="M25 15H39V17.5H25zM25 20H39V22.5H25zM25 25H39V27.5H25zM25 30H35V32.5H25z"/><path fill="#1565C0" d="M27,42L6,38.746C5.416,38.655,5,38.146,5,37.555v-27.11c0-0.591,0.416-1.1,1-1.191L27,6V42z"/><path fill="#FFF" d="M21.8,17h-2.7l-1.5,8.6L15.8,17h-2.5l-1.9,8.6L9.9,17H7.1l2.8,14h2.7l1.9-8.3l1.8,8.3H19l2.8-14z"/></svg>`;
  }
  if (type === 'image') {
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="18" height="18"><rect x="6" y="8" width="36" height="32" rx="4" fill="#29B6F6"/><circle cx="16.5" cy="17.5" r="4" fill="#FFD54F"/><path fill="#0277BD" d="M23,25l-11,13h26c2.2,0,4-1.8,4-4v-2L31,20L23,25z"/><path fill="#4FC3F7" d="M16,24L6,36c0,2.2,1.8,4,4,4h22L16,24z"/></svg>`;
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="18" height="18"><path fill="#90CAF9" d="M38,42H10c-2.2,0-4-1.8-4-4V10c0-2.2,1.8-4,4-4h19l13,13v19C42,40.2,40.2,42,38,42z"/><path fill="#1976D2" d="M29,6v9c0,2.2,1.8,4,4,4h9L29,6z"/><rect x="14" y="23" width="20" height="2.5" rx="1.2" fill="#1565C0"/><rect x="14" y="29" width="20" height="2.5" rx="1.2" fill="#1565C0"/><rect x="14" y="35" width="13" height="2.5" rx="1.2" fill="#1565C0"/></svg>`;
};

const getFileName = (fileObj, prefix, index) => {
  if (typeof fileObj === 'object' && fileObj.name) return fileObj.name;
  const url = typeof fileObj === 'string' ? fileObj : fileObj?.url;
  try {
    const parts = url.split('/');
    let name = parts[parts.length - 1];
    name = name.split('?')[0];
    name = decodeURIComponent(name);
    return name;
  } catch (e) {
    return `${prefix} ${index + 1}`;
  }
};

const truncateFileName = (name) => {
  if (!name) return '';
  if (name.length > 25) {
    return name.substring(0, 15) + '...' + name.substring(name.length - 7);
  }
  return name;
};

const getOfficeViewUrl = (fileObj) => {
  const url = typeof fileObj === 'string' ? fileObj : fileObj?.url;
  if (!url || typeof url !== 'string') return '#';
  return `https://view.officeapps.live.com/op/view.aspx?src=${encodeURIComponent(url)}`;
};

// --- LAZY LOADING WATCHERS & INTERSECTION OBSERVERS (25 CÔNG VIỆC / ĐỢT) ---
let lazyLoadObserver = null;
let pendingModalObserver = null;

const setupLazyLoadObserver = () => {
  if (lazyLoadObserver) {
    lazyLoadObserver.disconnect();
    lazyLoadObserver = null;
  }
  if (typeof window === 'undefined' || !('IntersectionObserver' in window)) return;
  const el = lazyLoadSentinel.value;
  if (!el) return;

  lazyLoadObserver = new IntersectionObserver(
    (entries) => {
      const entry = entries[0];
      if (entry && entry.isIntersecting && hasMoreReports.value && !loading.value) {
        loadMoreReports();
      }
    },
    {
      root: null,
      rootMargin: '350px 0px',
      threshold: 0.01
    }
  );
  lazyLoadObserver.observe(el);
};

const setupPendingModalObserver = () => {
  if (pendingModalObserver) {
    pendingModalObserver.disconnect();
    pendingModalObserver = null;
  }
  if (typeof window === 'undefined' || !('IntersectionObserver' in window)) return;
  const el = pendingModalSentinel.value;
  if (!el) return;
  const scrollRoot = el.closest('.bg-modal-body, .elite-modal-body') || null;

  pendingModalObserver = new IntersectionObserver(
    (entries) => {
      const entry = entries[0];
      if (entry && entry.isIntersecting && hasMorePendingModalReports.value && !loading.value) {
        loadMorePendingModalReports();
      }
    },
    {
      root: scrollRoot,
      rootMargin: '250px 0px',
      threshold: 0.01
    }
  );
  pendingModalObserver.observe(el);
};

watch(
  [
    () => filters.value.filterMode,
    () => filters.value.weekFrom,
    () => filters.value.weekTo,
    () => filters.value.dateFrom,
    () => filters.value.dateTo,
    () => filters.value.monthFrom,
    () => filters.value.monthTo,
    () => filters.value.yearFrom,
    () => filters.value.yearTo,
    () => filters.value.tag,
    () => filters.value.phan_loai,
    () => filters.value.trang_thai,
    () => filters.value.period,
    () => filters.value.sortOrder,
    () => filters.value.searchQuery,
    () => filters.value.maKH,
    () => desktopViewMode.value
  ],
  () => {
    visibleReportCount.value = LAZY_BATCH_SIZE;
    nextTick(() => {
      setupLazyLoadObserver();
    });
  }
);

watch(
  [() => pendingFilterMode.value, () => isPendingModalOpen.value],
  () => {
    visiblePendingModalCount.value = LAZY_BATCH_SIZE;
    nextTick(() => {
      setupPendingModalObserver();
    });
  }
);

watch(lazyLoadSentinel, () => {
  nextTick(() => {
    setupLazyLoadObserver();
  });
});

watch(pendingModalSentinel, () => {
  nextTick(() => {
    setupPendingModalObserver();
  });
});

onMounted(() => {
  listenCustomersRealtime();
  listenQuanLyFileRealtime();
  fetchCustomersForQuote();
  loadPipelineData();
  if (route.query.date) {
    filters.value.filterMode = 'day'
    filters.value.dateFrom = String(route.query.date)
    filters.value.dateTo = String(route.query.date)
  }
  fetchReports()
  window.addEventListener('resize', onResize)
  window.addEventListener('keydown', onBaogiaGlobalKeydown)
  window.addEventListener('dragend', onGlobalKanbanDragCleanup)
  window.addEventListener('drop', onGlobalKanbanDragCleanup)
  document.addEventListener('mousedown', onBaogiaDocPointerDown)
  watch(isExportModalOpen, (open) => {
    if (!open) openModalSelectKey.value = null
  })
  watch(highlightedReportId, (val) => {
    if (autoClearHighlightTimer) {
      clearTimeout(autoClearHighlightTimer)
      autoClearHighlightTimer = null
    }
    if (val) {
      autoClearHighlightTimer = setTimeout(() => {
        highlightedReportId.value = null
        autoClearHighlightTimer = null
      }, 1700)
    }
  })
  watch(droppedReportId, (val) => {
    if (autoClearDroppedTimer) {
      clearTimeout(autoClearDroppedTimer)
      autoClearDroppedTimer = null
    }
    if (val) {
      autoClearDroppedTimer = setTimeout(() => {
        droppedReportId.value = null
        autoClearDroppedTimer = null
      }, 600)
    }
  })
  nextTick(() => {
    setupLazyLoadObserver();
  });
})

onUnmounted(() => {
  window.removeEventListener('resize', onResize)
  window.removeEventListener('keydown', onBaogiaGlobalKeydown)
  window.removeEventListener('dragend', onGlobalKanbanDragCleanup)
  window.removeEventListener('drop', onGlobalKanbanDragCleanup)
  document.removeEventListener('mousedown', onBaogiaDocPointerDown)
  if (smartToastTimer) clearTimeout(smartToastTimer)
  if (searchBlurTimer) clearTimeout(searchBlurTimer)
  if (inlineCusBlurTimer) clearTimeout(inlineCusBlurTimer)
  if (draftSaveTimer) clearTimeout(draftSaveTimer)
  if (autoClearHighlightTimer) clearTimeout(autoClearHighlightTimer)
  if (autoClearDroppedTimer) clearTimeout(autoClearDroppedTimer)
  if (lazyLoadObserver) {
    lazyLoadObserver.disconnect();
    lazyLoadObserver = null;
  }
  if (pendingModalObserver) {
    pendingModalObserver.disconnect();
    pendingModalObserver = null;
  }
  if (unsubscribeReports) {
    unsubscribeReports();
  }
  if (unsubscribeCustomers) {
    unsubscribeCustomers();
  }
  if (unsubscribeQuanLyFiles) {
    unsubscribeQuanLyFiles();
  }
})
</script>

