  font-weight: 900 !important;
  letter-spacing: 0.045em;
  color: #ffffff !important;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.16) !important;
  text-transform: uppercase;
}

.bg-dcol-head .status-dot {
  width: 9px !important;
  height: 9px !important;
  border-radius: 50% !important;
  background-color: #ffffff !important;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.28) !important;
  flex-shrink: 0;
}

.bg-dcol-check-ic {
  width: 21px;
  height: 21px;
  border-radius: 999px;
  background: #ffffff !important;
  color: #059669 !important;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.18) !important;
}

.report-container.page.theme-light-blue .bg-dcol-check-ic {
  color: #0284c7 !important;
}

.bg-dcol-badge.kanban-badge,
.bg-detail-col.kb-col-done .bg-dcol-badge.kanban-badge,
.bg-detail-col.kb-col-pending .bg-dcol-badge.kanban-badge,
.bg-detail-col.kb-col-failed .bg-dcol-badge.kanban-badge {
  background: rgba(255, 255, 255, 0.22) !important;
  border: 1px solid rgba(255, 255, 255, 0.42) !important;
  color: #ffffff !important;
  padding: 2.5px 10px !important;
  border-radius: 999px !important;
  font-size: 0.74rem !important;
  font-weight: 800 !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2) !important;
}

/* 1A + 2A: Inner 2-Column Split (Buổi sáng | Buổi chiều) */
.bg-dcol-grid {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) !important;
  grid-template-rows: minmax(0, 1fr);
  align-items: stretch !important;
  gap: 10px !important;
  padding: 12px !important;
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
}

@media (max-width: 768px) {
  .bg-dcol-grid {
    grid-template-columns: minmax(0, 1fr) !important;
    grid-template-rows: auto;
    padding: 9px !important;
    gap: 9px !important;
  }
}

.bg-dsub-col {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
  min-height: 100%;
  height: 100%;
  border-radius: 13px;
  padding: 0;
  overflow: hidden;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-soft-pad-bd);
  transition: background 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.report-container.page.theme-light-blue .bg-dsub-col {
  background: #f8fafc;
  border-color: #cbd5e1;
}

.bg-dsub-col.kb-col-drag-over {
  transform: none !important;
  animation: none !important;
  border: 1.5px solid var(--theme-pri-bright) !important;
  box-shadow: inset 0 0 0 1px var(--theme-pri-bd), 0 0 22px -6px var(--theme-pri-glow) !important;
}
.bg-dsub-col.kb-col-drag-over::after {
  display: none !important;
}

/* 1A Refined: Sub-column Period Header — No Colored Background, Colored Text + Solid Colored '+' Button */
.bg-dsub-head {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  min-height: 38px;
  padding: 7px 38px;
  border-radius: 12px 12px 0 0;
  background: transparent !important;
  border: none;
  border-bottom: 1px solid var(--bg-border);
  box-shadow: none !important;
}

.report-container.page.theme-light-blue .bg-dsub-head {
  border-bottom-color: #e2e8f0;
}

.bg-dsub-head-center {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-width: 0;
}

.bg-dsub-title {
  font-size: 0.77rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.045em;
  white-space: nowrap;
}

.bg-dsub-count {
  padding: 1.5px 7.5px;
  border-radius: 999px;
  font-size: 0.69rem;
  font-weight: 800;
}

/* Pending Table -> Amber Text & Count Pill */
.bg-detail-col.kb-col-pending .bg-dsub-title {
  color: #fbbf24 !important;
}
.bg-detail-col.kb-col-pending .bg-dsub-count {
  background: rgba(245, 158, 11, 0.16) !important;
  border: 1px solid rgba(245, 158, 11, 0.36) !important;
  color: #fcd34d !important;
}
.report-container.page.theme-light-blue .bg-detail-col.kb-col-pending .bg-dsub-title {
  color: #d97706 !important;
}
.report-container.page.theme-light-blue .bg-detail-col.kb-col-pending .bg-dsub-count {
  background: rgba(245, 158, 11, 0.13) !important;
  border-color: rgba(217, 119, 6, 0.32) !important;
  color: #b45309 !important;
}

/* Failed Table -> Rose Red Text & Count Pill */
.bg-detail-col.kb-col-failed .bg-dsub-title {
  color: #fb7185 !important;
}
.bg-detail-col.kb-col-failed .bg-dsub-count {
  background: rgba(244, 63, 94, 0.16) !important;
  border: 1px solid rgba(244, 63, 94, 0.36) !important;
  color: #fda4af !important;
}
.report-container.page.theme-light-blue .bg-detail-col.kb-col-failed .bg-dsub-title {
  color: #e11d48 !important;
}
.report-container.page.theme-light-blue .bg-detail-col.kb-col-failed .bg-dsub-count {
  background: rgba(244, 63, 94, 0.12) !important;
  border-color: rgba(225, 29, 72, 0.32) !important;
  color: #be123c !important;
}

/* Completed Table -> Emerald Text (Dark) | Ocean Blue Text (Light) */
.bg-detail-col.kb-col-done .bg-dsub-title {
  color: #34d399 !important;
}
.bg-detail-col.kb-col-done .bg-dsub-count {
  background: rgba(16, 185, 129, 0.16) !important;
  border: 1px solid rgba(16, 185, 129, 0.36) !important;
  color: #6ee7b7 !important;
}
.report-container.page.theme-light-blue .bg-detail-col.kb-col-done .bg-dsub-title {
  color: #0284c7 !important;
}
.report-container.page.theme-light-blue .bg-detail-col.kb-col-done .bg-dsub-count {
  background: rgba(14, 165, 233, 0.13) !important;
  border-color: rgba(2, 132, 199, 0.32) !important;
  color: #0369a1 !important;
}

/* '+' Quick-Add Button in Solid Semantic Background + White Icon */
.bg-dsub-add-btn {
  position: absolute !important;
  right: 7px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: 25px !important;
  height: 25px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 7.5px;
  color: #ffffff !important;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  cursor: pointer;
  transition: filter 0.15s ease, box-shadow 0.15s ease, transform 0.12s ease;
}

.bg-detail-col.kb-col-pending .bg-dsub-add-btn {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%) !important;
  border: 1px solid rgba(252, 211, 77, 0.5) !important;
  box-shadow: 0 3px 9px -2px rgba(217, 119, 6, 0.45) !important;
}

.bg-detail-col.kb-col-failed .bg-dsub-add-btn {
  background: linear-gradient(135deg, #f43f5e 0%, #e11d48 100%) !important;
  border: 1px solid rgba(253, 164, 175, 0.5) !important;
  box-shadow: 0 3px 9px -2px rgba(225, 29, 72, 0.45) !important;
}

.bg-detail-col.kb-col-done .bg-dsub-add-btn {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%) !important;
  border: 1px solid rgba(110, 231, 183, 0.5) !important;
  box-shadow: 0 3px 9px -2px rgba(5, 150, 105, 0.48) !important;
}

.report-container.page.theme-light-blue .bg-detail-col.kb-col-done .bg-dsub-add-btn {
  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%) !important;
  border: 1px solid rgba(125, 211, 252, 0.55) !important;
  box-shadow: 0 3px 9px -2px rgba(2, 132, 199, 0.42) !important;
}

.bg-dsub-add-btn:hover {
  filter: brightness(1.08);
  color: #ffffff !important;
  transform: translateY(-50%) scale(1.08) !important;
}

.bg-dsub-list.kanban-list {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: 12px;
  padding: 11px !important;
  flex: 1 1 auto;
  min-height: 115px;
}

.bg-dsub-empty {
  flex: 1 1 auto;
  min-height: 120px;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  padding: 2px;
}

.bg-dsub-empty-add {
  width: 100%;
  min-height: 98px;
  border-radius: 13px;
  border: 1.5px dashed var(--bg-border-strong);
  background: transparent;
  color: var(--bg-text-muted);
  font-size: 0.8rem;
  font-weight: 700;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  box-sizing: border-box;
  transition: all 0.16s ease;
}

.bg-dsub-empty > .bg-dsub-empty-add {
  flex: 1 1 auto;
  justify-content: flex-start;
  padding: clamp(56px, 11vh, 128px) 12px 24px;
}

.bg-dsub-empty-add:hover {
  border-color: var(--theme-pri-bright);
  background: var(--theme-pri-bg);
  color: var(--theme-pri-bright);
}
.bg-dsub-empty-plus {
  width: 30px;
  height: 30px;
  border-radius: 999px;
  background: var(--bg-card);
  border: 1px solid var(--bg-border-strong);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  font-weight: 800;
  line-height: 1;
}

.bg-dsub-empty-txt {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--bg-text-muted);
  opacity: 0.75;
}

.bg-dsub-empty > .bg-dsub-empty-txt {
  flex: 1 1 auto;
  width: 100%;
  min-height: 120px;
  border-radius: 13px;
  border: 1.5px dashed var(--bg-border);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: clamp(72px, 12.5vh, 144px) 12px 24px;
  box-sizing: border-box;
  text-align: center;
}

/* --- Bento Detail Task Card (Scaled Up Roomy Edition — 100% Width Content!) --- */
.bg-detail-card {
  width: 100%;
  box-sizing: border-box;
  border-radius: 15px;
  padding: 14px 15px;
  min-height: 114px;
  background: var(--bg-card);
  border: 1px solid var(--bg-border-strong);
  border-left: 4.5px solid #f59e0b;
  color: var(--bg-text);
  display: flex;
  flex-direction: column;
  gap: 10px;
  cursor: pointer;
  position: relative;
  min-width: 0;
  box-shadow: 0 5px 15px -4px rgba(0, 0, 0, 0.26);
  transition:
    transform 0.18s var(--bg-ease),
    box-shadow 0.18s var(--bg-ease),
    border-color 0.18s ease,
    background 0.18s ease;
}

.report-container.page.theme-light-blue .bg-detail-card {
  background: #ffffff;
  border-color: #cbd5e1;
  box-shadow: 0 4px 13px -3px rgba(15, 23, 42, 0.08);
}

.bg-detail-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 28px -10px rgba(0, 0, 0, 0.44);
}
.report-container.page.theme-light-blue .bg-detail-card:hover {
  box-shadow: 0 12px 24px -8px rgba(15, 23, 42, 0.15);
}

.bg-detail-card.is-pending.is-priority {
  border-left-color: #f43f5e;
}

/* Proposal 4: Failed Card Hierarchy */
.bg-detail-card.is-failed {
  opacity: 1 !important;
  filter: none !important;
  border-color: rgba(244, 63, 94, 0.38);
  border-left: 4.5px solid #e11d48;
  background: linear-gradient(140deg, rgba(225, 29, 72, 0.14) 0%, var(--bg-card) 68%);
}
.report-container.page.theme-light-blue .bg-detail-card.is-failed {
  opacity: 1 !important;
  filter: none !important;
  border-color: #fecdd3;
  border-left: 4.5px solid #e11d48;
  background: linear-gradient(140deg, #fff1f2 0%, #ffffff 72%);
}

/* Proposal 4: Completed Card Hierarchy — Solid Emerald Green (Dark) / Solid Ocean Blue (Light) + White Text */
.bg-detail-card.is-done {
  opacity: 1 !important;
  filter: none !important;
  background: linear-gradient(135deg, #059669 0%, #047857 100%) !important;
  border: 1px solid rgba(110, 231, 183, 0.42) !important;
  border-left: 4.5px solid #a7f3d0 !important;
  color: #ffffff !important;
  box-shadow: 0 7px 18px -4px rgba(5, 150, 105, 0.42);
}
.report-container.page.theme-light-blue .bg-detail-card.is-done {
  opacity: 1 !important;
  filter: none !important;
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%) !important;
  border: 1px solid rgba(125, 211, 252, 0.52) !important;
  border-left: 4.5px solid #e0f2fe !important;
  color: #ffffff !important;
  box-shadow: 0 7px 18px -4px rgba(2, 132, 199, 0.34);
}
.bg-detail-card.is-done:hover {
  box-shadow: 0 12px 24px -6px rgba(5, 150, 105, 0.52);
}
.report-container.page.theme-light-blue .bg-detail-card.is-done:hover {
  box-shadow: 0 12px 24px -6px rgba(2, 132, 199, 0.44);
}

/* Smooth Dragging, Post-Drop Settle & Non-Hanging Focus Pulse */
.bg-detail-card.is-dragging {
  opacity: 0.42 !important;
  transform: scale(0.985) !important;
  box-shadow: none !important;
}

@keyframes bgDetailCardDropSmoothDark {
  0% {
    opacity: 0.72;
    transform: translate3d(0, -8px, 0) scale(0.974);
    box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.82), 0 18px 34px -8px rgba(16, 185, 129, 0.46);
  }
  58% {
    opacity: 1;
    transform: translate3d(0, 1.5px, 0) scale(1.007);
    box-shadow: 0 0 0 5px rgba(52, 211, 153, 0.16), 0 10px 22px -6px rgba(0, 0, 0, 0.32);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}

@keyframes bgDetailCardDropSmoothLight {
  0% {
    opacity: 0.74;
    transform: translate3d(0, -8px, 0) scale(0.974);
    box-shadow: 0 0 0 3px rgba(14, 165, 233, 0.8), 0 18px 34px -8px rgba(2, 132, 199, 0.36);
  }
  58% {
    opacity: 1;
    transform: translate3d(0, 1.5px, 0) scale(1.007);
    box-shadow: 0 0 0 5px rgba(14, 165, 233, 0.16), 0 10px 22px -6px rgba(15, 23, 42, 0.14);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}

.bg-detail-card.dropped-success {
  z-index: 30 !important;
  animation: bgDetailCardDropSmoothDark 0.52s cubic-bezier(0.22, 1, 0.36, 1) !important;
}
.report-container.page.theme-light-blue .bg-detail-card.dropped-success {
  animation: bgDetailCardDropSmoothLight 0.52s cubic-bezier(0.22, 1, 0.36, 1) !important;
}

@keyframes bgDetailCardFocusPulse {
  0% {
    box-shadow: 0 0 0 0 var(--theme-pri-bright);
  }
  35% {
    box-shadow: 0 0 0 3.5px var(--theme-pri-bright), 0 10px 24px -6px var(--theme-pri-shadow);
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}

/* Override legacy .highlight-card red !important lock on Detail Cards so it never hangs */
.bg-detail-card.highlight-card {
  background: var(--bg-card) !important;
  border-color: var(--bg-border-strong) !important;
  box-shadow: 0 4px 12px -4px rgba(0, 0, 0, 0.24) !important;
  animation: bgDetailCardFocusPulse 1.55s cubic-bezier(0.22, 1, 0.36, 1) !important;
}
.report-container.page.theme-light-blue .bg-detail-card.highlight-card {
  background: #ffffff !important;
  border-color: #cbd5e1 !important;
  box-shadow: 0 3px 10px -3px rgba(15, 23, 42, 0.07) !important;
}
.bg-detail-card.is-done.highlight-card {
  background: linear-gradient(135deg, #059669 0%, #047857 100%) !important;
  border-color: rgba(110, 231, 183, 0.42) !important;
}
.report-container.page.theme-light-blue .bg-detail-card.is-done.highlight-card {
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%) !important;
  border-color: rgba(125, 211, 252, 0.52) !important;
}

/* Inner Elements Contrast Overrides on Solid Colored Completed Cards (.bg-detail-card.is-done) */
.bg-detail-card.is-done .bg-dcard-time,
.bg-detail-card.is-done .bg-dcard-title,
.bg-detail-card.is-done .bg-dcard-note-txt,
.bg-detail-card.is-done .bg-dcard-pl-main,
.bg-detail-card.is-done .bg-dcard-pl-lbl,
.bg-detail-card.is-done .bg-dcard-pl-txt {
  color: #ffffff !important;
}

.bg-detail-card.is-done .bg-dcard-time {
  opacity: 0.92;
}

.bg-detail-card.is-done .bg-dcard-done-circle {
  background: #ffffff !important;
  color: #047857 !important;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.18) !important;
}
.report-container.page.theme-light-blue .bg-detail-card.is-done .bg-dcard-done-circle {
  background: #ffffff !important;
  color: #0284c7 !important;
}

.bg-detail-card.is-done .bg-dcard-chip.is-work,
.bg-detail-card.is-done .bg-dcard-chip.is-life,
.bg-detail-card.is-done .bg-dcard-chip.is-cus-chip {
  background: rgba(255, 255, 255, 0.18) !important;
  border-color: rgba(255, 255, 255, 0.34) !important;
  color: #ffffff !important;
}

.bg-detail-card.is-done .bg-dcard-chip.is-prio-chip {
  background: rgba(225, 29, 72, 0.92) !important;
  border-color: rgba(255, 255, 255, 0.48) !important;
  color: #ffffff !important;
}

.bg-detail-card.is-done .bg-dcard-note {
  background: rgba(255, 255, 255, 0.15) !important;
  border: 1px solid rgba(255, 255, 255, 0.3) !important;
  border-left: 3px solid #ffffff !important;
}
.bg-detail-card.is-done .bg-dcard-note-tag {
  background: rgba(255, 255, 255, 0.24) !important;
  color: #ffffff !important;
}

.bg-detail-card.is-done .bg-dcard-pl-item {
  background: rgba(255, 255, 255, 0.14) !important;
  border: 1px solid rgba(255, 255, 255, 0.28) !important;
  border-left: 3px solid #ffffff !important;
}
.bg-detail-card.is-done .bg-dcard-pl-eye {
  color: #ffffff !important;
}
.bg-detail-card.is-done .bg-dcard-pl-eye:hover {
  background: rgba(255, 255, 255, 0.24) !important;
}

.bg-detail-card.is-done .bg-dcard-files-toggle,
.bg-detail-card.is-done .bg-dcard-qlf-btn {
  background: rgba(255, 255, 255, 0.16) !important;
  border-color: rgba(255, 255, 255, 0.32) !important;
  color: #ffffff !important;
}
.bg-detail-card.is-done .bg-dcard-files-toggle:hover,
.bg-detail-card.is-done .bg-dcard-files-toggle.is-open,
.bg-detail-card.is-done .bg-dcard-qlf-btn:hover {
  background: rgba(255, 255, 255, 0.24) !important;
  border-color: rgba(255, 255, 255, 0.48) !important;
  color: #ffffff !important;
}

.bg-detail-card.is-done .tl-att-v5 .tl-att-row {
  background: rgba(0, 0, 0, 0.18) !important;
  border-color: rgba(255, 255, 255, 0.26) !important;
  color: #ffffff !important;
}
.bg-detail-card.is-done .tl-att-v5 .tl-att-name,
.bg-detail-card.is-done .tl-att-v5 .tl-att-ic {
  color: #ffffff !important;
}
.bg-detail-card.is-done .tl-att-v5 .tl-att-act {
  background: rgba(255, 255, 255, 0.2) !important;
  border-color: rgba(255, 255, 255, 0.36) !important;
  color: #ffffff !important;
}
.bg-detail-card.is-done .tl-att-v5 .tl-att-act:hover {
  background: #ffffff !important;
  border-color: #ffffff !important;
  color: #047857 !important;
}
.report-container.page.theme-light-blue .bg-detail-card.is-done .tl-att-v5 .tl-att-act:hover {
  color: #0284c7 !important;
}

.bg-detail-card.is-done:hover .bg-dcard-actions,
.bg-detail-card.is-done:focus-within .bg-dcard-actions {
  border-top-color: rgba(255, 255, 255, 0.26) !important;
}
.bg-detail-card.is-done .bg-dcard-btn.is-del {
  background: rgba(255, 255, 255, 0.16) !important;
  border-color: rgba(255, 255, 255, 0.4) !important;
  color: #ffffff !important;
}
.bg-detail-card.is-done .bg-dcard-btn.is-del:hover {
  background: #e11d48 !important;
  border-color: #fda4af !important;
  color: #ffffff !important;
}

/* Top Meta & Badges Row */
.bg-dcard-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 6px 8px;
  min-width: 0;
}

.bg-dcard-meta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.bg-dcard-stt {
  padding: 2px 7px;
  border-radius: 6px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-border);
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--theme-pri-bright);
  line-height: 1.25;
}

.bg-dcard-time {
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--bg-text-muted);
  white-space: nowrap;
}

.bg-dcard-badges {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  min-width: 0;
}

.bg-dcard-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: 6.5px;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  line-height: 1.25;
  white-space: nowrap;
}

.bg-dcard-chip.is-work {
  background: var(--sem-sky-bg);
  border: 1px solid var(--sem-sky-bd);
  color: var(--sem-sky-bright);
}

.bg-dcard-chip.is-life {
  background: var(--sem-teal-bg);
  border: 1px solid var(--sem-teal-bd);
  color: var(--sem-teal-bright);
}

.bg-dcard-chip.is-failed-chip {
  background: #e11d48;
  border: 1px solid #fb7185;
  color: #ffffff;
}

.bg-dcard-chip.is-prio-chip {
  background: var(--sem-rose-bg);
  border: 1px solid var(--sem-rose-bd);
  color: var(--sem-rose-bright);
}

.bg-dcard-chip.is-cus-chip {
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-border-strong);
  color: var(--bg-text-sec);
  max-width: 175px;
}

.bg-dcard-cus-txt {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Card Main Title Row + Circular Checkmark Icon */
.bg-dcard-title-row {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  min-width: 0;
}

.bg-dcard-done-circle {
  width: 22px;
  height: 22px;
  border-radius: 999px;
  background: var(--theme-pri-grad);
  color: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 1px;
  box-shadow: 0 2px 7px -1px var(--theme-pri-shadow);
}

.bg-dcard-title {
  flex: 1 1 0;
  min-width: 0;
  font-size: 0.96rem;
  font-weight: 700;
  line-height: 1.5;
  color: var(--bg-text);
  word-break: break-word;
  white-space: pre-line;
}

/* Highlight Note Callout */
.bg-dcard-note {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  padding: 8px 11px;
  border-radius: 10px;
  background: var(--sem-rose-bg);
  border: 1px solid var(--sem-rose-bd);
  border-left: 3.5px solid #f43f5e;
  min-width: 0;
}

.bg-dcard-note-tag {
  padding: 2px 6px;
  border-radius: 5px;
  background: rgba(244, 63, 94, 0.22);
  color: var(--sem-rose-bright);
  font-size: 0.64rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  flex-shrink: 0;
  margin-top: 1px;
}

.bg-dcard-note-txt {
  font-size: 0.81rem;
  font-weight: 600;
  line-height: 1.44;
  color: var(--sem-rose-bright);
  word-break: break-word;
}

/* Linked Pipelines */
.bg-dcard-pipelines {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}

.bg-dcard-pl-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 7px;
  padding: 7px 10px;
  border-radius: 9px;
  background: var(--sem-sky-bg);
  border: 1px solid var(--sem-sky-bd);
  border-left: 3.5px solid #0ea5e9;
  min-width: 0;
}

.bg-dcard-pl-main {
  flex: 1 1 0;
  min-width: 0;
  font-size: 0.78rem;
  line-height: 1.36;
  color: var(--bg-text-sec);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bg-dcard-pl-lbl {
  font-weight: 800;
  color: var(--sem-sky-bright);
  margin-right: 4px;
}

.bg-dcard-pl-eye {
  width: 25px !important;
  height: 25px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 7px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--sem-sky-bright);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  cursor: pointer;
  transition: background 0.14s ease, color 0.14s ease;
}
.bg-dcard-pl-eye:hover {
  background: #0284c7;
  color: #ffffff;
}

/* Proposal 5: Collapsible Attachments Toggle + Linked File Shortcut */
.bg-dcard-files-wrap {
  display: flex;
  flex-direction: column;
  gap: 6.5px;
  min-width: 0;
}

.bg-dcard-files-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
}

.bg-dcard-files-toggle {
  flex: 1 1 135px;
  min-width: 0;
  height: 31px !important;
  margin: 0 !important;
  padding: 0 11px !important;
  border-radius: 9px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-border-strong);
  color: var(--theme-pri-bright);
  font-size: 0.76rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 7px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.bg-dcard-files-toggle:hover,
.bg-dcard-files-toggle.is-open {
  background: var(--theme-pri-bg);
  border-color: var(--theme-pri-bd);
}

.bg-dcard-files-toggle-left {
  display: inline-flex;
  align-items: center;
  gap: 5.5px;
  min-width: 0;
  white-space: nowrap;
}

.bg-dcard-files-caret {
  font-size: 0.74rem;
  opacity: 0.85;
  flex-shrink: 0;
}

.bg-dcard-qlf-btn {
  flex: 0 0 auto;
  height: 31px !important;
  margin: 0 !important;
  padding: 0 11px !important;
  border-radius: 9px;
  background: var(--sem-sky-bg);
  border: 1px solid var(--sem-sky-bd);
  color: var(--sem-sky-bright);
  font-size: 0.75rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}
.bg-dcard-qlf-btn:hover {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

.bg-dcard-att-collapse {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  margin-top: 0;
  pointer-events: none;
  transition:
    grid-template-rows 0.22s var(--bg-ease),
    opacity 0.18s ease,
    margin-top 0.18s ease;
}

.bg-dcard-att-collapse.is-open {
  grid-template-rows: 1fr;
  opacity: 1;
  margin-top: 2px;
  pointer-events: auto;
}

.bg-dcard-att-collapse-inner {
  min-height: 0;
  overflow: hidden;
}

.bg-dcard-att-list.tl-att-v5 {
  margin-top: 0 !important;
  padding: 0 !important;
  gap: 6px !important;
}

.bg-dcard-att-list.tl-att-v5 .tl-att-row {
  padding: 6.5px 9px;
  border-radius: 9px;
}

.bg-dcard-att-list.tl-att-v5 .tl-att-name {
  font-size: 0.78rem;
}

.bg-dcard-att-list.tl-att-v5 .tl-att-act {
  width: 26px !important;
  height: 24px !important;
}

/* Proposal 4: Differentiated Action Footer */
.bg-dcard-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
  padding-top: 10px;
  margin-top: auto;
  border-top: 1px solid var(--bg-border);
  transition:
    max-height 0.2s var(--bg-ease),
    opacity 0.16s ease,
    padding-top 0.16s ease,
    margin-top 0.16s ease,
    border-color 0.16s ease;
}

/* Done cards hide actions at rest and reveal smoothly on hover */
.bg-detail-card.is-done .bg-dcard-actions {
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  padding-top: 0;
  margin-top: -3px;
  border-top: 0 solid transparent;
  pointer-events: none;
}

.bg-detail-card.is-done:hover .bg-dcard-actions,
.bg-detail-card.is-done:focus-within .bg-dcard-actions {
  max-height: 46px;
  opacity: 1;
  padding-top: 10px;
  margin-top: auto;
  border-top: 1px solid var(--bg-border);
  pointer-events: auto;
}

.bg-dcard-btn {
  flex: 1 1 auto;
  height: 32px !important;
  padding: 0 11px !important;
  margin: 0 !important;
  border-radius: 8.5px;
  font-size: 0.77rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  white-space: nowrap;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease, transform 0.12s ease;
}

.bg-dcard-btn:active {
  transform: scale(0.97);
}

.bg-dcard-btn.is-del {
  background: transparent;
  border: 1.5px solid rgba(248, 113, 113, 0.38);
  color: #f87171;
}
.report-container.page.theme-light-blue .bg-dcard-btn.is-del {
  border-color: rgba(225, 29, 72, 0.36);
  color: #e11d48;
}
.bg-dcard-btn.is-del:hover {
  background: #e11d48;
  border-color: #e11d48;
  color: #ffffff;
  box-shadow: 0 4px 10px -2px rgba(225, 29, 72, 0.42);
}

.bg-dcard-btn.is-fail {
  background: var(--bg-soft-pad);
  border: 1.5px solid var(--bg-border-strong);
  color: var(--bg-text-sec);
}
.bg-dcard-btn.is-fail:hover {
  background: linear-gradient(135deg, #f97316 0%, #ea580c 100%);
  border-color: transparent;
  color: #ffffff;
  box-shadow: 0 4px 10px -2px rgba(249, 115, 22, 0.45);
}

.bg-dcard-btn.is-done {
  background: var(--theme-pri-grad);
  border: none;
  color: #ffffff;
  box-shadow: 0 4px 11px -2px var(--theme-pri-shadow);
}
.bg-dcard-btn.is-done:hover {
  background: var(--theme-pri-grad-h);
  color: #ffffff;
  box-shadow: 0 6px 14px -2px var(--theme-pri-shadow);
}

.bg-dsub-more-btn.lazy-subcol-more-btn {
  background: var(--bg-card) !important;
  border: 1px dashed var(--bg-border-strong) !important;
  color: var(--theme-pri-bright) !important;
  border-radius: 10px !important;
  padding: 8px 10px !important;
  font-size: 0.75rem !important;
  font-weight: 700 !important;
}
.bg-dsub-more-btn.lazy-subcol-more-btn:hover {
  background: var(--theme-pri-bg) !important;
  border-color: var(--theme-pri-bd) !important;
}

/* ============================================================================
   BOARD MODE ADAPTATIONS (SINGLE-STATUS FULL-WIDTH KANBAN & CALENDAR MODE)
============================================================================ */
.bg-board-anchor.is-single-status .kanban-board {
  grid-template-columns: minmax(0, 1fr) !important;
}

.bg-board-anchor.is-calendar-mode .lazy-load-footer {
  display: none !important;
}

/* ============================================================================
   MODULE 1C: GOOGLE CALENDAR WEEK (SÁNG / CHIỀU + QUICK ADD '+') & MONTH VIEW
============================================================================ */
.bg-gcal-workspace {
  position: relative;
  background: var(--bg-glass-panel);
  border: 1px solid var(--bg-glass-border);
  border-radius: 18px;
  overflow: hidden;
  margin-bottom: 18px;
  box-shadow:
    inset 0 1px 0 var(--bg-specular),
    var(--bg-shadow-panel);
  display: flex;
  flex-direction: column;
}

.bg-gcal-workspace.is-fullscreen {
  position: fixed !important;
  inset: 0 !important;
  width: 100vw !important;
  max-width: 100vw !important;
  height: 100dvh !important;
  max-height: 100dvh !important;
  z-index: 100005;
  margin: 0 !important;
  border-radius: 0 !important;
  background: var(--bg-panel);
  border: none !important;
  box-shadow: none !important;
}

.bg-gcal-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding: 13px 16px;
  background: var(--bg-subbar);
  border-bottom: 1px solid var(--bg-border);
  flex-shrink: 0;
}

.bg-gcal-nav-left {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.bg-gcal-arrows {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.bg-gcal-period-heading {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
}

.bg-gcal-title {
  margin: 0 !important;
  font-size: 1.06rem !important;
  font-weight: 800 !important;
  letter-spacing: -0.015em;
  color: var(--bg-text) !important;
  white-space: nowrap;
}

.bg-gcal-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--theme-pri-bg);
  border: 1px solid var(--theme-pri-bd);
  color: var(--theme-pri-bright);
  font-size: 0.72rem;
  font-weight: 800;
  white-space: nowrap;
}

.bg-gcal-nav-right {
  display: flex;
  align-items: center;
  gap: 11px;
  flex-wrap: wrap;
  margin-left: auto;
}

.bg-gcal-legend {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--bg-text-sec);
}

.bg-gcal-leg-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}

.bg-gcal-leg-item i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}
.bg-gcal-leg-item i.is-amber {
  background: #f59e0b;
  box-shadow: 0 0 6px rgba(245, 158, 11, 0.55);
}
.bg-gcal-leg-item i.is-emerald {
  background: #10b981;
  box-shadow: 0 0 6px rgba(16, 185, 129, 0.55);
}
.bg-gcal-leg-item i.is-theme-pri {
  background: var(--theme-pri-bright);
  box-shadow: 0 0 6px var(--theme-pri-shadow);
}
.bg-gcal-leg-item i.is-rose {
  background: #f43f5e;
  box-shadow: 0 0 6px rgba(244, 63, 94, 0.55);
}

.bg-gcal-leg-hint {
  color: var(--bg-text-muted);
  font-size: 0.72rem;
  white-space: nowrap;
}

.is-gcal-fs-btn {
  height: 36px;
  padding: 0 11px;
  border-radius: 10px;
}

/* --- SUB-VIEW 1: GOOGLE CALENDAR WEEK GRID (7 COLS x SÁNG / CHIỀU) --- */
.bg-gcal-week-wrap {
  width: 100%;
  overflow-x: auto;
  overflow-y: auto;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.bg-gcal-week-head-grid,
.bg-gcal-week-lane {
  display: grid;
  grid-template-columns: 98px repeat(7, minmax(0, 1fr));
  min-width: 860px;
}

/* Week Header: Emerald Green + White Text (Dark) | Ocean Blue + White Text (Light) */
.bg-gcal-week-head-grid {
  position: sticky;
  top: 0;
  z-index: 6;
  background: linear-gradient(135deg, #059669 0%, #047857 100%);
  color: #ffffff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    0 4px 12px -4px rgba(4, 120, 87, 0.45);
}

.report-container.page.theme-light-blue .bg-gcal-week-head-grid {
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%);
  color: #ffffff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.24);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    0 4px 12px -4px rgba(2, 132, 199, 0.35);
}

.bg-gcal-corner-cell {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px 8px;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #ffffff;
  border-right: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(0, 0, 0, 0.12);
}

.bg-gcal-day-head {
  padding: 10px 8px 9px;
  border-right: 1px solid rgba(255, 255, 255, 0.18);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  position: relative;
  color: #ffffff;
  transition: background 0.16s ease;
}
.bg-gcal-day-head:last-child {
  border-right: none;
}

.bg-gcal-day-head.is-today {
  background: rgba(255, 255, 255, 0.14);
}
.bg-gcal-day-head.is-today::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 12px;
  right: 12px;
  height: 3px;
  border-radius: 3px 3px 0 0;
  background: #ffffff;
  box-shadow: 0 0 10px rgba(255, 255, 255, 0.65);
}

.bg-gcal-wd-name,
.bg-gcal-day-head.is-today .bg-gcal-wd-name,
.bg-gcal-day-head.is-sun .bg-gcal-wd-name {
  font-size: 0.7rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #ffffff;
}

.bg-gcal-day-num-row {
  display: inline-flex;
  align-items: baseline;
  gap: 2px;
}

.bg-gcal-day-circle {
  min-width: 30px;
  height: 30px;
  padding: 0 5px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.04rem;
  font-weight: 800;
  color: var(--bg-text);
  line-height: 1;
}
.bg-gcal-day-circle.is-sm {
  min-width: 26px;
  height: 26px;
  font-size: 0.86rem;
}
.bg-gcal-day-circle.is-today {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #ffffff !important;
  box-shadow: 0 3px 10px rgba(5, 150, 105, 0.42);
}
.report-container.page.theme-light-blue .bg-gcal-day-circle.is-today {
  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%);
  color: #ffffff !important;
  box-shadow: 0 3px 10px rgba(2, 132, 199, 0.38);
}

/* Inside Week Header Bar: Keep ALL text crisp white (#ffffff) */
.bg-gcal-week-head-grid .bg-gcal-day-circle,
.bg-gcal-week-head-grid .bg-gcal-day-head.is-sun .bg-gcal-day-circle {
  color: #ffffff;
}
.bg-gcal-week-head-grid .bg-gcal-day-circle.is-today,
.report-container.page.theme-light-blue .bg-gcal-week-head-grid .bg-gcal-day-circle.is-today {
  background: rgba(255, 255, 255, 0.24);
  border: 2px solid #ffffff;
  color: #ffffff !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.18);
}

.bg-gcal-month-sub {
  font-size: 0.72rem;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.92);
}

.bg-gcal-day-count {
  margin-top: 1px;
  padding: 1.5px 8px;
  border-radius: 999px;
  font-size: 0.66rem;
  font-weight: 800;
  background: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.36);
  color: #ffffff;
  white-space: nowrap;
}

/* Week Lanes: Optional Reminder Strip + BUỔI SÁNG + BUỔI CHIỀU */
.bg-gcal-week-lane {
  border-bottom: 1px solid var(--bg-border);
  flex: 1 0 auto;
}
.bg-gcal-week-lane:last-child {
  border-bottom: none;
}

.bg-gcal-week-lane.is-morning-lane,
.bg-gcal-week-lane.is-afternoon-lane {
  min-height: 158px;
}
.bg-gcal-workspace.is-fullscreen .bg-gcal-week-lane.is-morning-lane,
.bg-gcal-workspace.is-fullscreen .bg-gcal-week-lane.is-afternoon-lane {
  min-height: calc((100dvh - 180px) / 2);
}

.bg-gcal-axis-cell {
  border-right: 1px solid var(--bg-border);
  padding: 14px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  text-align: center;
  background: var(--bg-soft-pad);
  user-select: none;
}
.bg-gcal-axis-cell.is-morning {
  background: linear-gradient(180deg, rgba(56, 189, 248, 0.08) 0%, transparent 100%);
}
.bg-gcal-axis-cell.is-afternoon {
  background: linear-gradient(180deg, rgba(245, 158, 11, 0.08) 0%, transparent 100%);
}
.bg-gcal-axis-cell.is-reminder {
  padding: 8px 6px;
  flex-direction: row;
  gap: 4px;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--sem-rose-bright);
  background: var(--sem-rose-bg);
}

.bg-gcal-axis-icon {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.bg-gcal-axis-icon.is-sky {
  background: var(--sem-sky-bg);
  border: 1px solid var(--sem-sky-bd);
  color: var(--sem-sky-bright);
}
.bg-gcal-axis-icon.is-amber {
  background: var(--sem-amber-bg);
  border: 1px solid var(--sem-amber-bd);
  color: var(--sem-amber-bright);
}

.bg-gcal-axis-lbl {
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--bg-text-sec);
  line-height: 1.25;
}

/* Week Day × Period Cell */
.bg-gcal-slot {
  border-right: 1px solid var(--bg-border);
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-width: 0;
  position: relative;
  transition: background 0.16s ease, box-shadow 0.16s ease;
}
.bg-gcal-slot:last-child {
  border-right: none;
}
.bg-gcal-slot.is-today {
  background: rgba(56, 189, 248, 0.035);
}
.bg-gcal-slot.is-sun:not(.is-today) {
  background: rgba(244, 63, 94, 0.018);
}
.bg-gcal-slot.is-reminder-slot {
  padding: 6px;
  gap: 4px;
  min-height: 38px;
  justify-content: center;
}
.bg-gcal-slot.is-drag-over {
  background: rgba(16, 185, 129, 0.12) !important;
  box-shadow: inset 0 0 0 2px var(--sem-emerald-bright);
}

.bg-gcal-rem-chip {
  width: 100% !important;
  margin: 0 !important;
  padding: 4px 7px;
  border-radius: 7px;
  background: var(--sem-rose-bg);
  border: 1px solid var(--sem-rose-bd);
  color: var(--sem-rose-bright);
  font-size: 0.71rem;
  font-weight: 700;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}
.bg-gcal-rem-chip:hover {
  background: rgba(244, 63, 94, 0.22);
}

/* Empty Slot Prominent '+' Quick-Add Button */
.bg-gcal-empty-add {
  width: 100% !important;
  height: 100%;
  min-height: 116px;
  margin: 0 !important;
  padding: 12px 8px;
  border-radius: 12px;
  background: transparent;
  border: 1.5px dashed var(--bg-border-strong);
  color: var(--bg-text-muted);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  transition: all 0.18s var(--bg-ease);
}

.bg-gcal-plus-circle {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-border-strong);
  color: var(--bg-text-sec);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.18s var(--bg-ease);
}

.bg-gcal-plus-txt {
  font-size: 0.73rem;
  font-weight: 700;
  opacity: 0.75;
  white-space: nowrap;
  transition: all 0.18s var(--bg-ease);
}

.bg-gcal-empty-add.is-morning:hover {
  background: var(--sem-sky-bg);
  border-color: var(--sem-sky-bright);
  color: var(--sem-sky-bright);
}
.bg-gcal-empty-add.is-morning:hover .bg-gcal-plus-circle {
  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%);
  border-color: transparent;
  color: #ffffff;
  transform: scale(1.08);
  box-shadow: 0 4px 12px rgba(14, 165, 233, 0.38);
}

.bg-gcal-empty-add.is-afternoon:hover {
  background: var(--sem-amber-bg);
  border-color: var(--sem-amber-bright);
  color: var(--sem-amber-bright);
}
.bg-gcal-empty-add.is-afternoon:hover .bg-gcal-plus-circle {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  border-color: transparent;
  color: #ffffff;
  transform: scale(1.08);
  box-shadow: 0 4px 12px rgba(245, 158, 11, 0.38);
}

.bg-gcal-empty-add:hover .bg-gcal-plus-txt {
  opacity: 1;
}

/* Elevate hovered slot/day cell so scaled card never slips under sibling column */
.bg-gcal-slot:hover,
.bg-gcal-slot:focus-within {
  z-index: 5;
}

/* Google Calendar Event Card (Hover Scale + Toggle Files + Bottom 3 Action Buttons) */
.bg-gcal-event {
  position: relative;
  min-width: 0;
  max-width: 100%;
  padding: 8px 9px;
  border-radius: 10px;
  background: var(--bg-group-surface);
  border: 1px solid var(--bg-group-border);
  border-left: 3.5px solid var(--sem-amber);
  box-shadow: 0 3px 10px -4px rgba(2, 6, 23, 0.25);
  display: flex;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  transform-origin: center center;
  transition:
    transform 0.2s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.18s ease,
    box-shadow 0.2s ease;
}

.bg-gcal-event:hover,
.bg-gcal-event.is-files-open {
  z-index: 8;
  border-color: var(--theme-pri-bd);
  box-shadow:
    0 12px 26px -6px rgba(2, 6, 23, 0.48),
    0 0 0 1px var(--theme-pri-ring);
}

.bg-gcal-event:hover {
  transform: translateY(-2px) scale(1.026);
}

.report-container.page.theme-light-blue .bg-gcal-event:hover,
.report-container.page.theme-light-blue .bg-gcal-event.is-files-open {
  border-color: rgba(2, 132, 199, 0.44);
  box-shadow:
    0 12px 24px -6px rgba(15, 23, 42, 0.16),
    0 0 0 1px rgba(2, 132, 199, 0.2);
}

.bg-gcal-event.is-pending {
  border-left-color: #f59e0b;
}

/* Completed Calendar Card: Solid Emerald Green + White Text (Dark) | Solid Ocean Blue + White Text (Light) */
.bg-gcal-event.is-done {
  background: linear-gradient(135deg, #059669 0%, #047857 100%);
  border-color: rgba(52, 211, 153, 0.46);
  border-left: 3.5px solid #6ee7b7;
  color: #ffffff;
  box-shadow: 0 6px 16px -6px rgba(5, 150, 105, 0.52);
}

.report-container.page.theme-light-blue .bg-gcal-event.is-done {
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%);
  border-color: rgba(56, 189, 248, 0.52);
  border-left: 3.5px solid #bae6fd;
  color: #ffffff;
  box-shadow: 0 6px 16px -6px rgba(2, 132, 199, 0.44);
}

.bg-gcal-event.is-done:hover,
.bg-gcal-event.is-done.is-files-open {
  border-color: rgba(255, 255, 255, 0.65);
}

.bg-gcal-event.is-failed {
  opacity: 1 !important;
  filter: none !important;
  border-color: rgba(244, 63, 94, 0.34);
  border-left-color: #f43f5e;
  background: linear-gradient(135deg, rgba(244, 63, 94, 0.14) 0%, var(--bg-group-surface) 78%);
}
.report-container.page.theme-light-blue .bg-gcal-event.is-failed {
  border-color: #fecdd3;
  border-left-color: #e11d48;
  background: linear-gradient(135deg, #fff1f2 0%, #ffffff 78%);
}
.bg-gcal-event.is-compact {
  padding: 5px 6px;
  border-radius: 8px;
  gap: 4px;
}

.bg-gcal-event.dragging-task {
  opacity: 0.45;
  transform: scale(0.97) !important;
}
.bg-gcal-event.drop-success-pulse {
  box-shadow: 0 0 0 2px var(--theme-pri-bright), 0 8px 18px var(--theme-pri-shadow);
}

.bg-gcal-event-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  min-width: 0;
}

.bg-gcal-event-badges {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
  min-width: 0;
}

.bg-gcal-prio-tag {
  padding: 1.5px 5px;
  border-radius: 5px;
  background: var(--sem-rose-bg);
  border: 1px solid var(--sem-rose-bd);
  color: var(--sem-rose-bright);
  font-size: 0.61rem;
  font-weight: 800;
  letter-spacing: 0.03em;
  white-space: nowrap;
}

.bg-gcal-cus-tag {
  padding: 1.5px 6px;
  border-radius: 5px;
  background: var(--theme-pri-bg);
  border: 1px solid var(--theme-pri-bd);
  color: var(--theme-pri-bright);
  font-size: 0.63rem;
  font-weight: 700;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bg-gcal-event.is-done .bg-gcal-prio-tag {
  background: rgba(225, 29, 72, 0.88);
  border-color: rgba(255, 255, 255, 0.38);
  color: #ffffff;
}

.bg-gcal-event.is-done .bg-gcal-cus-tag {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.36);
  color: #ffffff;
}

.bg-gcal-event-title {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--bg-text);
  line-height: 1.36;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  word-break: break-word;
}
/* Circular Checkmark Icon on Completed Calendar Tasks */
.bg-gcal-title-row {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  min-width: 0;
}

.bg-gcal-title-row .bg-gcal-event-title {
  flex: 1 1 0;
  min-width: 0;
}

.bg-gcal-done-circle {
  width: 17px;
  height: 17px;
  border-radius: 999px;
  background: #ffffff;
  color: #047857;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 1px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.22);
}

.report-container.page.theme-light-blue .bg-gcal-done-circle {
  background: #ffffff;
  color: #0284c7;
}

.bg-gcal-event.is-compact .bg-gcal-done-circle {
  width: 15px;
  height: 15px;
}

.bg-gcal-event.is-compact .bg-gcal-done-circle svg {
  width: 9.5px;
  height: 9.5px;
}

.bg-gcal-event.is-compact .bg-gcal-event-title {
  font-size: 0.74rem;
  -webkit-line-clamp: 2;
}
.bg-gcal-event.is-done .bg-gcal-event-title {
  color: #ffffff !important;
  opacity: 1;
}

.bg-gcal-event-note {
  font-size: 0.72rem;
  color: var(--bg-text-muted);
  line-height: 1.32;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  word-break: break-word;
}
.bg-gcal-event.is-done .bg-gcal-event-note {
  color: rgba(255, 255, 255, 0.92) !important;
}

/* --- Collapsible Attachment Section (Above Bottom 3 Action Buttons) --- */
.bg-gcal-files-box {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
  max-width: 100%;
  margin-top: 2px;
}

.bg-gcal-files-toggle {
  width: 100% !important;
  max-width: 100%;
  min-width: 0;
  margin: 0 !important;
  padding: 3.5px 7px !important;
  border-radius: 7px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-border-strong);
  color: var(--theme-pri-bright);
  font-size: 0.68rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.bg-gcal-files-toggle.is-compact {
  padding: 2.5px 6px !important;
  font-size: 0.65rem;
}

.bg-gcal-files-toggle:hover,
.bg-gcal-files-toggle.is-open {
  background: var(--theme-pri-bg);
  border-color: var(--theme-pri-bd);
}

.bg-gcal-event.is-done .bg-gcal-files-toggle {
  background: rgba(0, 0, 0, 0.18);
  border-color: rgba(255, 255, 255, 0.34);
  color: #ffffff;
}
.bg-gcal-event.is-done .bg-gcal-files-toggle:hover,
.bg-gcal-event.is-done .bg-gcal-files-toggle.is-open {
  background: rgba(0, 0, 0, 0.28);
  border-color: rgba(255, 255, 255, 0.55);
}

.bg-gcal-files-toggle-left {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  overflow: hidden;
}

.bg-gcal-files-toggle-left svg {
  flex-shrink: 0;
}

.bg-gcal-files-toggle-left span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bg-gcal-files-caret {
  font-size: 0.68rem;
  line-height: 1;
  flex-shrink: 0;
  opacity: 0.85;
}

.bg-gcal-files-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  max-width: 100%;
  padding: 0;
}

.bg-gcal-file-item {
  display: flex;
  align-items: center;
  gap: 3.5px;
  min-width: 0;
  max-width: 100%;
  padding: 2.5px 4px;
  border-radius: 6px;
  background: var(--bg-well);
  border: 1px solid var(--bg-border);
}

.bg-gcal-event.is-done .bg-gcal-file-item {
  background: rgba(0, 0, 0, 0.22);
  border-color: rgba(255, 255, 255, 0.28);
}

.bg-gcal-file-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 15px;
  height: 15px;
  flex-shrink: 0;
}

.bg-gcal-file-ic svg {
  width: 15px;
  height: 15px;
  display: block;
}

.bg-gcal-file-name {
  flex: 1 1 0;
  min-width: 0;
  font-size: 0.65rem;
  font-weight: 700;
  color: var(--bg-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.25;
}

.bg-gcal-event.is-done .bg-gcal-file-name {
  color: #ffffff;
}

.bg-gcal-file-btns {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}

.bg-gcal-file-act {
  width: 18px !important;
  height: 18px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 4.5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.14s ease, color 0.14s ease, border-color 0.14s ease;
}

.bg-gcal-file-act.is-view {
  background: var(--sem-sky-bg);
  border: 1px solid var(--sem-sky-bd);
  color: var(--sem-sky-bright);
}
.bg-gcal-file-act.is-view:hover {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

.bg-gcal-file-act.is-dl {
  background: var(--theme-pri-bg);
  border: 1px solid var(--theme-pri-bd);
  color: var(--theme-pri-bright);
}
.bg-gcal-file-act.is-dl:hover {
  background: var(--theme-pri);
  border-color: var(--theme-pri);
  color: #ffffff;
}

.bg-gcal-event.is-done .bg-gcal-file-act.is-view,
.bg-gcal-event.is-done .bg-gcal-file-act.is-dl {
  background: rgba(255, 255, 255, 0.22);
  border-color: rgba(255, 255, 255, 0.38);
  color: #ffffff;
}
.bg-gcal-event.is-done .bg-gcal-file-act.is-view:hover,
.bg-gcal-event.is-done .bg-gcal-file-act.is-dl:hover {
  background: #ffffff;
  border-color: #ffffff;
  color: #0f172a;
}

/* --- Bottom 3 Action Buttons: [Xoá | Fail | Xong] ---
   - Pending (.is-pending): Permanently visible without hover!
   - Done (.is-done) & Failed (.is-failed): Hidden at rest, revealed on hover.
   - Styled identically to Detail Card (.tl-rect-actions)! */
.bg-gcal-card-foot-acts {
  display: flex;
  align-items: center;
  gap: 3px;
  min-width: 0;
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  margin-top: 0;
  padding-top: 0;
  border-top: 0 solid transparent;
  pointer-events: none;
  transition:
    max-height 0.2s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.16s ease,
    margin-top 0.16s ease,
    padding-top 0.16s ease,
    border-color 0.16s ease;
}

.bg-gcal-event.is-pending .bg-gcal-card-foot-acts {
  max-height: none;
  opacity: 1;
  overflow: visible;
  margin-top: 5px;
  padding-top: 6px;
  border-top: 1px solid var(--bg-border);
  pointer-events: auto;
}

.bg-gcal-event.is-done:hover .bg-gcal-card-foot-acts,
.bg-gcal-event.is-done:focus-within .bg-gcal-card-foot-acts {
  max-height: 38px;
  opacity: 1;
  margin-top: 5px;
  padding-top: 6px;
  border-top: 1px solid rgba(255, 255, 255, 0.26);
  pointer-events: auto;
}

.bg-gcal-event.is-failed:hover .bg-gcal-card-foot-acts,
.bg-gcal-event.is-failed:focus-within .bg-gcal-card-foot-acts {
  max-height: 38px;
  opacity: 1;
  margin-top: 5px;
  padding-top: 6px;
  border-top: 1px solid var(--bg-border);
  pointer-events: auto;
}

.bg-gcal-foot-btn {
  flex: 1 1 auto;
  min-width: 0;
  width: auto !important;
  height: 24px !important;
  margin: 0 !important;
  padding: 0 3px !important;
  border-radius: 6px;
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  line-height: 1;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease, transform 0.12s ease;
}

.bg-gcal-event.is-compact .bg-gcal-foot-btn {
  height: 22px !important;
  padding: 0 2.5px !important;
  font-size: 0.61rem;
  gap: 1.5px;
}

.bg-gcal-foot-btn svg {
  width: 9px;
  height: 9px;
  flex-shrink: 0;
}

.bg-gcal-foot-btn:active {
  transform: scale(0.96);
}

/* Xoá — Ghost Red Outline + Red Text (Exact Detail Card .tl-action-delete match) */
.bg-gcal-foot-btn.is-del {
  background: transparent;
  border: 1.5px solid rgba(248, 113, 113, 0.38);
  color: #f87171;
}
.report-container.page.theme-light-blue .bg-gcal-foot-btn.is-del {
  background: transparent;
  border: 1.5px solid rgba(225, 29, 72, 0.38);
  color: #e11d48;
}
.bg-gcal-foot-btn.is-del:hover {
  background: #e11d48 !important;
  border-color: #e11d48 !important;
  color: #ffffff !important;
  box-shadow: 0 3px 10px -2px rgba(225, 29, 72, 0.42);
}

/* Inside Solid Green/Blue Completed Card: Frosted White-Border Xoá Pill */
.bg-gcal-event.is-done .bg-gcal-foot-btn.is-del {
  background: rgba(0, 0, 0, 0.22);
  border: 1.5px solid rgba(255, 255, 255, 0.45);
  color: #ffffff;
}
.bg-gcal-event.is-done .bg-gcal-foot-btn.is-del:hover {
  background: #e11d48 !important;
  border-color: #ffffff !important;
  color: #ffffff !important;
}

/* Fail — Frosted Neutral Slate Glass Pill turning Orange on Hover (Exact Detail Card .tl-action-fail match) */
.bg-gcal-foot-btn.is-fail {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: #cbd5e1;
}
.report-container.page.theme-light-blue .bg-gcal-foot-btn.is-fail {
  background: rgba(15, 23, 42, 0.06);
  border: 1px solid #cbd5e1;
  color: #334155;
}
.bg-gcal-foot-btn.is-fail:hover {
  background: linear-gradient(135deg, #f97316 0%, #ea580c 100%) !important;
  border-color: transparent !important;
  color: #ffffff !important;
  box-shadow: 0 3px 10px -2px rgba(249, 115, 22, 0.42);
}

/* Xong — Solid Theme-Priority Gradient + White Bold Text (Dark = Emerald Green | Light = Ocean Blue) */
.bg-gcal-foot-btn.is-done {
  background: var(--theme-pri-grad);
  border: 1px solid transparent;
  color: #ffffff;
  box-shadow: 0 3px 10px -2px var(--theme-pri-shadow);
}
.bg-gcal-foot-btn.is-done:hover {
  filter: brightness(1.07);
  transform: translateY(-1px);
}

/* Subtle '+ Thêm' button below populated slot */
.bg-gcal-slot-more-add {
  width: 100% !important;
  margin: auto 0 0 0 !important;
  height: 28px;
  padding: 0 8px;
  border-radius: 8px;
  background: transparent;
  border: 1px dashed var(--bg-border-strong);
  color: var(--bg-text-muted);
  font-size: 0.72rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.16s var(--bg-ease);
}
.bg-gcal-slot-more-add:hover {
  background: var(--theme-pri-bg);
  border-color: var(--theme-pri-bd);
  color: var(--theme-pri-bright);
}

/* --- SUB-VIEW 2: GOOGLE CALENDAR MONTH GRID AUGMENTATIONS --- */
.bg-gcal-month-wrap {
  padding: 14px 16px 16px;
  overflow-x: auto;
  overflow-y: auto;
  flex: 1;
}

.bg-gcal-month-block {
  min-width: 860px;
}

/* Month Header: Emerald Green + White Text (Dark) | Ocean Blue + White Text (Light) */
.bg-gcal-month-wrap .bg-cal-month-title {
  display: inline-flex;
  align-items: center;
  padding: 7px 14px;
  margin-bottom: 10px;
  border-radius: 10px;
  border-bottom: none;
  background: linear-gradient(135deg, #059669 0%, #047857 100%);
  color: #ffffff;
  font-size: 0.88rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    0 3px 10px -3px rgba(4, 120, 87, 0.45);
}

.report-container.page.theme-light-blue .bg-gcal-month-wrap .bg-cal-month-title {
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%);
  color: #ffffff;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    0 3px 10px -3px rgba(2, 132, 199, 0.35);
}

.bg-gcal-month-wrap .bg-cal-weekdays {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0;
  margin-bottom: 10px;
  border-radius: 12px;
  overflow: hidden;
  background: linear-gradient(135deg, #059669 0%, #047857 100%);
  border: 1px solid rgba(16, 185, 129, 0.36);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    0 4px 12px -4px rgba(4, 120, 87, 0.45);
}

.report-container.page.theme-light-blue .bg-gcal-month-wrap .bg-cal-weekdays {
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%);
  border: 1px solid rgba(2, 132, 199, 0.38);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    0 4px 12px -4px rgba(2, 132, 199, 0.35);
}

.bg-gcal-month-wrap .bg-cal-wd {
  text-align: center;
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 10px 6px;
  border-radius: 0;
  background: transparent;
  color: #ffffff;
  border-right: 1px solid rgba(255, 255, 255, 0.18);
}

.bg-gcal-month-wrap .bg-cal-wd:last-child {
  border-right: none;
}

.bg-gcal-month-wrap .bg-move-day-cell {
  overflow: visible;
  min-width: 0;
  position: relative;
}

.bg-gcal-month-wrap .bg-move-day-cell:hover,
.bg-gcal-month-wrap .bg-move-day-cell:focus-within {
  z-index: 5;
}

.bg-gcal-month-wrap .bg-move-day-head {
  background: transparent;
  border-radius: 11px 11px 0 0;
}

.bg-gcal-month-wrap .bg-move-zones {
  min-width: 0;
  padding: 5px;
  gap: 5px;
}

.bg-gcal-month-wrap .bg-move-day-cell.is-today {
  border-color: var(--sem-emerald-bd);
  box-shadow: inset 0 0 0 1px rgba(16, 185, 129, 0.28);
}

.report-container.page.theme-light-blue .bg-gcal-month-wrap .bg-move-day-cell.is-today {
  border-color: var(--sem-sky-bd);
  box-shadow: inset 0 0 0 1px rgba(2, 132, 199, 0.25);
}

/* Month Sáng & Chiều Zones: NO colored background fill — ONLY colored text labels */
.bg-gcal-month-wrap .bg-move-zone.is-morning,
.bg-gcal-month-wrap .bg-move-zone.is-afternoon {
  background: transparent;
  border: 1px dashed var(--bg-border);
  min-width: 0;
  padding: 5px;
  gap: 5px;
}

.bg-gcal-month-wrap .bg-move-zone.drag-over-sang {
  background: rgba(56, 189, 248, 0.12);
  border-color: var(--sem-sky-bright);
}

.bg-gcal-month-wrap .bg-move-zone.drag-over-chieu {
  background: rgba(245, 158, 11, 0.12);
  border-color: var(--sem-amber-bright);
}

.bg-move-zone-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}

.bg-move-zone-lbl.is-amber {
  color: var(--sem-amber-bright);
}

.bg-move-zone-plus {
  width: 20px !important;
  height: 20px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 6px;
  background: var(--bg-panel);
  border: 1px solid var(--bg-border-strong);
  color: var(--bg-text-sec);
  font-size: 0.84rem;
  font-weight: 800;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.bg-move-zone-plus:hover {
  background: var(--theme-pri);
  border-color: transparent;
  color: #ffffff;
}

.bg-gcal-month-empty-add {
  width: 100% !important;
  flex: 1;
  min-height: 44px;
  margin: 0 !important;
  padding: 0;
  border-radius: 8px;
  background: transparent;
  border: 1px dashed var(--bg-border-strong);
  color: var(--bg-text-muted);
  font-size: 1.05rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.16s var(--bg-ease);
}
.bg-gcal-month-empty-add:hover {
  background: var(--bg-soft-pad);
  border-color: var(--theme-pri-bright);
  color: var(--theme-pri-bright);
  transform: scale(1.01);
}

/* ============================================================================
   RESPONSIVE BREAKPOINTS (<= 1100px COMPACT SHELL & <= 768px MOBILE)
============================================================================ */
@media (max-width: 1100px) {
  .report-container.page {
    padding: 12px 12px calc(112px + env(safe-area-inset-bottom, 0px)) !important;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
    overflow-x: clip !important;
  }

  .bg-hide-compact {
    display: none !important;
  }

  .bg-bento-deck {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .bg-board-toolbar {
    justify-content: flex-end;
  }

  .bg-board-view-cluster {
    margin-left: auto;
  }

  .bg-report-3col-grid,
  .bg-dist-step2-grid,
  .bg-grid-3 {
    grid-template-columns: 1fr;
  }

  /* Mobile Floating Glass Bottom Process Dock */
  .bg-mobile-dock {
    position: fixed;
    left: 50%;
    bottom: calc(12px + env(safe-area-inset-bottom, 0px));
    transform: translate3d(-50%, 0, 0);
    width: min(520px, calc(100vw - 20px));
    z-index: 955;
    background: var(--bg-dock-glass);
    backdrop-filter: blur(20px) saturate(185%);
    -webkit-backdrop-filter: blur(20px) saturate(185%);
    border: 1px solid var(--bg-glass-border);
    border-top: 1px solid var(--theme-pri-bd);
    border-radius: 20px;
    padding: 6px 8px;
    box-shadow:
      inset 0 1px 0 var(--bg-specular-strong),
      var(--bg-shadow-pop);
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 4px;
    transition: bottom 0.34s var(--bg-ease), transform 0.24s var(--bg-ease), opacity 0.18s ease;
  }

  .bg-mobile-dock.is-modal-hidden {
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transform: translate3d(-50%, calc(100% + 96px + env(safe-area-inset-bottom, 0px)), 0);
  }

  .bg-dock-btn {
    width: 100% !important;
    margin: 0 !important;
    padding: 6px 2px;
    border-radius: 13px;
    background: transparent;
    color: var(--bg-text-sec);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
  }

  .bg-dock-btn.is-primary {
    background: var(--theme-pri-bg);
    border: 1px solid var(--theme-pri-bd);
    color: var(--theme-pri-bright);
  }

  .bg-dock-btn.is-primary.is-center-cta {
    background: var(--theme-pri-grad) !important;
    border: 1px solid rgba(255, 255, 255, 0.34) !important;
    color: #ffffff !important;
    transform: translateY(-4px);
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.36),
      0 8px 18px -4px var(--theme-pri-shadow);
  }

  .bg-dock-btn.is-primary.is-center-cta:active {
    transform: translateY(-2px) scale(0.96);
  }

  .bg-dock-btn.is-primary.is-center-cta .bg-dock-icon {
    width: 24px;
    height: 24px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.22);
    color: #ffffff;
  }

  .bg-dock-btn.is-primary.is-center-cta .bg-dock-lbl {
    color: #ffffff !important;
    font-weight: 800;
  }

  .bg-dock-icon {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .bg-dock-badge {
    position: absolute;
    top: -6px;
    right: -13px;
    min-width: 17px;
    height: 16px;
    padding: 0 4px;
    border-radius: 999px;
    background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
    color: #ffffff;
    font-size: 0.64rem;
    font-weight: 800;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .bg-dock-lbl {
    font-size: 0.68rem;
    font-weight: 700;
    white-space: nowrap;
  }

  .report-container.page {
    --mobile-modal-head-top: max(calc(env(safe-area-inset-top, 0px) + 6px), 52px);
  }

  /* Fullscreen Mobile Sheet for Work Modals (.is-mobile-sheet / .is-fullscreen-card) */
  .bg-modal-overlay:has(.bg-modal-card.is-mobile-sheet),
  .bg-modal-overlay:has(.bg-modal-card.is-fullscreen-card) {
    padding: 0;
    align-items: stretch;
  }

  .bg-modal-card.is-mobile-sheet {
    max-width: 100% !important;
    width: 100% !important;
    height: 100dvh;
    max-height: 100dvh;
    border-radius: 0;
    border: none;
  }

  /* Non-Fullscreen Centered Dialogs on Mobile: keep centered with >= 56px top safe clearance below clock/battery */
  .bg-modal-overlay:not(.is-fullscreen-modal):not(:has(.bg-modal-card.is-mobile-sheet)):not(:has(.bg-modal-card.is-fullscreen-card)) {
    padding: max(calc(env(safe-area-inset-top, 0px) + 12px), 56px) 14px calc(16px + env(safe-area-inset-bottom, 0px)) !important;
    align-items: center;
  }

  .bg-modal-card:not(.is-mobile-sheet):not(.is-fullscreen-card) {
    max-height: calc(100dvh - max(calc(env(safe-area-inset-top, 0px) + 28px), 76px) - env(safe-area-inset-bottom, 0px));
  }

  .dt-only-head {
    display: none !important;
  }

  .m-grab-head-stack {
    display: flex;
    flex-direction: column;
    background: var(--bg-panel-elev);
    border-bottom: 1px solid var(--bg-border);
    padding: 10px 14px 10px;
    flex-shrink: 0;
  }

  .bg-modal-card.is-mobile-sheet > .m-grab-head-stack,
  .bg-modal-card.is-fullscreen-card > .m-grab-head-stack {
    padding: var(--mobile-modal-head-top, max(calc(env(safe-area-inset-top, 0px) + 6px), 52px)) 14px 12px !important;
  }

  .bg-modal-card.is-mobile-sheet > .m-grab-head-stack > .m-grab-pill,
  .bg-modal-card.is-fullscreen-card > .m-grab-head-stack > .m-grab-pill {
    display: none !important;
  }

  .m-grab-head-stack .bg-modal-close {
    width: 36px !important;
    height: 36px !important;
    border-radius: 11px;
  }

  .bg-gcal-workspace.is-fullscreen .bg-gcal-toolbar {
    padding-top: var(--mobile-modal-head-top, max(calc(env(safe-area-inset-top, 0px) + 6px), 52px)) !important;
  }

  /* Lightbox on Mobile: pin close button safely below clock & battery icon */
  .bg-lightbox-overlay {
    padding: max(calc(env(safe-area-inset-top, 0px) + 52px), 96px) 14px calc(20px + env(safe-area-inset-bottom, 0px)) !important;
  }

  .bg-lightbox-close {
    position: fixed !important;
    top: max(calc(env(safe-area-inset-top, 0px) + 6px), 52px) !important;
    right: 14px !important;
    width: 38px !important;
    height: 38px !important;
    z-index: 5 !important;
    background: rgba(15, 23, 42, 0.76) !important;
    border: 1px solid rgba(255, 255, 255, 0.24) !important;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
  }

  .m-grab-pill {
    width: 36px;
    height: 4px;
    border-radius: 999px;
    background: var(--bg-border-strong);
    margin: 0 auto 8px;
  }

  .m-grab-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
  }

  .m-grab-title-wrap {
    display: flex;
    flex-direction: column;
    min-width: 0;
  }

  .m-grab-title {
    margin: 0 !important;
    font-size: 0.98rem !important;
    font-weight: 800 !important;
    color: var(--bg-text) !important;
  }

  .m-grab-sub {
    font-size: 0.72rem;
    color: var(--bg-text-muted);
  }

  .bg-modal-foot {
    padding: 10px 14px calc(12px + env(safe-area-inset-bottom, 0px));
  }

  /* CRITICAL: baogiaDialog stays Centered Non-Fullscreen Rounded Card on Mobile with >= 56px top safe clearance! */
  .baogia-dialog-overlay {
    padding: max(calc(env(safe-area-inset-top, 0px) + 12px), 56px) 16px calc(16px + env(safe-area-inset-bottom, 0px)) !important;
    align-items: center !important;
  }

  .baogia-dialog-card {
    width: min(420px, calc(100vw - 24px)) !important;
    height: auto !important;
    max-height: calc(100dvh - max(calc(env(safe-area-inset-top, 0px) + 28px), 76px) - env(safe-area-inset-bottom, 0px)) !important;
    border-radius: 20px !important;
  }

  .baogia-dialog-card > .m-grab-head-stack {
    padding: 8px 14px 10px !important;
  }
}

@media (max-width: 768px) {
  :global(.app-layout:has(.report-container.page) .main-content) {
    padding-bottom: 0 !important;
  }

  .report-container.page {
    min-height: calc(100vh - env(safe-area-inset-top, 0px)) !important;
    min-height: calc(100dvh - env(safe-area-inset-top, 0px)) !important;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
    overflow-x: clip !important;
    padding: 12px 10px calc(176px + env(safe-area-inset-bottom, 0px)) !important;
  }

  .bg-mobile-dock {
    bottom: calc(74px + env(safe-area-inset-bottom, 0px));
    width: calc(100vw - 20px);
    max-width: 500px;
  }

  :global(.app-layout.mobile-nav-hidden .report-container.page .bg-mobile-dock) {
    bottom: calc(10px + env(safe-area-inset-bottom, 0px));
  }

  .bg-hide-sm {
    display: none !important;
  }

  /* =========================================================================
     V7.8 MOBILE OVERHAUL (<= 768px):
     1. Compact 1-Row Search + Collapsible Filter Panel + 1-Row 4-Pill Status Bar
     2. Centered '+ Thêm mới' in Mobile Bottom Dock
     3. Full-Width 3-Tab View Switcher & Unified PC Detail Cards on Mobile
     4. Mobile Week Calendar (3A) & Mobile Month Matrix + Day Agenda (4)
     ========================================================================= */
  .bg-topbar {
    padding: 0 2px 6px;
    margin-bottom: 2px;
  }

  .bg-brand-icon {
    width: 34px;
    height: 34px;
    border-radius: 10px;
  }

  .bg-page-title {
    font-size: 1.08rem !important;
  }

  .bg-bento-deck {
    gap: 7px !important;
    margin-bottom: 8px !important;
  }

  /* 1A: Hide desktop solid filter header & collapse filters into 1-row Search + [Lọc] + [↻] */
  .bg-filter-head {
    display: none !important;
  }

  .bg-filter-strip {
    padding: 7px 8px !important;
    border-radius: 14px !important;
  }

  .bg-filter-row-top {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 0 !important;
  }

  .bg-search-shell,
  .bg-search-shell.is-focused {
    flex: 1 1 0 !important;
    width: auto !important;
    max-width: none !important;
    min-width: 0;
    height: 38px !important;
    padding: 0 10px !important;
    border-radius: 10.5px !important;
    gap: 7px;
  }

  .bg-search-input {
    font-size: 0.8rem !important;
  }

  .bg-m-filter-toggle {
    width: auto !important;
    margin: 0 !important;
    height: 38px !important;
    padding: 0 10px !important;
    border-radius: 10.5px;
    background: var(--bg-soft-pad);
    border: 1px solid var(--bg-border-strong);
    color: var(--bg-text);
    font-size: 0.76rem;
    font-weight: 800;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    flex-shrink: 0;
    white-space: nowrap;
    cursor: pointer;
    transition: all 0.16s var(--bg-ease);
  }

  .bg-m-filter-toggle.is-open,
  .bg-m-filter-toggle.has-active {
    background: var(--theme-pri-grad) !important;
    border-color: transparent !important;
    color: #ffffff !important;
    box-shadow: 0 4px 12px -3px var(--theme-pri-shadow);
  }

  .bg-m-filter-badge {
    min-width: 17px;
    height: 17px;
    padding: 0 4.5px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.24);
    color: #ffffff;
    font-size: 0.67rem;
    font-weight: 900;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .bg-m-filter-caret {
    font-size: 0.68rem;
    opacity: 0.88;
  }

  .bg-m-refresh-btn {
    width: 38px !important;
    height: 38px !important;
    margin: 0 !important;
    padding: 0 !important;
    border-radius: 10.5px;
    background: var(--bg-soft-pad);
    border: 1px solid var(--bg-border-strong);
    color: var(--bg-text-sec);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    cursor: pointer;
    transition: all 0.16s var(--bg-ease);
  }

  .bg-m-refresh-btn:active {
    transform: scale(0.94);
  }

  .bg-filter-collapsible {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 8px;
    padding-top: 8px;
    border-top: 1px solid var(--bg-border);
  }

  .bg-filter-collapsible.is-m-collapsed {
    display: none !important;
  }

  .bg-filter-row-main {
    padding: 0 !important;
    gap: 6px;
  }

  .bg-filter-row-main .bg-seg-switch.is-compact {
    flex: 1 1 auto;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .bg-filter-row-main .bg-seg-switch.is-compact .bg-seg-btn {
    justify-content: center;
    padding: 0 4px;
  }

  .bg-filter-row-pickers {
    display: grid !important;
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 6px !important;
    margin-top: 0 !important;
    padding: 7px 0 0 !important;
    background: transparent !important;
    border-top: 1px dashed var(--bg-border) !important;
    border-radius: 0 !important;
  }

  .bg-filter-row-pickers .pl-picker-wrap:nth-child(5) {
    grid-column: 1 / -1;
  }

  .bg-m-filter-reset-bar {
    display: flex;
    width: 100%;
  }

  .bg-m-reset-inline-btn {
    width: 100% !important;
    margin: 0 !important;
    height: 33px !important;
    padding: 0 10px !important;
    border-radius: 9.5px;
    background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%) !important;
    border: 1px solid rgba(254, 243, 199, 0.55) !important;
    color: #ffffff !important;
    font-size: 0.74rem;
    font-weight: 800;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    cursor: pointer;
  }

  /* Asymmetric Bento KPI Deck on Mobile (Col 1: Tall Hero Total | Col 2: 3 Stacked Status Cards) */
  .bg-kpi-grid {
    grid-template-columns: minmax(124px, 0.88fr) minmax(0, 1.18fr);
    gap: 8px;
    padding: 9px;
    border-radius: 15px;
  }

  .bg-kpi-card.is-total-hero {
    min-height: 112px;
    padding: 10px 11px;
    border-radius: 12px;
  }

  .bg-kpi-hero-top {
    gap: 6px;
  }

  .bg-kpi-hero-icon {
    width: 23px;
    height: 23px;
    border-radius: 7px;
  }

  .bg-kpi-hero-icon svg {
    width: 13px;
    height: 13px;
  }

  .bg-kpi-hero-lbl {
    font-size: 0.64rem;
    letter-spacing: 0.03em;
  }

  .bg-kpi-hero-mid {
    margin: 4px 0 3px;
    gap: 4px;
  }

  .bg-kpi-hero-num {
    font-size: 1.66rem;
  }

  .bg-kpi-hero-unit {
    font-size: 0.72rem;
  }

  .bg-kpi-hero-foot {
    gap: 4.5px;
  }

  .bg-kpi-hero-rate {
    font-size: 0.67rem;
  }

  .bg-kpi-seg-bar {
    height: 5px;
  }

  .bg-kpi-stack {
    gap: 5.5px;
  }

  .bg-kpi-card.is-stack-row {
    min-height: 33.5px;
    padding: 0 9.5px;
    border-radius: 10px;
    gap: 6px;
  }

  .bg-kpi-row-left {
    gap: 6px;
  }

  .bg-kpi-dot {
    width: 6.5px;
    height: 6.5px;
  }

  .bg-kpi-label {
    font-size: 0.74rem;
  }

  .bg-kpi-row-right {
    gap: 6px;
  }

  .bg-kpi-pct {
    font-size: 0.66rem;
  }

  .bg-kpi-val {
    font-size: 0.88rem;
    min-width: 18px;
  }

  /* 3-Tab View Switcher + Inline Theme Button + "?" Guide Button on Mobile ([Chi tiết | Lịch tuần | Lịch tháng] [☀/🌙] [?]) */
  .bg-board-toolbar {
    margin-bottom: 9px !important;
  }

  .bg-board-view-cluster {
    width: 100%;
    margin-left: 0 !important;
    display: flex;
    align-items: center;
    gap: 5.5px;
  }

  .bg-board-view-cluster .bg-seg-switch.is-view-track {
    flex: 1 1 0;
    width: auto;
    min-width: 0;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    padding: 3.5px;
    gap: 2px;
    border-radius: 12px;
    box-sizing: border-box;
  }

  .bg-board-view-cluster .bg-seg-switch.is-view-track .bg-seg-btn {
    width: 100% !important;
    height: 33px;
    padding: 0 3.5px;
    justify-content: center;
    font-size: 0.725rem;
    gap: 3.5px;
  }

  .bg-board-view-cluster .bg-seg-switch.is-view-track .bg-seg-btn svg {
    width: 12.5px;
    height: 12.5px;
    flex-shrink: 0;
  }

  .bg-board-view-cluster .bg-btn-theme,
  .bg-board-view-cluster .bg-btn-guide {
    width: 42px !important;
    height: 42px !important;
    padding: 0 !important;
    border-radius: 12px;
    flex-shrink: 0;
    justify-content: center;
    box-sizing: border-box;
  }

  .bg-board-view-cluster .bg-btn-guide .bg-guide-btn-ic {
    width: 17px;
    height: 17px;
  }

  .bg-board-view-cluster .bg-btn-theme .bg-theme-btn-lbl,
  .bg-board-view-cluster .bg-btn-guide .bg-guide-btn-lbl {
    display: none !important;
  }

  /* Mobile Empty Days Modal: Clean 2-Row Filter Subbar (Row 1: Từ ngày → Đến ngày | Row 2: 50/50 Danh sách | Lịch tháng) */
  .bg-modal-subbar.is-empty-days-subbar {
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
    padding: 10px 12px;
  }

  .bg-empty-date-row {
    flex: 0 0 auto;
    max-width: none;
    width: 100%;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    gap: 6px;
  }

  .is-empty-date-field {
    gap: 3.5px;
    min-width: 0;
  }

  .is-empty-date-field .bg-label {
    font-size: 0.7rem;
    font-weight: 800;
    color: var(--bg-text-muted);
    letter-spacing: 0.01em;
  }

  .bg-input.is-empty-date-input {
    width: 100% !important;
    min-width: 0 !important;
    height: 36px !important;
    padding: 0 8px !important;
    margin: 0 !important;
    font-size: 0.78rem !important;
    border-radius: 10px !important;
  }

  .bg-empty-date-arrow {
    height: 36px;
    font-size: 0.82rem;
    padding: 0 1px;
  }

  .bg-seg-switch.is-empty-view-track {
    width: 100%;
    height: auto;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 3px;
    border-radius: 10.5px;
    box-sizing: border-box;
  }

  .bg-seg-switch.is-empty-view-track .bg-seg-btn {
    width: 100% !important;
    height: 31px;
    padding: 0 8px;
    justify-content: center;
    font-size: 0.76rem;
    gap: 6px;
  }

  /* Mobile 1-Column Unified Detail Stream (Zero Outer Wrapper Boxes, Color-Differentiated Cards) */
  .bg-m-detail-stream {
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    gap: 11px;
    width: 100%;
    min-width: 0;
  }

  .bg-m-detail-empty {
    flex: 1 1 auto;
    min-height: max(175px, calc(100vh - 452px));
    min-height: max(175px, calc(100dvh - 452px));
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 26px 16px;
    border-radius: 15px;
    background: var(--bg-panel);
    border: 1px dashed var(--bg-border-strong);
    text-align: center;
    box-sizing: border-box;
  }

  .report-container.page:has(.bg-m-filter-toggle.is-open) .bg-m-detail-empty {
    min-height: 175px;
  }

  .bg-m-detail-empty > .bg-dsub-empty-add {
    flex: 0 0 auto;
    width: 100%;
    max-width: 240px;
    min-height: 88px;
    padding: 14px 18px;
    justify-content: center;
  }

  .bg-m-detail-empty-txt {
    font-size: 0.82rem;
    font-weight: 700;
    color: var(--bg-text-muted);
  }

  .bg-dcard-period-chip {
    display: inline-flex;
    align-items: center;
    padding: 1.5px 6.5px;
    border-radius: 6px;
    font-size: 0.63rem;
    font-weight: 900;
    letter-spacing: 0.04em;
    line-height: 1.3;
    border: 1px solid transparent;
  }

  .bg-dcard-period-chip.is-am {
    background: var(--sem-sky-bg);
    border-color: var(--sem-sky-bd);
    color: var(--sem-sky-bright);
  }

  .bg-dcard-period-chip.is-pm {
    background: var(--sem-amber-bg);
    border-color: var(--sem-amber-bd);
    color: var(--sem-amber-bright);
  }

  .bg-detail-card.is-done .bg-dcard-period-chip {
    background: rgba(255, 255, 255, 0.2) !important;
    border-color: rgba(255, 255, 255, 0.38) !important;
    color: #ffffff !important;
  }

  /* Touch-friendly Detail Cards on Mobile: Always reveal Xoá on Completed cards */
  .bg-detail-card.is-done .bg-dcard-actions {
    max-height: 46px;
    opacity: 1;
    padding-top: 9px;
    margin-top: auto;
    border-top: 1px solid rgba(255, 255, 255, 0.24);
    pointer-events: auto;
  }

  /* Mobile Calendar Top Toolbar Compaction */
  .bg-gcal-toolbar {
    padding: 8px 10px !important;
    gap: 7px !important;
  }

  .bg-gcal-nav-left {
    width: 100%;
    gap: 6px !important;
    justify-content: flex-start;
  }

  .bg-gcal-nav-left > .bg-btn-chip {
    height: 32px !important;
    padding: 0 10px !important;
    font-size: 0.75rem !important;
  }

  .bg-gcal-period-heading {
    gap: 6px;
    margin-left: auto;
    justify-content: flex-end;
  }

  .bg-gcal-title {
    font-size: 0.88rem !important;
  }

  .bg-gcal-badge {
    font-size: 0.66rem !important;
    padding: 2px 7px !important;
  }

  .bg-gcal-nav-right,
  .bg-gcal-legend,
  .is-gcal-fs-btn {
    display: none !important;
  }

  .bg-date-stepper-group {
    flex: 1 1 100%;
    width: 100%;
    display: flex;
    align-items: center;
    gap: 4px;
  }

  .bg-period-step-btn {
    width: 30px !important;
    height: 34px !important;
  }

  .bg-date-range-capsule {
    flex: 1 1 0;
    min-width: 0;
    height: 34px;
    box-sizing: border-box;
    justify-content: space-between;
    padding: 0 7px;
    gap: 4px;
    overflow: hidden;
  }

  .bg-date-field {
    gap: 3px;
    min-width: 0;
    flex: 1 1 0;
  }

  .bg-date-input:not(.is-year) {
    font-size: 0.74rem !important;
    min-width: 0;
    width: 100%;
    max-width: 112px;
  }

  .bg-grid-2 {
    grid-template-columns: 1fr;
  }

  .bg-foot-right.is-add-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    width: 100%;
  }
  .bg-foot-right.is-add-grid .bg-btn-emerald {
    grid-column: 1 / -1;
  }

  /* MB-A Compact Top Capsule for Smart Toast */
  .smart-toast-wrap {
    top: calc(10px + env(safe-area-inset-top, 0px));
    border-radius: 999px;
    padding: 8px 14px;
    max-width: calc(100vw - 20px);
  }

  .smart-toast-close {
    display: none !important;
  }
}


/* =========================================================================
   V7.5 3-COLUMN STUDIO ADD / EDIT REPORT MODAL (~23% | ~50% | ~27%)
   ========================================================================= */

/* Full-Bleed Solid Semantic Studio Header (Dark = Emerald | Light = Ocean Blue) */
.bg-modal-head.is-solid-studio {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%) !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.16) !important;
  color: #ffffff !important;
  padding: 12px 20px !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    0 6px 18px -8px rgba(5, 150, 105, 0.45);
}

.report-container.page.theme-light-blue .bg-modal-head.is-solid-studio {
  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.32),
    0 6px 18px -8px rgba(2, 132, 199, 0.42);
}

.bg-modal-head.is-solid-studio .bg-modal-title {
  color: #ffffff !important;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.18);
}

.bg-modal-head.is-solid-studio .bg-modal-sub {
  color: rgba(255, 255, 255, 0.88) !important;
}

.bg-modal-icon.is-studio-glass {
  background: rgba(255, 255, 255, 0.2) !important;
  border: 1px solid rgba(255, 255, 255, 0.34) !important;
  color: #ffffff !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35);
}

.bg-studio-head-status {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 9px;
  border-radius: 999px;
  font-size: 0.71rem;
  font-weight: 800;
  letter-spacing: 0.03em;
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.38);
}
.bg-studio-head-status.is-pending {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
}
.bg-studio-head-status.is-done {
  background: rgba(255, 255, 255, 0.24);
}
.bg-studio-head-status.is-failed {
  background: linear-gradient(135deg, #f43f5e 0%, #e11d48 100%);
}

.bg-studio-head-right {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.bg-studio-kbd-pill {
  font-size: 0.71rem;
  font-weight: 700;
  color: #ffffff;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.28);
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
}

.bg-modal-close.is-studio-close {
  background: rgba(255, 255, 255, 0.18) !important;
  border: 1px solid rgba(255, 255, 255, 0.32) !important;
  color: #ffffff !important;
  font-weight: 800;
}
.bg-modal-close.is-studio-close:hover {
  background: #f43f5e !important;
  border-color: #fda4af !important;
  color: #ffffff !important;
}

/* 3-Column Studio Grid (Left Rail ~23% : Center Composer ~50% : Right Upload Vault ~27%) */
.bg-studio-modal-body {
  display: flex;
  flex-direction: column;
  padding: 14px 18px !important;
}

.bg-studio-3col-grid {
  display: grid;
  grid-template-columns: minmax(264px, 0.92fr) minmax(420px, 2.04fr) minmax(292px, 1.08fr);
  gap: 14px;
  flex: 1;
  min-height: 100%;
  align-items: stretch;
}

.bg-studio-left-rail {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.modal-banner-left {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.bg-studio-mob-rail-toggle {
  display: none;
}

.bg-studio-rail-body {
  gap: 12px;
  flex: 1;
}

.bg-choice-grid.is-cols-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.bg-choice-btn.is-active-slate-solid {
  background: linear-gradient(135deg, #475569 0%, #334155 100%);
  color: #ffffff !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.25),
    0 3px 9px -2px rgba(15, 23, 42, 0.38);
}

/* 1-Tap Quick Day Presets (Hôm qua | Hôm nay | Ngày mai) */
.bg-studio-day-chips {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px;
  margin-bottom: 2px;
}

.bg-studio-day-chip {
  width: 100% !important;
  margin: 0 !important;
  height: 29px;
  padding: 0 6px;
  border-radius: 8px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-soft-pad-bd);
  color: var(--bg-text-sec);
  font-size: 0.73rem;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.16s var(--bg-ease);
}
.bg-studio-day-chip:hover {
  border-color: var(--theme-pri-bd);
  color: var(--bg-text);
}
.bg-studio-day-chip.is-active {
  background: var(--theme-pri-grad);
  border-color: transparent;
  color: #ffffff !important;
  font-weight: 800;
  box-shadow: 0 3px 10px -3px var(--theme-pri-shadow);
}

/* Center Studio Composer (~50%) & Smart Drag-and-Drop Overlay */
.bg-report-studio-card {
  position: relative;
}

.bg-report-studio-card.is-drag-over {
  border-color: var(--theme-pri-bright) !important;
  box-shadow:
    0 0 0 3px var(--theme-pri-ring),
    0 12px 30px -10px var(--theme-pri-shadow) !important;
}

.bg-studio-composer {
  position: relative;
  min-width: 0;
  display: flex;
  flex-direction: column;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.bg-studio-drop-overlay {
  position: absolute;
  inset: 0;
  z-index: 45;
  border-radius: 16px;
  background: rgba(6, 20, 32, 0.84);
  backdrop-filter: blur(5px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  pointer-events: none;
}

.report-container.page.theme-light-blue .bg-studio-drop-overlay {
  background: rgba(240, 249, 255, 0.92);
}

.bg-studio-drop-box {
  border: 2px dashed var(--theme-pri-bright);
  border-radius: 16px;
  padding: 26px 34px;
  text-align: center;
  color: var(--theme-pri-bright);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  background: var(--theme-pri-bg);
}

.bg-studio-drop-title {
  font-size: 1rem;
  font-weight: 800;
  color: var(--bg-text);
}

.bg-studio-drop-sub {
  font-size: 0.79rem;
  font-weight: 600;
  color: var(--bg-text-sec);
}

.bg-studio-composer-body {
  display: flex;
  flex-direction: column;
  gap: 11px;
  flex: 1;
  min-height: 0;
}

/* Auto-Draft Recovery Strip */
.bg-studio-draft-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  padding: 8px 12px;
  border-radius: 11px;
  background: var(--sem-amber-bg);
  border: 1px solid var(--sem-amber-bd);
}

.bg-studio-draft-text {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 0.79rem;
  font-weight: 700;
  color: var(--sem-amber-bright);
}

.bg-studio-draft-acts {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* 1. Customer Input Shell with Embedded "Chọn khách hàng" Button (Zero Recent Chips) */
.bg-studio-customer-bar {
  position: relative;
  z-index: 25;
}

.bg-studio-cus-combobox {
  position: relative;
  width: 100%;
  box-sizing: border-box;
  min-height: 44px;
  padding: 4px 5px 4px 12px;
  border-radius: 12px;
  background: var(--bg-well);
  border: 1px solid var(--bg-well-border);
  box-shadow: var(--bg-well-shadow);
  display: flex;
  align-items: center;
  gap: 8px;
  transition: border-color 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
}

.bg-studio-cus-combobox:focus-within {
  border-color: var(--theme-pri-bright);
  box-shadow:
    var(--bg-well-shadow),
    0 0 0 3px var(--theme-pri-ring);
}

.bg-studio-cus-combobox.is-selected-shell {
  padding: 5px 5px 5px 8px;
  background: var(--bg-soft-pad);
  border-color: var(--theme-pri-bd);
  justify-content: space-between;
}

.bg-studio-cus-info {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: nowrap;
  overflow: hidden;
  min-width: 0;
  flex: 1 1 0;
}

.bg-studio-cus-info.is-clickable-info {
  cursor: pointer;
  border-radius: 8px;
  padding: 2px 4px;
  transition: background 0.14s ease;
}
.bg-studio-cus-info.is-clickable-info:hover {
  background: var(--bg-hover);
}

.bg-studio-cus-icon {
  width: 26px;
  height: 26px;
  border-radius: 8px;
  background: var(--theme-pri-grad);
  color: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.bg-studio-cus-name {
  flex: 0 1 auto;
  min-width: 0;
  font-size: 0.85rem;
  font-weight: 800;
  color: var(--bg-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bg-studio-cus-info .bg-tag-pill {
  flex-shrink: 0;
}

.bg-studio-cus-in-actions {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
}

.bg-studio-cus-inbtn {
  width: auto !important;
  margin: 0 !important;
  height: 33px !important;
  padding: 0 12px !important;
  border-radius: 9px;
  background: var(--theme-pri-grad);
  border: 1px solid rgba(255, 255, 255, 0.24);
  color: #ffffff !important;
  font-size: 0.76rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  white-space: nowrap;
  flex-shrink: 0;
  cursor: pointer;
  box-shadow: 0 3px 9px -2px var(--theme-pri-shadow);
  transition: filter 0.15s ease, transform 0.12s ease;
}
.bg-studio-cus-inbtn:hover {
  filter: brightness(1.07);
}
.bg-studio-cus-inbtn:active {
  transform: scale(0.97);
}

.bg-studio-cus-remove-inbtn {
  width: 31px !important;
  height: 33px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 9px;
  background: var(--sem-rose-bg);
  border: 1px solid var(--sem-rose-bd);
  color: var(--sem-rose-bright);
  font-size: 0.78rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  cursor: pointer;
  transition: all 0.14s ease;
}
.bg-studio-cus-remove-inbtn:hover {
  background: #e11d48;
  border-color: #e11d48;
  color: #ffffff;
}

.bg-studio-cus-search-ic {
  color: var(--theme-pri-bright);
  flex-shrink: 0;
}

.bg-studio-cus-input {
  flex: 1;
  min-width: 0;
  height: 34px !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--bg-text) !important;
  font-size: 0.84rem;
  font-weight: 600;
  outline: none !important;
}

.bg-studio-cus-input::placeholder {
  color: var(--bg-text-muted);
  font-weight: 500;
}

.bg-studio-cus-clear {
  width: 24px !important;
  height: 24px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 6px;
  border: none;
  background: var(--bg-soft-pad);
  color: var(--bg-text-muted);
  font-size: 0.72rem;
  cursor: pointer;
  flex-shrink: 0;
}
.bg-studio-cus-clear:hover {
  background: var(--sem-rose-bg);
  color: var(--sem-rose-bright);
}

/* Inline Customer Autocomplete Dropdown */
.bg-studio-cus-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  z-index: 1850;
  background: var(--bg-panel-elev);
  border: 1px solid var(--bg-border-strong);
  border-radius: 13px;
  box-shadow:
    inset 0 1px 0 var(--bg-specular-strong),
    var(--bg-shadow-pop);
  overflow: hidden;
  animation: bgPopDrop 0.14s var(--bg-ease);
}

.bg-studio-dd-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 7px 12px;
  font-size: 0.69rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--bg-text-muted);
  background: var(--bg-soft-pad);
  border-bottom: 1px solid var(--bg-border);
}

.bg-studio-dd-list {
  max-height: 242px;
  overflow-y: auto;
  padding: 5px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.bg-studio-dd-item {
  width: 100% !important;
  margin: 0 !important;
  padding: 7px 10px !important;
  border-radius: 9px;
  border: none;
  background: transparent;
  color: var(--bg-text);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  text-align: left;
  cursor: pointer;
  transition: background 0.12s ease;
}

.bg-studio-dd-item.is-highlighted,
.bg-studio-dd-item:hover {
  background: var(--theme-pri-bg);
}

.bg-studio-dd-main {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  flex: 1;
  overflow: hidden;
}

.bg-studio-dd-title {
  font-size: 0.82rem;
  font-weight: 800;
  color: var(--bg-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bg-studio-dd-company {
  font-size: 0.76rem;
  font-weight: 600;
  color: var(--bg-text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bg-studio-dd-tags {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.bg-studio-dd-empty {
  padding: 14px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 0.8rem;
  color: var(--bg-text-muted);
}

.bg-studio-dd-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 7px 11px;
  background: var(--bg-soft-pad);
  border-top: 1px solid var(--bg-border);
}

.bg-mini-link.is-emerald {
  color: var(--theme-pri-bright);
  background: transparent;
  border: none;
  cursor: pointer;
}
.bg-mini-link.is-emerald:hover {
  background: var(--theme-pri-bg);
}
.bg-mini-link.is-sky {
  color: var(--sem-sky-bright);
  background: transparent;
  border: none;
  cursor: pointer;
}
.bg-mini-link.is-sky:hover {
  background: var(--sem-sky-bg);
}
.bg-mini-link.is-slate {
  color: var(--bg-text-muted);
  background: transparent;
  border: none;
  cursor: pointer;
}
.bg-mini-link.is-slate:hover {
  color: var(--bg-text);
  background: var(--bg-hover);
}

/* 2. Fixed Full-Height Center Work Content Composer */
.bg-studio-main-field {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-height: 195px;
}

.bg-studio-main-label {
  font-size: 0.81rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--bg-text);
}

.bg-textarea.is-studio-textarea {
  flex: 1 1 auto;
  min-height: 185px;
  font-size: 0.93rem;
  line-height: 1.6;
  padding: 13px 15px;
  border-radius: 13px;
}

/* 3. Three Popup Modal Trigger Buttons (B1: 44px + 26x26 Semantic Tinted Icon Boxes) */
.bg-studio-modal-triggers {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.bg-studio-mtrigger {
  width: 100% !important;
  margin: 0 !important;
  height: 44px;
  padding: 0 13px;
  border-radius: 12px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-border-strong);
  color: var(--bg-text);
  font-size: 0.86rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8.5px;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.16s var(--bg-ease);
}

.bg-studio-mtrig-ic {
  width: 26px;
  height: 26px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background 0.16s ease, color 0.16s ease, border-color 0.16s ease;
}

.bg-studio-mtrigger.is-note-trigger {
  border-color: rgba(244, 63, 94, 0.28);
}
.bg-studio-mtrigger.is-note-trigger .bg-studio-mtrig-ic {
  background: var(--sem-rose-bg);
  border: 1px solid var(--sem-rose-bd);
  color: var(--sem-rose-bright);
}
.bg-studio-mtrigger.is-note-trigger:hover {
  border-color: #f43f5e;
  background: var(--sem-rose-bg);
  color: var(--sem-rose-bright);
  transform: translateY(-1px);
}
.bg-studio-mtrigger.is-note-trigger.has-data {
  background: linear-gradient(135deg, #f43f5e 0%, #e11d48 100%);
  border-color: transparent;
  color: #ffffff !important;
  box-shadow: 0 4px 13px -3px rgba(225, 29, 72, 0.48);
}
.bg-studio-mtrigger.is-note-trigger.has-data .bg-studio-mtrig-ic {
  background: rgba(255, 255, 255, 0.22);
  border-color: rgba(255, 255, 255, 0.34);
  color: #ffffff;
}

.bg-studio-mtrigger.is-rem-trigger {
  border-color: rgba(245, 158, 11, 0.3);
}
.bg-studio-mtrigger.is-rem-trigger .bg-studio-mtrig-ic {
  background: var(--sem-amber-bg);
  border: 1px solid var(--sem-amber-bd);
  color: var(--sem-amber-bright);
}
.bg-studio-mtrigger.is-rem-trigger:hover {
  border-color: #f59e0b;
  background: var(--sem-amber-bg);
  color: var(--sem-amber-bright);
  transform: translateY(-1px);
}
.bg-studio-mtrigger.is-rem-trigger.has-data {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  border-color: transparent;
  color: #ffffff !important;
  box-shadow: 0 4px 13px -3px rgba(217, 119, 6, 0.48);
}
.bg-studio-mtrigger.is-rem-trigger.has-data .bg-studio-mtrig-ic {
  background: rgba(255, 255, 255, 0.22);
  border-color: rgba(255, 255, 255, 0.34);
  color: #ffffff;
}

.bg-studio-mtrigger.is-file-trigger {
  border-color: var(--theme-pri-bd);
}
.bg-studio-mtrigger.is-file-trigger .bg-studio-mtrig-ic {
  background: var(--theme-pri-bg);
  border: 1px solid var(--theme-pri-bd);
  color: var(--theme-pri-bright);
}
.bg-studio-mtrigger.is-file-trigger:hover {
  border-color: var(--theme-pri-bright);
  background: var(--theme-pri-bg);
  color: var(--theme-pri-bright);
  transform: translateY(-1px);
}
.bg-studio-mtrigger.is-file-trigger.has-data {
  background: var(--theme-pri-grad);
  border-color: transparent;
  color: #ffffff !important;
  box-shadow: 0 4px 13px -3px var(--theme-pri-shadow);
}
.bg-studio-mtrigger.is-file-trigger.has-data .bg-studio-mtrig-ic {
  background: rgba(255, 255, 255, 0.22);
  border-color: rgba(255, 255, 255, 0.34);
  color: #ffffff;
}

/* 4. Compact Full-Detail Vertical Summary Stack (Option 2: hiện đủ theo hàng dọc và gọn) */
@keyframes studioMetaRowFadeIn {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.bg-studio-meta-stack {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.bg-studio-meta-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 7.5px 10px;
  border-radius: 10px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-soft-pad-bd);
  cursor: pointer;
  min-width: 0;
  animation: studioMetaRowFadeIn 0.15s var(--bg-ease);
  transition: border-color 0.14s ease, background 0.14s ease;
}

.bg-studio-meta-row.is-note {
  border-left: 3.5px solid #f43f5e;
  background: linear-gradient(145deg, rgba(244, 63, 94, 0.08) 0%, rgba(244, 63, 94, 0.02) 100%);
  border-color: rgba(244, 63, 94, 0.25);
}
.bg-studio-meta-row.is-note:hover {
  border-color: rgba(244, 63, 94, 0.45);
}

.bg-studio-meta-row.is-reminder {
  border-left: 3.5px solid #f59e0b;
  background: linear-gradient(145deg, rgba(245, 158, 11, 0.09) 0%, rgba(217, 119, 6, 0.02) 100%);
  border-color: rgba(245, 158, 11, 0.28);
}
.bg-studio-meta-row.is-reminder:hover {
  border-color: rgba(245, 158, 11, 0.48);
}

.bg-studio-meta-row.is-file {
  border-left: 3.5px solid var(--theme-pri-bright);
  border-color: var(--theme-pri-bd);
}
.bg-studio-meta-row.is-file:hover {
  background: var(--theme-pri-bg);
}

.bg-studio-meta-tag {
  padding: 2px 6px;
  border-radius: 5px;
  font-size: 0.62rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  line-height: 1.25;
  flex-shrink: 0;
  margin-top: 1px;
  white-space: nowrap;
}
.bg-studio-meta-tag.is-rose {
  background: rgba(244, 63, 94, 0.2);
  color: var(--sem-rose-bright);
}
.bg-studio-meta-tag.is-amber {
  background: rgba(245, 158, 11, 0.2);
  color: var(--sem-amber-bright);
}
.bg-studio-meta-tag.is-teal {
  background: var(--theme-pri-bg);
  color: var(--theme-pri-bright);
  border: 1px solid var(--theme-pri-bd);
}

.bg-studio-meta-text {
  flex: 1 1 0;
  min-width: 0;
  font-size: 0.8rem;
  font-weight: 600;
  line-height: 1.44;
  color: var(--bg-text);
  white-space: pre-line;
  word-break: break-word;
}
.bg-studio-meta-text.is-rose-txt {
  color: var(--sem-rose-bright);
}

.bg-studio-meta-date {
  color: var(--sem-amber-bright);
  font-weight: 800;
}

.bg-studio-meta-subnote {
  color: var(--bg-text-muted);
  font-size: 0.76rem;
}

.bg-studio-meta-acts {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.bg-studio-meta-open,
.bg-studio-meta-clear {
  width: 23px !important;
  height: 23px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 6px;
  font-size: 0.74rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  cursor: pointer;
  transition: all 0.14s ease;
}

.bg-studio-meta-open {
  background: var(--sem-sky-bg);
  border: 1px solid var(--sem-sky-bd);
  color: var(--sem-sky-bright);
}
.bg-studio-meta-open:hover {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

.bg-studio-meta-clear {
  background: var(--bg-well);
  border: 1px solid var(--bg-well-border);
  color: var(--bg-text-muted);
}
.bg-studio-meta-clear:hover {
  background: #e11d48;
  border-color: #e11d48;
  color: #ffffff;
}

/* =========================================================================
   COLUMN 3 (~27%): TỆP ĐÍNH KÈM (OPTION 1.1 UPLOAD STACK WITH CLEAR ⬆ ICONS)
   ========================================================================= */
.bg-studio-right-files {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.bg-studio-head-cnt {
  margin-left: auto;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.34);
  color: #ffffff;
  font-size: 0.69rem;
  font-weight: 800;
  line-height: 1.2;
}

.bg-studio-files-body {
  display: flex;
  flex-direction: column;
  gap: 11px;
  flex: 1;
  min-height: 0;
}

.bg-studio-upload-11 {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.bg-studio-upload-row2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.bg-studio-upbtn {
  width: 100% !important;
  margin: 0 !important;
  height: 40px;
  padding: 0 11px;
  border-radius: 10.5px;
  font-size: 0.78rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.16s var(--bg-ease);
}

.bg-studio-up-ic {
  width: 23px;
  height: 23px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background 0.16s ease, color 0.16s ease;
}

.bg-studio-upbtn.is-upload-img {
  background: var(--sem-sky-bg);
  border: 1px solid var(--sem-sky-bd);
  color: var(--sem-sky-bright);
}
.bg-studio-upbtn.is-upload-img .bg-studio-up-ic {
  background: rgba(14, 165, 233, 0.18);
}
.bg-studio-upbtn.is-upload-img:hover,
.bg-studio-upbtn.is-upload-img.has-items {
  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%);
  border-color: transparent;
  color: #ffffff;
  box-shadow: 0 4px 12px -3px rgba(2, 132, 199, 0.42);
}
.bg-studio-upbtn.is-upload-img:hover .bg-studio-up-ic,
.bg-studio-upbtn.is-upload-img.has-items .bg-studio-up-ic {
  background: rgba(255, 255, 255, 0.22);
  color: #ffffff;
}

.bg-studio-upbtn.is-upload-bg {
  background: var(--sem-emerald-bg);
  border: 1px solid var(--sem-emerald-bd);
  color: var(--sem-emerald-bright);
}
.bg-studio-upbtn.is-upload-bg .bg-studio-up-ic {
  background: rgba(16, 185, 129, 0.18);
}
.bg-studio-upbtn.is-upload-bg:hover,
.bg-studio-upbtn.is-upload-bg.has-items {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  border-color: transparent;
  color: #ffffff;
  box-shadow: 0 4px 12px -3px rgba(5, 150, 105, 0.44);
}
.bg-studio-upbtn.is-upload-bg:hover .bg-studio-up-ic,
.bg-studio-upbtn.is-upload-bg.has-items .bg-studio-up-ic {
  background: rgba(255, 255, 255, 0.22);
  color: #ffffff;
}

.bg-studio-upbtn.is-upload-mh {
  background: var(--sem-amber-bg);
  border: 1px solid var(--sem-amber-bd);
  color: var(--sem-amber-bright);
}
.bg-studio-upbtn.is-upload-mh .bg-studio-up-ic {
  background: rgba(245, 158, 11, 0.18);
}
.bg-studio-upbtn.is-upload-mh:hover,
.bg-studio-upbtn.is-upload-mh.has-items {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  border-color: transparent;
  color: #ffffff;
  box-shadow: 0 4px 12px -3px rgba(217, 119, 6, 0.44);
}
.bg-studio-upbtn.is-upload-mh:hover .bg-studio-up-ic,
.bg-studio-upbtn.is-upload-mh.has-items .bg-studio-up-ic {
  background: rgba(255, 255, 255, 0.22);
  color: #ffffff;
}

.bg-studio-tool-badge {
  min-width: 19px;
  height: 19px;
  padding: 0 5px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.26);
  color: #ffffff;
  font-size: 0.69rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* Dashed Dropzone Empty State & Populated Attachment Vault */
.bg-studio-files-empty {
  flex: 1 1 auto;
  min-height: 185px;
  border: 1.5px dashed var(--bg-border-strong);
  border-radius: 13px;
  background: var(--bg-soft-pad);
  padding: 18px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 8px;
  cursor: pointer;
  transition: all 0.16s ease;
}
.bg-studio-files-empty:hover {
  border-color: var(--theme-pri-bright);
  background: var(--theme-pri-bg);
}

.bg-studio-empty-upic {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--theme-pri-bg);
  border: 1px solid var(--theme-pri-bd);
  color: var(--theme-pri-bright);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.bg-studio-empty-title {
  font-size: 0.82rem;
  font-weight: 800;
  color: var(--bg-text);
}

.bg-studio-empty-sub {
  font-size: 0.74rem;
  font-weight: 500;
  line-height: 1.45;
  color: var(--bg-text-muted);
  max-width: 265px;
}

.bg-studio-files-vault {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding-right: 2px;
}

.bg-studio-vault-sec {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.bg-studio-vault-lbl {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--bg-text-muted);
  text-transform: uppercase;
}

.bg-thumb-grid.is-studio-thumbs {
  grid-template-columns: repeat(auto-fill, minmax(96px, 1fr));
}

.bg-studio-excel-stack {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.bg-studio-file-kind {
  font-size: 0.61rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  padding: 2px 5px;
  border-radius: 5px;
  flex-shrink: 0;
  color: #ffffff;
}
.bg-studio-file-kind.is-bg {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
}
.bg-studio-file-kind.is-mh {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
}

.bg-file-pill-act.is-swap {
  font-size: 0.78rem;
  font-weight: 800;
  color: var(--theme-pri-bright);
  background: var(--theme-pri-bg);
  border: 1px solid var(--theme-pri-bd);
}
.bg-file-pill-act.is-swap:hover {
  background: var(--theme-pri-grad);
  border-color: transparent;
  color: #ffffff;
}

/* Centered Sub-Modals (MODULE 3B Ghi Chú · MODULE 3C Nhắc Hẹn) & MODULE 4B Current Linked Bar */
.bg-modal-overlay.is-studio-submodal-overlay {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 16px !important;
}

.bg-modal-card.is-studio-submodal-card {
  width: min(520px, calc(100vw - 24px)) !important;
  max-width: 520px !important;
  height: auto !important;
  max-height: 88dvh !important;
  border-radius: 20px !important;
}

.bg-textarea.is-studio-note {
  min-height: 92px !important;
  padding: 10px 13px;
}

.bg-studio-rem-presets {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.bg-studio-rem-chip {
  width: auto !important;
  margin: 0 !important;
  height: 24px;
  padding: 0 8px;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 800;
  background: var(--bg-well);
  border: 1px solid var(--sem-amber-bd);
  color: var(--sem-amber-bright);
  cursor: pointer;
  transition: all 0.14s ease;
}
.bg-studio-rem-chip:hover,
.bg-studio-rem-chip.is-active {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  border-color: transparent;
  color: #ffffff !important;
}

/* MODULE 3D: SUB-MODAL HỎI LẤY TÊN FILE ĐƯA VÀO NỘI DUNG */
.bg-ufn-modal-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.bg-ufn-quick-tools {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.bg-ufn-tool-btn {
  width: auto !important;
  margin: 0 !important;
  height: 24px;
  padding: 0 9px;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 800;
  background: var(--bg-well);
  border: 1px solid var(--bg-border-strong);
  color: var(--bg-text-sub);
  cursor: pointer;
  transition: all 0.14s ease;
}

.bg-ufn-tool-btn:hover {
  background: var(--theme-pri-bg);
  border-color: var(--theme-pri-bd);
  color: var(--theme-pri-bright);
}

.bg-ufn-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  max-height: 210px;
  overflow-y: auto;
  padding-right: 2px;
}

.bg-ufn-item {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 11px;
  border-radius: 11px;
  background: var(--bg-well);
  border: 1.5px solid var(--bg-border);
  cursor: pointer;
  user-select: none;
  transition: all 0.15s ease;
}

.bg-ufn-item:hover {
  border-color: var(--bg-border-strong);
}

.bg-ufn-item.is-checked {
  background: var(--theme-pri-bg);
  border-color: var(--theme-pri-bd);
}

.bg-ufn-check {
  width: 18px;
  height: 18px;
  border-radius: 5px;
  border: 1.5px solid var(--bg-border-strong);
  background: var(--bg-surface);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: #ffffff;
  transition: all 0.14s ease;
}

.bg-ufn-check.is-checked {
  background: var(--theme-pri-grad);
  border-color: transparent;
}

.bg-ufn-kind-pill {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  padding: 2px 6px;
  border-radius: 5px;
  flex-shrink: 0;
  color: #ffffff;
}

.bg-ufn-kind-pill.is-emerald {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
}

.bg-ufn-kind-pill.is-amber {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
}

.bg-ufn-kind-pill.is-sky {
  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%);
}

.bg-ufn-name {
  font-size: 0.81rem;
  font-weight: 700;
  color: var(--bg-text);
  line-height: 1.35;
  word-break: break-all;
  flex: 1;
  min-width: 0;
}

.bg-ufn-preview-box {
  padding: 10px 12px;
  border-radius: 11px;
  background: var(--bg-well);
  border: 1px dashed var(--theme-pri-bd);
  font-size: 0.81rem;
  font-weight: 700;
  color: var(--bg-text);
  line-height: 1.45;
  word-break: break-word;
  max-height: 110px;
  overflow-y: auto;
}

.bg-ufn-preview-box.is-empty {
  border-color: var(--bg-border);
  font-weight: 500;
  color: var(--bg-text-muted);
}

.bg-linked-current-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 7px 11px;
  border-radius: 10px;
  background: var(--theme-pri-bg);
  border: 1px solid var(--theme-pri-bd);
}

.bg-linked-current-txt {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  font-size: 0.79rem;
  font-weight: 700;
  color: var(--bg-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bg-linked-file-card.is-selected-file {
  border-color: var(--theme-pri-bright) !important;
  box-shadow: 0 0 0 2px var(--theme-pri-ring);
}

/* Studio Footer & Clone Button (A1: 44px Secondary Bordered + 46px Prominent Primary CTA) */
.bg-modal-foot.bg-studio-foot {
  padding: 14px 22px;
  gap: 12px;
  background: var(--bg-panel-elev);
  border-top: 1px solid var(--bg-border-strong);
}

.bg-studio-foot-left {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.bg-modal-foot.bg-studio-foot .bg-foot-right {
  gap: 10px;
}

.bg-modal-foot.bg-studio-foot .bg-btn {
  height: 44px;
  padding: 0 20px;
  border-radius: 12px;
  font-size: 0.88rem;
  font-weight: 800;
  gap: 7.5px;
}

.bg-modal-foot.bg-studio-foot .bg-btn.is-studio-cta {
  height: 46px;
  min-width: 178px;
  padding: 0 26px;
  border-radius: 12.5px;
  font-size: 0.94rem;
  font-weight: 800;
  letter-spacing: 0.01em;
  box-shadow: 0 6px 18px -4px var(--theme-pri-shadow);
}

.bg-studio-clone-btn {
  display: inline-flex;
  align-items: center;
  gap: 7.5px;
}

/* Responsive V7.5 Studio Modal (<= 1100px & <= 768px) */
@media (max-width: 1100px) {
  /* Beat global unscoped #app .page .m-grab-head-stack { flex: 1 1 auto !important } from baogiaFirebase.vue */
  :global(#app .report-container.page .m-grab-head-stack) {
    display: flex !important;
    flex-direction: column !important;
    justify-content: flex-start !important;
    align-items: stretch !important;
    flex: 0 0 auto !important;
    height: auto !important;
    min-height: 0 !important;
    gap: 0 !important;
    padding: 10px 14px 10px !important;
    background: var(--bg-panel-elev);
    border-bottom: 1px solid var(--bg-border);
  }

  /* Fullscreen Mobile Modals: match baogiaFirebase notch/status-bar top safe-area (>= 52px) */
  :global(#app .report-container.page .bg-modal-card.is-mobile-sheet > .m-grab-head-stack),
  :global(#app .report-container.page .bg-modal-card.is-fullscreen-card > .m-grab-head-stack) {
    padding: var(--mobile-modal-head-top, max(calc(env(safe-area-inset-top, 0px) + 6px), 52px)) 14px 12px !important;
  }

  :global(#app .report-container.page .bg-modal-card.is-mobile-sheet > .m-grab-head-stack > .m-grab-pill),
  :global(#app .report-container.page .bg-modal-card.is-fullscreen-card > .m-grab-head-stack > .m-grab-pill) {
    display: none !important;
  }

  :global(#app .report-container.page .m-grab-title) {
    color: var(--bg-text) !important;
    -webkit-text-fill-color: var(--bg-text) !important;
  }

  :global(#app .report-container.page .m-grab-head-stack.is-solid-studio) {
    background: linear-gradient(135deg, #10b981 0%, #059669 100%) !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.18) !important;
    color: #ffffff !important;
  }

  :global(#app .report-container.page.theme-light-blue .m-grab-head-stack.is-solid-studio) {
    background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%) !important;
  }

  :global(#app .report-container.page .m-grab-head-stack.is-solid-studio .m-grab-pill) {
    background: rgba(255, 255, 255, 0.45) !important;
  }

  :global(#app .report-container.page .m-grab-head-stack.is-solid-studio .m-grab-title) {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  :global(#app .report-container.page .m-grab-head-stack.is-solid-studio .m-grab-sub) {
    color: rgba(255, 255, 255, 0.86) !important;
    -webkit-text-fill-color: rgba(255, 255, 255, 0.86) !important;
  }

  .bg-studio-3col-grid {
    grid-template-columns: 1fr;
    gap: 10px;
    min-height: auto;
  }

  .modal-banner-header.is-mob-collapsible {
    justify-content: space-between;
    cursor: pointer;
    user-select: none;
  }

  .bg-studio-mob-rail-toggle {
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    gap: 4px;
    width: auto !important;
    margin: 0 !important;
    height: 24px;
    padding: 0 9px !important;
    border-radius: 6px;
    background: rgba(15, 23, 42, 0.62) !important;
    border: 1px solid rgba(255, 255, 255, 0.45) !important;
    color: #ffffff !important;
    font-size: 0.7rem;
    font-weight: 800;
    text-transform: none;
    letter-spacing: 0;
    line-height: 1;
    cursor: pointer;
    flex-shrink: 0;
    text-shadow: none !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.18) !important;
    transition: all 0.16s ease;
  }

  :global(#app .report-container.page.theme-light-blue .modal-banner-header .bg-studio-mob-rail-toggle) {
    background: #ffffff !important;
    color: #0369a1 !important;
    -webkit-text-fill-color: #0369a1 !important;
    border: 1.5px solid #e0f2fe !important;
    box-shadow: 0 2px 6px rgba(3, 105, 161, 0.25) !important;
    text-shadow: none !important;
  }

  :global(#app .report-container.page.theme-light-blue .modal-banner-header .bg-studio-mob-rail-toggle span) {
    color: #0369a1 !important;
    -webkit-text-fill-color: #0369a1 !important;
    text-shadow: none !important;
  }

  :global(#app .report-container.page.theme-light-blue .modal-banner-header .bg-studio-mob-rail-toggle svg) {
    color: #0369a1 !important;
    stroke: #0369a1 !important;
  }

  .bg-studio-mob-rail-chevron {
    transition: transform 0.2s ease;
  }

  .bg-studio-mob-rail-toggle.is-open .bg-studio-mob-rail-chevron {
    transform: rotate(180deg);
  }

  .bg-studio-left-rail.is-mob-collapsed .bg-studio-rail-body {
    display: none !important;
  }

  .bg-studio-left-rail.is-mob-collapsed .modal-banner-header {
    border-radius: 15px !important;
  }
}

@media (max-width: 768px) {
  .bg-studio-modal-body {
    padding: 10px 10px !important;
  }

  .bg-studio-rail-body,
  .bg-studio-composer-body,
  .bg-studio-files-body {
    padding: 10px 11px !important;
    gap: 9px !important;
  }

  .bg-report-studio-card .bg-textarea.is-studio-textarea {
    min-height: 120px !important;
  }

  .bg-studio-cus-name {
    max-width: 170px;
  }

  .bg-studio-cus-inbtn {
    padding: 0 9px !important;
    font-size: 0.72rem;
  }

  .bg-studio-files-empty {
    min-height: 118px;
    padding: 14px 12px;
  }

  .bg-studio-modal-triggers {
    gap: 6px;
  }

  .bg-studio-mtrigger {
    height: 40px;
    padding: 0 7px;
    gap: 5.5px;
    font-size: 0.77rem;
    border-radius: 10px;
  }

  .bg-studio-mtrig-ic {
    width: 22px;
    height: 22px;
    border-radius: 6px;
  }

  /* Compact 2-Row Mobile Studio Footer (Add Mode & Edit Mode) */
  .bg-modal-foot.bg-studio-foot {
    padding: 9px 12px calc(10px + env(safe-area-inset-bottom, 0px)) !important;
    gap: 7px !important;
  }

  .bg-modal-foot.bg-studio-foot .dt-btn-ic {
    display: none;
  }

  .bg-modal-foot.bg-studio-foot:has(.is-add-grid) {
    display: grid !important;
    grid-template-columns: auto minmax(0, 1fr) minmax(0, 1fr);
    align-items: center;
  }

  .bg-modal-foot.bg-studio-foot .bg-foot-right.is-add-grid {
    display: contents !important;
  }

  .bg-modal-foot.bg-studio-foot:has(.is-add-grid) .bg-btn {
    height: 38px !important;
    min-width: 0 !important;
    padding: 0 9px !important;
    font-size: 0.76rem !important;
    white-space: nowrap;
    justify-content: center;
  }

  .bg-modal-foot.bg-studio-foot:has(.is-add-grid) .bg-btn.is-studio-cta {
    grid-column: 1 / -1;
    height: 42px !important;
    font-size: 0.86rem !important;
  }

  .bg-modal-foot.bg-studio-foot:has(.is-edit-grid) {
    display: grid !important;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    align-items: center;
  }

  .bg-modal-foot.bg-studio-foot .bg-foot-right.is-edit-grid {
    display: contents !important;
  }

  .bg-modal-foot.bg-studio-foot:has(.is-edit-grid) > .bg-btn {
    grid-column: span 2;
  }

  .bg-modal-foot.bg-studio-foot:has(.is-edit-grid) .bg-studio-clone-btn {
    grid-column: span 4;
  }

  .bg-modal-foot.bg-studio-foot:has(.is-edit-grid) .bg-btn {
    height: 38px !important;
    min-width: 0 !important;
    padding: 0 10px !important;
    font-size: 0.77rem !important;
    white-space: nowrap;
    justify-content: center;
  }

  .bg-modal-foot.bg-studio-foot:has(.is-edit-grid) .bg-btn.is-studio-cta {
    grid-column: 1 / -1;
    height: 42px !important;
    font-size: 0.86rem !important;
  }

  .bg-modal-foot.bg-studio-foot:has(.is-edit-grid):has(.is-studio-cta + .is-studio-cta) .bg-btn.is-studio-cta {
    grid-column: span 3;
  }
}

/* ============================================================================
   V7.8 MOBILE WEEK CALENDAR (3A) & MOBILE MONTH CALENDAR (4) — DUAL-THEME
============================================================================ */
.bg-mcal-week-wrap {
  display: flex;
  flex-direction: column;
  width: 100%;
  min-width: 0;
}

.bg-mcal-week-strip {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
  padding: 8px 9px;
  background: var(--bg-subbar);
  border-bottom: 1px solid var(--bg-border);
  box-sizing: border-box;
}

.bg-mcal-wtab {
  width: 100% !important;
  min-width: 0;
  margin: 0 !important;
  padding: 5px 2px !important;
  border-radius: 10px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-soft-pad-bd);
  color: var(--bg-text-sec);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  cursor: pointer;
  transition: all 0.16s var(--bg-ease);
}

.report-container.page.theme-light-blue .bg-mcal-wtab {
  background: #ffffff;
  border-color: #cbd5e1;
}

.bg-mcal-wtab.is-today {
  border-color: var(--theme-pri-bright);
  box-shadow: inset 0 0 0 1px var(--theme-pri-bd);
}

.bg-mcal-wtab.is-selected {
  background: var(--theme-pri-grad) !important;
  border-color: transparent !important;
  color: #ffffff !important;
  box-shadow: 0 4px 12px -3px var(--theme-pri-shadow);
}

.bg-mcal-wtab-wd {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  line-height: 1.1;
}

.bg-mcal-wtab.is-sun:not(.is-selected) .bg-mcal-wtab-wd {
  color: var(--sem-rose-bright);
}

.bg-mcal-wtab-num {
  font-size: 0.86rem;
  font-weight: 900;
  color: var(--bg-text);
  line-height: 1.15;
}

.bg-mcal-wtab.is-selected .bg-mcal-wtab-wd,
.bg-mcal-wtab.is-selected .bg-mcal-wtab-num {
  color: #ffffff !important;
}

.bg-mcal-wtab-cnt {
  min-width: 16px;
  height: 15px;
  padding: 0 4px;
  border-radius: 999px;
  background: var(--theme-pri-bg);
  color: var(--theme-pri-bright);
  font-size: 0.6rem;
  font-weight: 900;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.bg-mcal-wtab.is-selected .bg-mcal-wtab-cnt {
  background: rgba(255, 255, 255, 0.24);
  color: #ffffff;
}

.bg-mcal-wtab-dot-empty {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--bg-border-strong);
  margin: 5.5px 0;
}

.bg-mcal-wtab.is-selected .bg-mcal-wtab-dot-empty {
  background: rgba(255, 255, 255, 0.5);
}

.bg-mcal-week-agenda {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px;
}

.bg-mcal-day-card,
.bg-mcal-month-agenda {
  border-radius: 14px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-border-strong);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  scroll-margin-top: 14px;
}

.report-container.page.theme-light-blue .bg-mcal-day-card,
.report-container.page.theme-light-blue .bg-mcal-month-agenda {
  background: #f8fafc;
  border-color: #cbd5e1;
}

.bg-mcal-day-card.is-today,
.bg-mcal-month-agenda {
  border-color: var(--theme-pri-bd);
}

.bg-mcal-day-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8.5px 12px;
  background: var(--bg-panel-elev);
  border-bottom: 1px solid var(--bg-border);
}

.bg-mcal-day-card.is-today .bg-mcal-day-head,
.bg-mcal-day-head.is-month-agenda-head {
  background: var(--theme-pri-header-grad);
  border-bottom-color: rgba(255, 255, 255, 0.18);
  color: #ffffff;
}

.bg-mcal-day-title {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  flex-wrap: wrap;
}

.bg-mcal-day-wd {
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.03em;
  color: var(--bg-text);
}

.bg-mcal-day-date {
  font-size: 0.78rem;
  font-weight: 800;
  color: var(--theme-pri-bright);
}

.bg-mcal-day-card.is-today .bg-mcal-day-wd,
.bg-mcal-day-card.is-today .bg-mcal-day-date,
.bg-mcal-day-head.is-month-agenda-head .bg-mcal-day-wd {
  color: #ffffff !important;
}

.bg-mcal-today-pill {
  padding: 1.5px 7px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.38);
  color: #ffffff;
  font-size: 0.64rem;
  font-weight: 800;
}

.bg-mcal-day-total {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-border-strong);
  color: var(--bg-text-sec);
  font-size: 0.69rem;
  font-weight: 800;
  white-space: nowrap;
}

.bg-mcal-day-card.is-today .bg-mcal-day-total,
.bg-mcal-day-head.is-month-agenda-head .bg-mcal-day-total {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.36);
  color: #ffffff;
}

.bg-mcal-day-rems {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px 9px 0;
}

.bg-mcal-day-periods {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 9px;
}

.bg-mcal-period-box {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 8.5px;
  border-radius: 12px;
  background: var(--bg-panel);
  border: 1px solid var(--bg-border);
}

.report-container.page.theme-light-blue .bg-mcal-period-box {
  background: #ffffff;
  border-color: #dbe6f3;
}

.bg-mcal-period-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.bg-mcal-period-left {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.bg-mcal-period-lbl {
  font-size: 0.73rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.bg-mcal-period-box.is-morning .bg-mcal-period-lbl {
  color: var(--sem-sky-bright);
}

.bg-mcal-period-box.is-afternoon .bg-mcal-period-lbl {
  color: var(--sem-amber-bright);
}

.bg-mcal-period-cnt {
  padding: 1px 6.5px;
  border-radius: 999px;
  font-size: 0.67rem;
  font-weight: 800;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-border-strong);
  color: var(--bg-text-sec);
}

.bg-mcal-period-add {
  width: 25px !important;
  height: 25px !important;
  margin: 0 !important;
  padding: 0 !important;
  border-radius: 7.5px;
  color: #ffffff !important;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  cursor: pointer;
}

.bg-mcal-period-box.is-morning .bg-mcal-period-add {
  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%);
  border: 1px solid rgba(125, 211, 252, 0.5);
}

.bg-mcal-period-box.is-afternoon .bg-mcal-period-add {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  border: 1px solid rgba(252, 211, 77, 0.5);
}

.bg-mcal-empty-slot {
  width: 100% !important;
  margin: 0 !important;
  height: 34px !important;
  padding: 0 10px !important;
  border-radius: 9px;
  background: transparent;
  border: 1px dashed var(--bg-border-strong);
  color: var(--bg-text-muted);
  font-size: 0.74rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}

.bg-mcal-empty-slot:active {
  background: var(--theme-pri-bg);
  border-color: var(--theme-pri-bd);
  color: var(--theme-pri-bright);
}

.bg-mcal-card-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.bg-detail-card.is-mcal-card {
  padding: 12px 13px;
  min-height: 98px;
  gap: 8.5px;
}

/* --- Mobile Month Matrix + Selected Day Agenda (4) --- */
.bg-mcal-month-wrap {
  display: flex;
  flex-direction: column;
  gap: 11px;
  padding: 10px;
  width: 100%;
  box-sizing: border-box;
}

.bg-mcal-month-block {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}

.bg-mcal-month-subtitle {
  align-self: flex-start;
  padding: 4px 10px;
  border-radius: 8px;
  background: var(--theme-pri-header-grad);
  color: #ffffff;
  font-size: 0.76rem;
  font-weight: 800;
}

.bg-mcal-month-weekdays {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  border-radius: 10px;
  overflow: hidden;
  background: var(--theme-pri-header-grad);
}

.bg-mcal-mwd {
  padding: 6.5px 2px;
  text-align: center;
  font-size: 0.67rem;
  font-weight: 800;
  color: #ffffff;
  border-right: 1px solid rgba(255, 255, 255, 0.16);
}

.bg-mcal-mwd:last-child {
  border-right: none;
}

.bg-mcal-month-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
  width: 100%;
  min-width: 0;
}

.bg-mcal-mcell {
  width: 100% !important;
  min-width: 0;
  margin: 0 !important;
  min-height: 48px;
  padding: 5px 2px !important;
  border-radius: 9.5px;
  background: var(--bg-soft-pad);
  border: 1px solid var(--bg-border);
  color: var(--bg-text);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 3px;
  cursor: default;
  box-sizing: border-box;
  transition: all 0.15s var(--bg-ease);
}

.bg-mcal-mcell.has-tasks {
  cursor: pointer;
  background: var(--bg-panel-elev);
  border-color: var(--theme-pri-bd);
  box-shadow: inset 0 1px 0 var(--bg-specular);
}

.bg-mcal-mcell.has-tasks:active {
  transform: scale(0.96);
}

.report-container.page.theme-light-blue .bg-mcal-mcell:not(.is-pad) {
  background: #ffffff;
  border-color: #d5e0ee;
}

.report-container.page.theme-light-blue .bg-mcal-mcell.has-tasks {
  background: #f0f9ff;
  border-color: #7dd3fc;
}

.bg-mcal-day-modal-card {
  width: 100vw !important;
  max-width: 100vw !important;
  height: 100dvh !important;
  max-height: 100dvh !important;
  border-radius: 0 !important;
  border: none !important;
  display: flex;
  flex-direction: column;
}

.bg-mcal-modal-title-row {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.bg-mcal-day-modal-body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 12px !important;
}

.bg-mcal-day-modal-foot {
  display: grid !important;
  grid-template-columns: 1.45fr 0.85fr;
  gap: 10px !important;
  padding: 11px 12px calc(11px + env(safe-area-inset-bottom, 0px)) !important;
  border-top: 1px solid var(--bg-border-strong);
  background: var(--bg-panel-elev);
}

.bg-mcal-day-modal-foot .bg-btn {
  width: 100% !important;
  margin: 0 !important;
  height: 42px !important;
  justify-content: center;
  border-radius: 11.5px;
}

.bg-mcal-mcell.is-pad {
  background: transparent !important;
  border-color: transparent !important;
  pointer-events: none;
}

.bg-mcal-mcell.is-today {
  border-color: var(--theme-pri-bright);
  box-shadow: inset 0 0 0 1px var(--theme-pri-bd);
}

.bg-mcal-mcell.is-sun:not(.is-selected) .bg-mcal-mday-num {
  color: var(--sem-rose-bright);
}

.bg-mcal-mcell.is-selected {
  background: var(--theme-pri-grad) !important;
  border-color: transparent !important;
  color: #ffffff !important;
  box-shadow: 0 4px 12px -3px var(--theme-pri-shadow);
}

.bg-mcal-mcell-top {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  max-width: 100%;
}

.bg-mcal-mday-num {
  font-size: 0.78rem;
  font-weight: 800;
  line-height: 1.1;
}

.bg-mcal-mcell.is-selected .bg-mcal-mday-num {
  color: #ffffff !important;
}

.bg-mcal-mday-cnt {
  padding: 0 3.5px;
  border-radius: 999px;
  background: var(--theme-pri-bg);
  color: var(--theme-pri-bright);
  font-size: 0.57rem;
  font-weight: 900;
  line-height: 1.3;
}

.bg-mcal-mcell.is-selected .bg-mcal-mday-cnt {
  background: rgba(255, 255, 255, 0.25);
  color: #ffffff;
}

.bg-mcal-mdots {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 2.5px;
  min-height: 6px;
}

.bg-mcal-mdot {
  width: 5.5px;
  height: 5.5px;
  border-radius: 50%;
}

.bg-mcal-mdot.is-pending {
  background: #fbbf24;
}

.bg-mcal-mdot.is-done {
  background: var(--theme-pri-bright);
}

.bg-mcal-mdot.is-failed {
  background: #fb7185;
}

.bg-mcal-mcell.is-selected .bg-mcal-mdot.is-done {
  background: #ffffff;
}

/* ============================================================================
   CUSTOM GLASSIFY UI MODE (HÒN MUN NHA TRANG WALLPAPER + DYNAMIC GLASS TUNER)
============================================================================ */
.bg-theme-switch-anchor {
  position: relative;
  display: inline-flex;
  align-items: center;
  z-index: 120;
}

.bg-theme-mode-switch {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3.5px;
  border-radius: 999px;
  background: var(--bg-well);
  border: 1px solid var(--bg-glass-border);
  box-shadow:
    inset 0 1px 0 var(--bg-specular),
    0 6px 18px -8px rgba(0, 0, 0, 0.38);
  flex-shrink: 0;
}

.bg-theme-seg-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 29px;
  padding: 0 11px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--bg-text-sec);
  font-size: 0.74rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s var(--bg-ease);
  white-space: nowrap;
}

.bg-theme-seg-btn:hover:not(.is-active) {
  color: var(--bg-text);
  background: rgba(255, 255, 255, 0.08);
}

.bg-theme-seg-btn.is-active {
  background: var(--theme-pri-grad);
  border-color: rgba(255, 255, 255, 0.28);
  color: #ffffff !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.3),
    0 4px 12px -3px var(--theme-pri-shadow);
}

.bg-theme-seg-btn.is-custom-glass.is-active {
  background: linear-gradient(135deg, #06b6d4 0%, #0284c7 52%, #059669 100%) !important;
  border-color: rgba(165, 243, 252, 0.65) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.38),
    0 4px 14px -2px rgba(6, 182, 212, 0.5) !important;
}

.bg-theme-tuner-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 29px;
  height: 29px;
  border-radius: 50%;
  border: 1px solid rgba(165, 243, 252, 0.45);
  background: rgba(6, 182, 212, 0.22);
  color: #e0f2fe;
  cursor: pointer;
  transition: all 0.18s var(--bg-ease);
  flex-shrink: 0;
}

.bg-theme-tuner-btn:hover,
.bg-theme-tuner-btn.is-open {
  background: linear-gradient(135deg, #06b6d4 0%, #10b981 100%);
  border-color: #ffffff;
  color: #ffffff;
  box-shadow: 0 0 12px rgba(6, 182, 212, 0.55);
}

.bg-btn-theme.is-tuner-shortcut.is-active {
  background: linear-gradient(135deg, rgba(6, 182, 212, 0.32) 0%, rgba(16, 185, 129, 0.28) 100%) !important;
  border-color: rgba(165, 243, 252, 0.72) !important;
  color: #ffffff !important;
}

/* --- Custom Glass Tuner Popover (Teleported to body) --- */
.bg-custom-tuner-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000089;
  background: transparent;
}

.bg-custom-tuner-popover {
  position: fixed;
  top: 64px;
  right: 20px;
  z-index: 1000090;
  width: 344px;
  max-height: calc(100dvh - 80px);
  overflow-y: auto;
  padding: 14px;
  border-radius: 18px;
  background: linear-gradient(160deg, rgba(10, 28, 46, 0.90) 0%, rgba(6, 18, 32, 0.94) 100%);
  border: 1px solid rgba(255, 255, 255, 0.36);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.38),
    0 24px 54px -10px rgba(2, 8, 20, 0.78);
  backdrop-filter: blur(26px) saturate(185%);
  -webkit-backdrop-filter: blur(26px) saturate(185%);
  color: #f8fafc;
  display: flex;
  flex-direction: column;
  gap: 12px;
  font-family: 'Plus Jakarta Sans', 'Inter', system-ui, -apple-system, sans-serif;
}

.bg-ct-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 9px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
}

.bg-ct-head-left {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.bg-ct-badge-ic {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  background: linear-gradient(135deg, rgba(6, 182, 212, 0.28) 0%, rgba(16, 185, 129, 0.28) 100%);
  border: 1px solid rgba(165, 243, 252, 0.45);
  color: #67e8f9;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.bg-ct-title {
  font-size: 0.8rem;
  font-weight: 800;
  color: #ffffff;
  line-height: 1.2;
}

.bg-ct-sub {
  font-size: 0.67rem;
  color: #cbd5e1;
  margin-top: 1px;
}

.bg-ct-head-actions {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
}

.bg-ct-reset-btn {
  height: 25px;
  padding: 0 8.5px;
  border-radius: 7px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: rgba(255, 255, 255, 0.1);
  color: #e2e8f0;
  font-size: 0.68rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.bg-ct-reset-btn:hover {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.4);
  color: #ffffff;
}

.bg-ct-close-btn {
  width: 25px;
  height: 25px;
  border-radius: 7px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.08);
  color: #cbd5e1;
  font-size: 0.74rem;
  font-weight: 800;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.bg-ct-close-btn:hover {
  background: rgba(244, 63, 94, 0.28);
  border-color: rgba(251, 113, 133, 0.55);
  color: #ffffff;
}

.bg-ct-sec-label {
  font-size: 0.67rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #94a3b8;
  margin-bottom: 6px;
}

.bg-ct-preset-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}

.bg-ct-preset-btn {
  height: 31px;
  padding: 0 7px;
  border-radius: 9px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.07);
  color: #e2e8f0;
  font-size: 0.7rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  cursor: pointer;
  transition: all 0.16s ease;
  white-space: nowrap;
}

.bg-ct-preset-btn:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.34);
}

.bg-ct-preset-btn.is-active {
  background: linear-gradient(135deg, rgba(6, 182, 212, 0.36) 0%, rgba(16, 185, 129, 0.32) 100%);
  border-color: #67e8f9;
  color: #ffffff;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35);
}

.bg-ct-preset-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.bg-ct-preset-dot.is-frost {
  background: linear-gradient(135deg, #f8fafc 0%, #93c5fd 100%);
  box-shadow: 0 0 6px rgba(255, 255, 255, 0.75);
}

.bg-ct-preset-dot.is-ocean {
  background: linear-gradient(135deg, #0284c7 0%, #0f172a 100%);
  border: 1px solid rgba(125, 211, 252, 0.7);
}

.bg-ct-preset-dot.is-clear {
  background: rgba(255, 255, 255, 0.25);
  border: 1.5px solid #67e8f9;
}

.bg-ct-sliders-stack {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.bg-ct-slider-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.bg-ct-slider-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.bg-ct-slider-lbl {
  font-size: 0.72rem;
  font-weight: 700;
  color: #f1f5f9;
}

.bg-ct-slider-val {
  font-size: 0.72rem;
  font-weight: 800;
  color: #67e8f9;
  padding: 1px 6px;
  border-radius: 6px;
  background: rgba(6, 182, 212, 0.16);
  border: 1px solid rgba(103, 232, 249, 0.3);
}

.bg-ct-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    #06b6d4 0%,
    #10b981 var(--range-pct, 45%),
    rgba(255, 255, 255, 0.18) var(--range-pct, 45%),
    rgba(255, 255, 255, 0.18) 100%
  );
  outline: none;
  cursor: pointer;
}

.bg-ct-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #ffffff;
  border: 2px solid #06b6d4;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.45);
  cursor: grab;
  transition: transform 0.12s ease;
}

.bg-ct-range::-webkit-slider-thumb:active {
  transform: scale(1.16);
  cursor: grabbing;
}

.bg-ct-range::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #ffffff;
  border: 2px solid #06b6d4;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.45);
  cursor: grab;
}

.bg-ct-slider-hints {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.62rem;
  color: #94a3b8;
}

.bg-ct-wallpaper-section {
  padding-top: 4px;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
}

.bg-ct-wp-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 6px;
}

.bg-ct-wp-btn {
  height: 30px;
  padding: 0 8px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.08);
  color: #e2e8f0;
  font-size: 0.7rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.bg-ct-wp-btn:hover {
  background: rgba(255, 255, 255, 0.16);
  border-color: rgba(255, 255, 255, 0.36);
}

.bg-ct-wp-btn.is-active {
  background: rgba(6, 182, 212, 0.25);
  border-color: #67e8f9;
  color: #ffffff;
}

.bg-ct-wp-url-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.bg-ct-wp-url-input {
  flex: 1 1 auto;
  min-width: 0;
  height: 29px;
  padding: 0 9px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(4, 15, 28, 0.55);
  color: #ffffff;
  font-size: 0.7rem;
  outline: none;
}

.bg-ct-wp-url-input::placeholder {
  color: #94a3b8;
}

.bg-ct-wp-url-input:focus {
  border-color: #38bdf8;
}

.bg-ct-wp-apply-btn {
